window.__D("text/igrot-rebbe/c022",{"p":[[1200830008,"ב'תרכט\n\n<p>ב\"ה, ד' אייר, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ג והרה\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמוה\"ר יצחק שי' הכהן</p>\n<p> שלום וברכה!</p>\n<p>בנועם קבלתי מכתבו מח' למ\"ט מונים בו כותב ע\"ד התועדות דחג הפסח ותוכן דבורו אז, ויה\"ר מהשי\"ת אשר לאיוש\"ט ימשיך בהשפעתו על סביבתו לקרב את לבם לתורה ולמצות ולמאור שבתורה זוהי פנימיות התורה אשר מובן שזה מוסיף ג\"כ בפנימיות החיות בגשמיות כי הרי אצל איש הישראלי הגשמיות והרוחניות יחד ילכו ובמילא נתוסף ג\"כ בחיצוניות חיות הגוף, וכידוע דאשתו כגופו דמיא ה\"ז מוסיף תוספת בריאות גם בהנוגע לאשתו של אדם והשי\"ת יצליחו לבשר טוב גם בזה.</p>\n<p>בטח מקבל ג\"כ קונטרסים כבקשתו ובודאי תהי' עינו טובה בשל אחרים לזכותם בתוכנם של הקונטרסים גם אותם.</p>\n<p>בברכה לאריכות ימים ושנים טובות ולהוסיף אומץ בהרמת קרן ישראל סבא מתוך בריאות הנכונה והרחבת הדעת.</p>\n<h4><i><b>ב'תרכט</b></i></h4>\n<p><b> מוה\"ר יצחק:</b> הוברמן, אגרת נוספת אליו -לעיל ח\"ו א'תשלב.</p>"],[1200830009,"ב'תרל\n\n<p>ב\"ה, ד' אייר, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>... וזאת להעיר אשר כיון שיש כמה תלונות מהמורים והמורות, כדאי הי' לחשוב ע\"ד הצעה שבהנהלה יכנס בא כח המורים עכ\"פ בתור מייעץ בענינים הקשורים עם המורים. ואחכה לבשו\"ט בכל הנ\"ל.</p>\n<p>בברכה.</p>"],[1200830010,"ב'תרלא\n\n<p>ב\"ה, ד' אייר, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמוה\"ר זלמן טובי' שי' הכהן</p>\n<p> שלום וברכה!</p>\n<p>זה עתה נתקבל מכתבו מכ\"ד ניסן, ובודאי יוסיף אומץ בעבודתו בקדש ברשת אהלי יוסף יצחק ליובאוויטש אשר באה\"ק ת\"ו ככל האפשרי, והרי כבר ראה במוחש אשר אם רק מתעסקים במוסדות אלו, הנה נשיאנו כ\"ק מו\"ח אדמו\"ר מעורר ר\"ר ונשפעת הצלחה מופלגה לאותם המקומות שהם מתעסקים בהם אבל כיון שאין פתיחה כחודה של מחט הרי אין וכו', וכאשר יטיל עצמו בהעבודה כדבעי הרי תהי' העבודה בהצלחה, ואין להתפעל ממה שבתי ספר אחרים יש להם רהיטים וכו' ובהשתדלות הראוי' הרי לאט לאט יתוסף גם זה, כיון שבבתי ספר אהלי יוסף יצחק ליובאוויטש הענינים הפנימיים יהיו מסודרים. ובלי ספק אשר התעסקות זו תמשיך ג\"כ תוספת ברכה והצלחה בענינים הפרטים שלו ושל זוגתו וילידי' שיחיו ואחכה לבשו\"ט.</p>\n<p>בברכת הצלחה בכל הנ\"ל.</p>\n<h4><i><b>ב'תרלא</b></i></h4>\n<p><b> מוה\"ר זלמן טובי' שי':</b> אבלסקי, אגרות נוספות אליו - לעיל ח\"ו א'תתטו, ובהנסמן בהערות שם.</p>"],[1200830011,"ב'תרלב\n\n<p>ב\"ה, ד' אייר, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>זה עתה נתקבל מכתבו מר\"ח אייר בו כותב אשר לפ\"ע הזמן והמצב הצליח בשליחותו במדינת... ולפלא שאין כותב יותר פרטים ובכל אופן בודאי יודע ושמע על הוראת כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע לשד\"רים צו קלייבען גשמיות און זייהען - לזרוע - רוחניות אשר מלשונו זה מובן שהא בהא תליא.</p>\n<p>מה שכותב אשר יש רופאים מייעצים לנתח את השקדים של... שי' ומחכים לקריאה מהרופא לעשות הנתוח. הנה בטח קודם שיעשו ישאלו את דעתו עוד הפעם כיון שתלוי זה במצב האויר בעת ויום שאומרים שצריך להסיר השקדים נוסף על מה שכמה רופאים אין דעתם כ\"כ בהחלט לנתח שקדים כמו שהי' בשנים שעברו, ואיך שיהי' יה\"ר מהשי\"ת שיהי' בשעה טובה ומוצלחת ויגדלוהו לתורה ולחופה ולמעשים טובים.</p>\n<p>בהנוגע לעניני פרנסתו. הנה בכלל צריך להשתדל בכל תוקף שתהי' גם הפרנסה בגשמיות קשורה עם עבודה בכרם חב\"ד, שמלבד שזה קרוב יותר ללבם של אנ\"ש אם ביודעים או בלא יודעים ובמילא העבודה בהצלחה יותר, הנה גם מצד רוחנית הדבר מובן כי נשיאנו הק' הם המשפיעים לתלמידי' ולאנ\"ש בכלל כל השפעות הנצרכים להם וע\"ד מה שנאמר במשה רבנו מאין לי בשר וכו' שלא הי' זה במדריגתו כלל כמבואר בלקו\"ת ובמילא הוכרחה השפעת הבשר להיות באמצעית השבעים זקנים, אבל בכ\"ז רק ע\"י משה רבנו.</p>\n<p>וכשהפרנסה קשורה בכרם חב\"ד הרי הצד הרוחני והגשמי מסייעים זל\"ז. ומה שכותב שעסקנותו עד עתה בכרם חב\"ד מזיקה לבריאות כו' הרי בטח יש לסדר באופן שלא ללכת בהקצוות, היינו אם לעשות נסיעות הרי אין זה מוכרח להיות כל השנה או רובה אבל לאידך גיסא שלא למשוך את ידו מזה לגמרי, והשי\"ת ימציא לו פרנסתו ופרנסת ב\"ב שיחיו בהרחבת הדעת ויוסיף אומץ גם בכמות בהפצת המעיינות חוצה ובלימוד הנגלה וחסידות גם לעצמו.</p>\n<p>בברכה.</p>"],[1200830012,"ב'תרלג\n\n<p>ב\"ה, ד' אייר, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>עס איז מיר אנגעקומען א פ\"נ בקשת ברכה פאר אייך און אייער פאמיליע שיחיו, און ווען איך וועל זיין אויף דעם ציון הק' פון מיין שווער כ\"ק אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, וועל איך לייענען דעם פ\"נ, און זיכער וועט ער מעורר זיין רחמים רבים פאר יעדערן וועלכען איר דערמאנט אין דעם פ\"נ דעם וואס ער נויטיגט זיך.</p>\n<p>זיכער איז איבעריג צו אויפמערקזאם מאכען אז בכדי צו אויפנעמען די ברכות פון השם יתברך יעדערער אין זיין ענין, דארפמען מאכען די פאסענדע כלים צו דעם וואס דאס זיינען די ענינים פון תורה ומצות. און וויבאלד הקדוש ברוך הוא מאנט דאס פון יעדער אידן, איז זיכער אז ער - ברוך הוא - האט געגעבען די מעגליכקייט און די כחות אויף צו מקיים זיין דאס. און עס ווענדעט זיך נאר אן דעם גוטען ווילען פון יעדער איינעם באזונדער. און עס איז פארשטאנדיק אז דער געדאנק אז אמעריקא איז אנדערש איז דאס א דיעה פון כפירה ר\"ל. און דער וועלכער גלויבט, אז הקב\"ה איז דער באשעפער פון דער גאנצער וועלט און איז דער בעל הבית פון דער <b>גאנצער</b> וועלט, וואס בא אידען מאמינים בני מאמינים איז דאך בא זיי ניטא קיין שום ספק אין דעם, און אויב אפילו אז אויף א קליינע צייט פארגעסטן אויף דעם, דערמאנט דער נפש האלקית וועלכע איז פראן בא יעדער אידען, וועגען דעם. און ווען מען הערט זיך נאר צו העלפט השי\"ת אז מען קומט איבער די פארפירעניש פון דעם יצר הרע און מען פירט זיך אויף ווי א איד דארף זיך אויפפירען, וואס נאר דענסטמאל קען מען זיין זיכער צו באגליקט ווערען סיי בגשמיות און סיי ברוחניות. און השי\"ת זאל אייך העלפען צו האבען אמת'ן נחת פון אלע אייערע קינדער און אייניקלעך און אויפנעמען דאס מיט גוטען געזונט בגשמיות וברוחניות.</p>\n<p>בברכה,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>\n<p>נ.ב.</p>\n<p>זיכער זאגט איר תהלים יעדער טאג נאכן דאוונען און גיט אויך א פאר מאל א וואך אויף צדקה לכל הפחות עטליכע סענט והשי\"ת יצליחו.</p>\n<h4><i><b>ב'תרלג</b></i></h4>\n<p><b> אז אמעריקא איז אנדערש</b><b>:</b> ראה לקמן אגרת ב'תתקלט, ובהנסמן בהערות שם.</p>"],[1200830013,"ב'תרלד\n\n<p>ב\"ה, ד' אייר, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>זה עתה נתקבל הפ\"נ שלו אודות זוגתו הרבנית מרת... תחי' וכשאהי' על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע אזכירה לרפואה קרובה ויה\"ר מהשי\"ת אשר יבשר טובות בזה.</p>\n<p>ובודאי לדכוותי' אך למותר להעיר על מרז\"ל שמדתו של הקב\"ה מדה כנגד מדה וכשמוסיפים בבריאות מושפעיו היינו סביבתו וקהלתו בריאות ברוחניות ע\"י קירוב לבם יותר ויותר לאבינו שבשמים הרי הקב\"ה מוסיף בריאות הגשמי והרוחני (אשר אצל איש הישראלי יחד ילכו והא בהא תליא) בהמצטרך לו ולאשתו דאשתו כגופו דמיא וזהו נוסף על ענין זה שגדול ערכו בפ\"ע וכמובא הביאור במרז\"ל שכר מצוה מצוה, אשר עצם היכולת לעשיית המצוה בפועל זהו שכר היותר גדול שנברא יכול לקבל בחסד חנם של הקב\"ה המאפשר לאדם קרוץ מחומר למלאות רצון ממה\"מ הקב\"ה בכבודו ובעצמו.</p>\n<p>בכבוד ובברכה לבשר טוב בכל הנ\"ל.</p>"],[1200830014,"ב'תרלה\n\n<p>ב\"ה, ו' אייר, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמוה\"ר שניאור זלמן אליעזר שי'</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מכ\"ג ניסן, בו מעיר על מ\"ש בתניא בחנוך לנער במוסגר, ומצות החינוך היא ג\"כ במ\"ע כמ\"ש בא\"ח סימן שמ\"ג.</p>\n<p>הנה בהנ\"ל <b>מצ</b><b>\"</b><b>ע</b> יש לפרש מ\"ש ג\"כ במ\"ע בשני אופנים. שההדגשה היא על התיבות במ\"ע, היינו ומכש\"כ במל\"ת (אשר כן הם דברי רבנו הזקן בשולחנו הטהור סי' שמ\"ג) או שההדגשה היא על התיבות ג\"כ וקאי אדלעיל מני', שכמו שהאהבה היא שרש ויסוד למ\"ע הרי מצות החינוך היא ג\"כ במ\"ע (כי הרי <b>אין</b> נוגע כאן אם מצות החינוך היא במצות ל\"ת או לא), ואז מובן יותר בפשטות התיבה כן, כי לפירוש הראשון הי' מספיק שיא[מ]ר גם במ\"ע, ומסיום ההקדמה, אך עיקרה מאהבה שנתחנך וכו' מובן פירוש מאמר המוסגר הנ\"ל שרוצה להדגיש שבאהבה ישנה ג\"כ מצות החינוך.</p>\n<p>ובזה יומתק עוד כי בכלל מאמרים המוסגרים הרי מובן שמוסיפים דבר שאינו עיקרי כ\"כ בהבנת הענין וה\"ה בנדון דידן, כי הכתוב חנוך לנער אין פירושו דוקא קודם שנעשה גדול במצות ואדרבה (ראה קידושין ל' ע\"א) משיתסר כו' מתמניסרי כו' (בדא\"ג יש להעיר אשר בהל' ת\"ת פרק א' סעיף ט' לרבנו הזקן לכאורה ארכבי' אתרי רכשי.</p>\n<p>ואכ\"מ) ומוסיף במאמר המוסגר שיש לפרש הכתוב גם כפשוטו בזמן שיש למצוה החינוך היינו בגיל חינוך ממש וק\"ל.</p>\n<p>והנה יש להעיר עוד בהמשך להנ\"ל דלכאורה מתחיל בשרשי עבודת ה' דו\"ר ומסיים רק באהבה (ואין זה שייך להנ\"ל כי גם היראה היא מצות עשה) ויש לפרש זה ע\"פ המבואר בכ\"מ אשר באהבה נכלל ג\"כ דחילו, ולא רק באהבה המסותרת כמבואר בתניא פי\"ח אלא גם באיזה אהבה שתהי' כי מפני האהבה ירא למרות רצונו וכמ\"ש גם כאן כי האהבה היא יסוד ושרש לקיום כל מ\"ע אשר גם היראה נכללה.</p>\n<p>במה שהעיר בחילוק דעת התוס' אם ישנו לחינוך במצות ל\"ת, בטח יעיין בב\"ח לאו\"ח סימן שמ\"ג.</p>\n<p>במה שהעיר בלוח התיקון בדרך אפשר במה שתקנתי בנוגע לד' יסודות שצ\"ל ארבעה (להעיר ג\"כ מה' יסוה\"ת להרמב\"ם פרק ד') ומוסיף שעפ\"ז יש לתקן ג\"כ בפרק ז' ועד\"ז מאחת לאחד בדף ט\"ו.</p>\n<p>הנה כן הוא והן מההשמטות בלוח התיקון מפני החפזון בעריכת הדפוס. וכמו שנתוספו ג\"כ איזה ענינים בין ההו\"ל דתניא בפורמט הרגיל לההו\"ל בפורמט כיס, ועוד כמה תיקונים נשארו שלא נכנסו גם בהאחרון ועוד חזון למועד.</p>\n<p>מזכיר במכתבו כת\"י של התניא מהדו\"ק, ומטובו להודיעני בהקדם יותר פרטים אודותו וכן אפשריות להשיגו על משך איזה זמן ות\"ח מראש.</p>\n<p>בברכה.</p>\n<h4><i><b>ב'תרלה</b></i></h4>\n<p><b> מוה\"ר שניאור זלמן אליעזר</b><b>:</b> גורביץ</p>\n<p><b> החינוך... במ</b><b>\"</b><b>ע</b><b>:</b> ראה גם לעיל ח\"ח אגרת ב'שלה ס\"ו. הערת כ\"ק אדמו\"ר שליט\"א בפלח הרמון ע\"ס בראשית ע' 294.</p>\n<p><b> ארכבי' אתרי רכשי:</b> ראה גם לעיל ח\"ב אגרת רמו.</p>"],[1200830015,"ב'תרלו\n\n<p>ב\"ה, ז' אייר, תשי\"ד</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ עוסק בצ\"צ מוה\"ר יוסף שי'</p>\n<p> שלום וברכה!</p>\n<p>בנועם הנני מאשר קבלת מכתבו מד' אייר עם המוסגר בו ההמחאות לכולל חב\"ד באה\"ק ת\"ו שנשלחים ימים אלו למטרתם, ונהניתי גם מזריזותו דמר בשילוח הנ\"ל מבלי לחכות על השאר.</p>\n<p>ומה נפלאו דברי רבנו הזקן בנוגע לענין העקדה מאורע המשמש דוגמא וסמל לא רק לבני ישראל אלא גם לאו\"ה ועמא דבר מפרש תוכן הענין שאב זקן מוסר לעקדה את בנו יחידו על פי ציוויו של הקב\"ה. ובא רבנו הזקן ומעמיק לבאר שלא זהו פנימיות הדברים, ובלשונו הק' \"העקדה עצמה אינה נחשבה כ\"כ לנסיון גדול לערך מעלת אברהם אבינו ע\"ה בשגם כי ה' דיבר בו קח נא את בנך כו' רק שא\"א ע\"ה עשה זאת בזריזות נפלאה להראות שמחתו וחפצו כו' וממנו למדו רז\"ל לקיום כל המצות בכלל ובפרט מעשה הצדקה העולה על כולנה\" (עיין אגרת הקדש סי' כ\"א) ומזה מובנת מעלת הזריזות אשר עוד יותר גדולה רבה ונפלאה היא אפילו ממעלת העקדה, והאריכות לדכוותי' בודאי אך למותר.</p>\n<p>מכתבי הקודם בטח קיבל במועדו.</p>\n<p>בברכת הצלחה בכל עניניו.</p>\n<h4><i><b>ב'תרלו</b></i></h4>\n<p><b> מוה\"ר יוסף:</b> פלייער, אגרות נוספות אליו - לעיל ח\"ח ב'של, ובהנסמן בהערות שם.</p>\n<p><b> ומה נפלאו כו</b><b>':</b> ראה גם לקמן אגרת ב'תתכז.</p>"],[1200830016,"ב'תרלז\n\n<p>ב\"ה, ז' אייר, תשי\"ד</p><p>ברוקלין.</p>\n<p> ברכה ושלום!</p>\n<p>מיט אייניגע וואכען צוריק האט השי\"ת געוויזען זיין חסד אין דעם וואס עס האט געטראפען מיט אייך וואס מען קען דאס אנרופען מיטן נאמען <b>נס</b> נארמאלערהייט דארף דאס ארויסרופען דאנקבארקייט צו השי\"ת וועלכער איז דער רופא כל בשר ומפליא לעשות. און דער דאנק דארף זיך אויסדריקען אין דעם וועג וואס <b>השי\"ת</b> וויל, און זיין ווילען איז דייטליך אנגעזאגט געווארען צו אלע אידען אן אונטערשייד פון מאן און פרוי אין זיין הייליקער תורה. און דעריבער האב איך געהאפט אז דאס וועט ערוועקען בא אייך א ווילען צו אנטאן א גאנצען פארוק-שייטעל; וואס מיט דעם איז מען מקדש השם <b> ברבים,</b> און אויב עס דאכט אז עס איז שווער, איס דאך דער דאנק אויסדרוק צו השם יתברך דערמיט נאך גרעסער, במילא דארפמען דאס טען נאך מיט מער שמחה.</p>\n<p>איך האב אויך געהאפט אז אויך בנוגע צו אנדערע וועט זיך אויסדריקען אייער דאנקבארקייט צו השי\"ת לויט ווי ער - ברוך הוא - פאדערט אין זיין תורה הק' צו איינווירקען אויך אויף אייער אומגעבונג אז זיי זאלען זיין מער אידישער און בפרט אין זאכען וועלכע ווערן געטאן בפרהסיא, ד.ה. אז מערערע מענשן זעהען דאס.</p>\n<p>עס האט מיר דעריבער זייער געוואונדערט דער קלאנג וואס האט דערגרייכט צו מיר, אז דער <b>נס</b> וואס האט פאסירט מיט אייך, איז אנגענומען געווארען ווי א נארמאלע ערשיינונג, און ניט נאר אז דאס האט ניט מיטגעבראכט קיין דאנקבארקייט און אנערקענונג פון חסד השי\"ת צו ווערען אליין ווארימער און נעהענטער צו אידישקייט, נאר מען ניצט נאך אויס דעם איינפלוס וואס מען האט אויף נאהענטע אז זיי זאלען זיך געגען שטעלען דעם שולחן ערוך, אז ווען מען גייט חתונה מאכען א טאכטער וואס א חתונה איז דאס א פונדיישאן אויף דעם גאנצען לעבען, זאל מען וועלען טאן דאס פארקערט ווי עס זאגט השם יתברך אין זיין שולחן ערוך. און מורא האבענדיק טאמער וועט די כלה אליין יע וועלען טאן ווי דער שולחן ערוך הייסט, זוכט מען צו איינווירקען אויף די עלטערען אז זיי זאלען טאן פארקערט פון דעם שולחן ערוך, און דאס איז די דאנקבארקייט נאך דעם נס וואס השי\"ת האט געטאן.</p>\n<p>איך וויל האפען אז דער קלאנג איז ניט ריכטיג און עפעס שטימט ניט. אבער אזוי ווי דער קלאנג איז אנגעקומען צו מיר און יעדער זאך איז דאך בהשגחה פרטית, געפין איך פאר מיין חוב צו שרייבען די אויבענדערמאנטע שורות און איך האף אז איך וועל באקומען פון אייך א גוטע בשורה, אז איר האט שוין אנגעטאן א פולען פארוק אמווייניגסטן פון היינט אן און ווייטער לויטן מנהג פון אידישע כשר'ה טעכטער און אויך אז איר נוצט אויס אייער איינפלוס צו איינווירקען אויף אייער סביבה בכלל אויף אויף אייער נאהענטע בפרט אז זיי זאלן זיך אויפפירען לויט ווי דער שולחן ערוך ווייזט אן און השם יתברך זאל אייך באגליקען.</p>\n<p>בברכה,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>\n<h4><i><b>ב'תרלז</b></i></h4>\n<p><b> שייטל:</b> ראה גם לעיל ח\"ז אגרת א'תתצב, ובהנסמן בהערות שם. ח\"ח אגרות ב'תלד.</p>\n<p>ב'תסג. ב'תקנה.</p>"],[1200830017,"ב'תרלח\n\n<p>ב\"ה, ז' אייר, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מה' אמור אשר קרא שם בנם הנולך להם... שי'. הנה יה\"ר מהשי\"ת שכשם שהכניסוהו לברית כן יכניסוהו לתורה ולחופה ולמעשים טובים.</p>\n<p>ומה שכותב בענין סגולה, הנה יבדקו המזוזות בביתם שיהיו כולן כשרות וכן את התפילין שלו, ובודאי מניח או עכ\"פ יניח מעתה תפילין דרבנו תם ובמילא יבדוק גם אותם, והוא וזוגתו שיחיו יפרישו בכל יום שני וחמישי בבקר איזה פרוטות לצדקה נוסף על מה שבודאי זוגתו תחי' מפרישה לצדקה קודם הדלקת הנרות בכל עש\"ק וערב יום טוב. והרי צדקה סגולה היא שמגינה בפני כל וכמ\"ש וילבש צדקה כשריון וידוע דרז\"ל על זה שנתבארה גם כן באגרת הקדש לרבנו הזקן סי' ג'. והשי\"ת יזכהו לבשר טוב תכה\"י.</p>\n<p>בברכת מז\"ט.</p>"],[1200830018,"ב'תרלט\n\n<p>ב\"ה, ז' אייר, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ מוה\"ר<br>\nדוד שי'</p>\n<p> שלום וברכה!</p>\n<p>איך האב באקומען אייער בריף פון ח\"י לעומר בקשת ברכה פאר הרב... שי', און ווען איך וועל זיין אויף דעם ציון הק' פון כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע וועל איך עם מזכיר זיין לרפואה קרובה.</p>\n<p>אבער איר דארפט עם ערקלערען, און זיכער וועט איר געפינען די פאסענדע ווערטער צו דעם, אז די נשיאים רבותנו הק' האבען מערערע מאל געזאגט אז דער פארבונד מיט זיי איז דורך זייער תורה, וכמאמר אסתכל באורייתא וברא עלמא, וואס די כוונה איז אויף דעם עולם בכללות, איז אין דעם נכלל אויך דעם עולם קטן וואס איז דער אדם, במילא וואלט ער באדארפט גלייך באשליסען, און דערנאך אויך טאן צו האבען א קביעות אין לערנען די תורת הנשיאים וועלכע איז א חלק פון תורתנו הק' וועלכע איז געגעבען למשה מסיני, און זאל אנהויבען פון לערנען תניא, וואס זיכער וועט איר קענען מייעץ זיין עם אין דעם,</p>\n<p>ויהי רצון אז לאריכות ימים ושנים טובות זאל הרב הנ\"ל לערנען תורת הנגלה ותורת החסידות...</p>\n<p>בברכה המחכה לבשו\"ט.</p>\n<h4><i><b>ב'תרלט</b></i></h4>\n<p><b> מוה\"ר דוד:</b> טננהויז.</p>"],[1200830019,"ב'תרמ\n\n<p>ב\"ה, ז' אייר, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ מוהר\"ש<br>\nשי'</p>\n<p> שלום וברכה!</p>\n<p>... מ\"ש אודות השתתפות בספר וויטעבסק שמתכוננים להו\"ל באה\"ק ת\"ו ואחיו ברצונו להשתתף במאמר אודות פעולת חב\"ד שמה.</p>\n<p>הנה לדעתי נכון הדבר, אלא שבהתאם לשאר המשתתפים ואופי הכללי של</p>\n<p>הספר - תלוי אם השתתפותו תהי' בגלוי (ביחד עם מי מעסקני אנ\"ש שם ומהחסידים) או לא. ואם ספק בדבר, והרי לפי המצב שם, אי אפשר להיות בטוח שיהי' הספר כדבעי עד שיודעים שמות אנשי חברי המערכת, אז האחריות קטנה יותר כשבא על החתום איש שאינו מעסקני חב\"ד, ולכן הצעתי שיכתוב לאנ\"ש באה\"ק ת\"ו היודעים אודות תולדות וויטעבסק בהנוגע לחב\"ד, שהם יעמדו שם בקישור עם אחיו שי', ויסדרו הדברים בהתאם להנ\"ל. מובן שיכול לכתוב לאנ\"ש שעושה זה ע\"פ הצעתי.</p>\n<p>נוסף על זה - יעורר את אחיו שישגיחו שידפיסו את הדברים בלי סילוף, כי, בכללות, הדבר נכון הוא, וכנ\"ל...</p>\n<p>המחכה לבשו\"ט וחותם בברכת הצלחה בגו\"ר.</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ב'תרמ</b></i></h4>\n<p><b> מוהר\"ש שי</b><b>':</b> מטוסוב. אגרות נוספות אליו - לעיל ח\"ח ב'רעג, ובהנסמן בהערות שם.</p>\n<p>לקמן ב'תרפו.</p>\n<p><b> השתתפות בספר וויטעבסק:</b> ראה גם לעיל ח\"ח אגרת ב'שכט.</p>"],[1200830020,"ב'תרמא\n\n<p>ב\"ה, ח' אייר, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ מוהרנ\"ן<br>\nשי'</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מב' אייר, ות\"ח על הבשו\"ט אשר הבחינה של התלמידים הראתה אז זיי לערנען גאנץ גוט ובודאי גם בענינים דיראת שמים... והשי\"ת יצליחו ויצליחם שע\"י פתיחה שהיא בערך דלמטה כחודה של מחט יפתחו מלמעלה כפתחו של אולם שגם בערך דלמעלה נקרא זה כפתחו של אולם...</p>\n<p>בודאי למותר לעוררו על ההכרח הגמור להתחיל בעוד מועד במרץ שיבואו תלמידים ללמוד בימי הוואקאנס ואולי באפשר גם קודם לזה וכן בנוגע לתלמידות דבית רבקה אם יכול לזרזם בזה בטח יעשה אף שכתבתי להם גם באופן ישר, ואל יהי הדבר קל בעיניו כי מלבד פתגם הבעש\"ט הידוע שבשביל פעולה אחת טובה בגשמיות או ברוחניות לאדם אחד כדאית ירידת הנשמה למטה למשך ע' פ' שנה ועומק הענין מתבאר עפמ\"ש רבנו הזקן בתניא סוף פרק כ\"ה ויחוד זה למעלה הוא נצחי לעולם ועד, הנה בודאי כשישתדלו במרץ הראוי חלק חשוב מהבאים לוואקאנס ימשיכו גם אחרי כן בדרכי התורה והמצוה וחלק מהם גם בלימודם בכותלי תו\"ת ואחכה לבשו\"ט בכל הנ\"ל ובענין זה ביחוד.</p>\n<p>ואתאפק לא אוכל להביא תמהוני ופליאתי ביותר והוא:</p>\n<p>מובן ע\"פ המובא בכ\"מ בדא\"ח ובפרט בהענין דתמיהת משה רבנו מאין לי בשר כי לא הי' זה במדריגתו כלל ואעפ\"כ אף שטענתו חזקה היתה והראי' שאמרו לו אספה לי שבעים איש וגו' הרי בכ\"ז גם השפעת הבשר היתה על ידו (אלא שהי' גם ממוצע בדבר) שמזה מובן שכל השפעות המקושרים והחסידים צריכה להיות קשורה באיזה אופן שהוא עם נשיאם וכו' מוכרח מזה שדורנו שזכה שכ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע הוא מנהיגו ורועו, הרי כל הענינים צריכים להיות קשורים באיזה אופן שהוא עמו ועאכו\"כ שכן צריך להיות אצל אנ\"ש והתמימים וב\"ב שיחיו ועאכו\"כ שכן צ\"ל בענינים הקשורים בתומ\"צ ובפרט בענינים הכללים שבהם ובפרטיות - בענינים הקשורים באמונה וכמ\"ש ויאמינו בה' ובמשה עבדו ואיתא במכילתא שכל מי שמאמין ברועה נאמן כאילו מאמין במאמר מי שאמר והי' העולם. ולכן גדלה תמיהתי כשנודע לי אשר דוקא במיכלא דמהימנותא הנה חלק מאנ\"ש בחרו לקבלו ממקום אחר בה-בשעה שהיתה אפשרית לקבלו ע\"י לשכה שנתיסדה מכ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע אשר פעולות צדיק עומדים לעד ובמילא גם עתה היא לשכתו.</p>\n<p>בטח יש ע\"ז איזה תירוצים ואולי גם תירוצים חזקים שאפשר הי' ביוקר או שלא היו אפויות טוב כ\"כ או שהי' איזה פירוד לבבות בין מוכר הנ\"ל ואנ\"ש או שכמו שאמרו אחרים שזהו רק בשביל ב\"ב משא\"כ הם בעצמם (וכאילו אפשר לחלק באמונה בין הגדול בישראל להקטן בישראל ובפרט בהנוגע לחג המצות שזהו <b>קטנות</b> אבא והמשל ע\"ז הוא <b> מתינוק</b> אוכל מאכל דגן), אבל אחרי כ\"ז תמיה בעיני, איז כדאי איינצושטעלען עוד ענין של קישור עם כ\"ק מו\"ח אדמו\"ר? ולו יהי' שזה רק בספק ספיקא בשביל ענינים שגם הם מידי ספק לא יצאו ולקבל מצה שמורה מיכלא דמהימנותא במקום אחר.</p>\n<p>- כיון שאיני רוצה לפרש בשם מי שעשה כנ\"ל לכן כותב הנני הדברים אליו כיון שבודאי הוא ומושפעיו לקחו שמורה דוקא מהבעקעריי הקשורה עם הלשכה, ובמילא בנקל יותר יהי' לו לבאר הדברים בעת התועדות כיד ה' הטובה עליו, ובודאי ידוע גם בצרפת פתגם כ\"ק מו\"ח אדמו\"ר, אז אונזערע זיבורית טוב מעידית שלהם. והשי\"ת יזכנו ויצליח את כאו\"א להמשיך המשכות דפסח על כל השנה בגלוי בחיי היום יומים.</p>\n<p>בברכה.</p>\n<h4><i><b>ב'תרמא</b></i></h4>\n<p><b> מוהרנ\"ן:</b> מוה\"ר ניסן נמנוב. אגרות נוספות אליו - לעיל ח\"ח ב'רעח, ובהנסמן בהערות שם. לקמן ב'תרחצ. ב'תשלז*. ב'תתכד. ב'תתנו. ב'תתס. ב'תתקכח.</p>\n<p><b> התלמידים:</b> בישיבת תו\"ת בצרפת.</p>\n<p><b> בימי הוואקאנס</b><b>:</b> ראה גם לקמן אגרת ב'תרעו.</p>\n<p><b> דבית רבקה... שכתבתי</b><b>:</b> ראה לקמן אגרת ב'תתב.</p>\n<p><b> פתגם הבעש</b><b>\"</b><b>ט</b><b>:</b> ראה גם לעיל ח\"ח אגרת ב'ערה, ובהנסמן בהערות שם. לקמן ב'תרנה.</p>\n<p><b> מאין לי בשר</b><b>:</b> ראה גם לעיל אגרת ב'תרלב.</p>\n<p><b> גדלה תמיהתי</b><b>:</b> ראה גם לקמן אגרות ב'תרעט. ב'תשעד.</p>\n<p><b> לשכה</b><b>:</b> לעזרת הפליטים באירופה.</p>\n<p><b> פתגם כ\"ק מו\"ח אדמו</b><b>\"</b><b>ר</b><b>:</b> ראה גם לעיל ח\"ג אגרת תרעג. ח\"ז ב'רג.</p>"],[1200830021,"ב'תרמב\n\n<p>ב\"ה, ח' אייר, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ג והרה\"ח הוו\"ח אי\"א נו\"מ רב פעלים<br>\nלתומ\"צ<br>\nצמ\"ס וכו' מוהר\"ר חנני' יום טוב ליפא שי'</p>\n<p> שלום וברכה!</p>\n<p>בנועם קבלתי ספריו טהרת יו\"ט - ה' חלקים - וכן הידיעה אשר הולך ומדפיס חלק ששי מספריו.</p>\n<p>מיוסדים על הס' יסוד יוסף המדבר בענין שמירת הברית, תיקון הפגם, ח\"ו, בזה וכו',</p>\n<p>ואף אשר לא הורגל בתוככי אנ\"ש להדפיס ספרים מיוחדים לביאור סיבת העון, וגם אפילו לא לייחד הדבור ע\"ז ברבים ובפרסום, וי\"ל הטעם ע\"ז, ע\"פ דברי כ\"ק אדמו\"ר הצ\"צ נ\"ע, כי ההרהור והפחד מהחטא יוכל לפעול, בטבע, הקרי כמו הרהורי עבירה (שו\"ת צ\"צ שער מילואים סי' סב. עיי\"ש),</p>\n<p>הנה במדינה זו, אשר נעשה פרץ גדול בעוון זה בחוגים ידועים, וכבקעה הדבר בעיניהם, ולא עוד אלא שאחדים מהרופאים, רופאי אליל ומתירי איסורים, מצווים על הבאים אליהם לעשותו ולנהוג בו ברגילות, מלעיגים על הנמנעים מזה ומסבירים שלא לבד שהיתר נעשה הדבר, אלא שמצוה, ר\"ל, הוא. ובעוה\"ר אין פוצה פה ומוחה ומגלה קלון, וגם לא מבאר, עכ\"פ כליון הגוף וכחותיו ואבדן החיים הבא עי\"ז, נוסף על טומאת הנפש וירידתה, אשר, כלשון רבנו הזקן נ\"ע, בעל התניא והשו\"ע, חמור עוון זה וגדול מעוות ביאות אסורות בבחי' הגדלות ורבוי הטומאה והקליפות שמוליד ומרבה במאד מאד (תניא ספ\"ז, עיי\"ש. ובלקו\"ת פ' שלח בתחלתה בדיוק הל' מאד מאד).</p>\n<p>הרי מקום לומר, אשר יש להדפיס ולפרסם ע\"ד גודל העוון והפגם, וגם לייחד הדבור אודות זה, ובלבד להציל נפש בחורי ישראל מרדת כו', ובעיקר - לחזק ולהגדיל גם עי\"ז את שימת לב המלמדים, הר\"מ והר\"י שליט\"א להמצב בזה, כי במדה ידועה וחשובה בהם הדבר תלוי לתקן המצב הפרוע, ומתאים למדה זו - הקולר תלוי בצווארם, ומי שיש בידו למחות וכו.</p>\n<p>וחפץ ה' בידו יצליח, לזכות את הרבים ולעוררם לעשות משפט (איהו רחמי) לעשוקים, הניצוצות דקדושה שנעשקים ע\"י מעשה הרע דבנ\"א (אדמו\"ר האמצעי נ\"ע בסידורו עה\"פ עושה משפט לעשוקים. עיי\"ש), עדי יקבץ הוי' נדחי עמו, ישראל, ע\"י מ\"צ בב\"א.</p>\n<p>בברכת הצלחה.</p>\n<p>כיון שבספרו זה עוסק בעניני מקואות ג\"כ, מוסג\"פ העתק רשימת הוראות כ\"ק אדמו\"ר מהורש\"ב, אביו של כ\"ק מו\"ח אדמו\"ר - זצוקללה\"ה נבג\"מ זי\"ע - בעת בנית המקוה בעירו.</p>\n<p>לחביבותי' דמילתא, באתי באיזה הערות בעברי בין דפי ספריו.</p>\n<p><b> ח\"א ע\"א. לראש הגוי'.</b> להעיר ולהאיר ממרז\"ל אין קישוי אלא לדעת (יבמות נג, ב) כי יש שייכות והתחברות להאבר עם מוח שבראש, והטעם ידוע שיש גידים דקים אשר ע\"י מתחבר החוט שבאבר עם המוח והיו לאחדים עד כי כאבר א' נחשבו. - ועיין בס' תורה אור לרבנו הזקן בהוספות ס\"פ ויחי שהאריך.</p>\n<p><b> שם עפ\"ז.</b> להעיר מס' אור השנים (להרא\"ל עפשטיין, גאון ומקובל, אב\"ד קעניגשברג) שמנה הוצאת ז\"ל במל\"ת שנא' לא תנאף. - ולע\"ע לא מצאתי לו חבר.</p>\n<p><b> ח\"ב על\"ד. טעם שלא נכתב בתורה עון מז\"ל</b> (ראה לעיל מס' אור השנים). - בתניא ספ\"ז כתב הטעם, מפני שבעון זה אפשר להעלות החיות שירדה בקליפות ע\"י תשובה נכונה כו' משא\"כ בשאר איסורין שבתורה. וע' פנים לתורה.</p>\n<p><b> שם. עפ\"ח. ע\"ד עונש הגלגול</b><b>.</b> לפלא שאחרי שנתגלה תורת האר\"י ז\"ל ותלמידיו, לא העתיק משם. ופרט אשר שער מיוחד ע\"ז - בשמונה שערים להאריז\"ל - והוא שער הגלגולים, מלבד המובא בכ\"מ בכתהאריז\"ל. וראה הקדמת הרח\"ו ז\"ל לשער ההקדמות קרוב לסופה.</p>\n<p><b> ח\"ג. בתחלתו. תיקוני החטא.</b> ראה תניא פ\"ז. אגרת התשובה לרבנו הזקן פ\"ג. שם פ\"ט.</p>\n<p><b> שם עקי\"א. הסרת הטבעת מהלולב בהו\"ר אחר אמירת הלל.</b> וצ\"ע. ומנהגנו להסיר <b> קודם</b> אמירת הלל. וכ\"מ בב\"ח שו\"ע או\"ח סתרס\"ד עיי\"ש הטעם. וכ\"כ גם בדרכי חיים ושלום סתשצ\"א.</p>\n<p><b> ח\"ד. בתחלתו. יעסוק בסודות התורה והיא תקון כו'.</b> ומזה עוד טעם (נוסף כיודא ועוד לקרא) למש\"כ האריז\"ל דדוקא בדורות אלו האחרונים מותר <b>ומצוה</b> לגלות זאת החכמה (הקבלה). וכבר האריך הרח\"ו בהקדמה הנ\"ל, וז\"ל: הכל תלוי בעסק החכמה הזאת, ומניעתינו מלהתעסק בה היא גורמת איחור ועיכוב בנין ביהמ\"ק כו' וכל הרעה הזאת היא מפני כו' שאין מתעסק בה כו' כי אין הנאה להקב\"ה מכל מה שברא בעולמו רק בהיות בניו למטה עוסקים ברזי התורה כו' כי בפשטי התורה כו' שלא נברא האדם אלא כדי שילמוד חכמת הקבלה כו'. ומביא ומפרש דברי זוה\"ק ח\"א כ\"ו וכ\"ז. שם קיח, א. ח\"ב רמז, א. ועוד עיי\"ש שהאריך.</p>\n<p><b> שם. עס\"ז ואילך</b><b>.</b> ראה בכ\"ז שו\"ת הצ\"צ חאה\"ע סקל\"ט. שם שער המילואים סמ\"ה.</p>\n<p>בחידושיו לברכות פ\"ג (ה, א)</p>\n<p>. <b>ח\"ה. בתחלתו. עה\"פ ויבוא יוסף</b><b>.</b> ראה דרך מצותיך לאדמו\"ר הצ\"צ ח\"ב ד' רעז, ב ואילך, שהאריך בכ\"ז.</p>\n<p><b> שם. עקנ\"ט. סנ\"א סק\"א.</b> ראה בזה שו\"ת צפנת פענח להגר\"י ראזין מרגצוב סכ\"ה.</p>\n<p><b> שם. בסופו עקפ\"ב. תמים הי' כו' אפילו בשביל הרהור, וצ\"ב היכן מרומז</b><b>.</b> י\"ל שהוא ע\"פ הזח\"ג רל, סע\"א: תוכו כברו בכל איברין פנימאין וחיצונין כו' תמים תהי' כו'.</p>\n<p>וראה שם קסה, ב' דלמד מכתוב זה על נח איש צדיק תמים הי'.</p>\n<h4><i><b>ב'תרמב</b></i></h4>\n<p>חלקה נדפס בלקו\"ש ח\"ז ע' 312, וחלקה שם ע' 315, והושלמה ע\"פ העתק המזכירות.</p>\n<p><b> מוה\"ר חנני' יום טוב ליפא שי</b><b>':</b> דייטש.</p>\n<p><b> דברי כ\"ק אדמו\"ר הצ</b><b>\"</b><b>צ</b><b>נ</b><b>\"</b><b>ע</b><b>:</b> אג\"ק שלו אגרת כו.</p>\n<p><b> העתק רשימת הוראות</b><b>:</b> נדפסה בס' טהרת מים בסופו. הוספות לשו\"ע אדה\"ז קה\"ת ח\"ה-ו ע' 78[1910].</p>\n<p><b> ומנהגנו:</b> ראה ס' המנהגים-חב\"ד ע' 68.</p>"],[1200830022,"ב'תרמג\n\n<p>ב\"ה, ט' אייר, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מג' אייר בו כותב אודות בת דודו ובעלה שיחיו.</p>\n<p>והנה נחוץ הי' א) שמכאן ולהבא תזהר בכיסוי הראש כפסק דין תורתנו הק'. ב) מכאן ולהבא תשתמש בהמקוה שהיא ממי גשמים או מי מעיין, ולא ממים העוברים דרך כלי מודד המים וכו' וכל הוספה בענינים דתורה ומצות ממשיך תוספת בברכות השי\"ת בהמצטרך לאדם וביתו שי'.</p>\n<p>בברכה,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>"],[1200830023,"ב'תרמד\n\n<p>ב\"ה, יו\"ד אייר, תשי\"ד,</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מאדר\"ח אייר, עם המוסגר בו.</p>\n<p>הנה בהנוגע לבריאותו, בכלל צריך להתנהג כפי הוראת הרופא, ובודאי אפשר לסדר זה באופן כזה שלא תהי' סתירה לעבודתו בקדש ובפרט שגם בריאות הגוף היות הגוף בריא ושלם מדרכי השם הוא במילא קען דאך ניט זיין אז איין מצוה זאל סותר זיין די צווייטע מצוה און ביחוד ווען מען טוט דאס מיט שמחה, איז שמחה פורץ גדר פון דעם חומר און נעמט דאס אראפ. וואס דענסטמאל איז גשמיות ניט ווייט פון רוחניות.</p>\n<p>והשי\"ת זאל העלפען אייך צוזאמען מיט אייערע בני בית צו אנזאגען שטענדיג בשורות טובות ויצליח בעבודתו בקדש מתוך בריאות הנכונה.</p>\n<p>בברכה ופ\"ש כל אנ\"ש שיחיו.</p>\n<p>נ.ב.</p>\n<p>מוסג\"פ קטע משיחת ש\"ק מברכין סיון דאשתקד שבאמת בכל השנה ושנה זמנו הוא.</p>"],[1200830024,"ב'תרמה\n\n<p>ב\"ה, יו\"ד אייר, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מעש\"ק, בו כותב אודות מצב רוחו שאינו כדבעי ועל מיעוט החיות בלימודו וכו' ומסיים שאינו יודע לשית עצות בנפשו.</p>\n<p>והנה אינו צריך לשית עצות, כי כבר ידועה עצה היעוצה מתורתנו הק' בכל הנ\"ל אשר יגעת ולא מצאת אל תאמין ובו הדבר תלוי להצליח בלימוד תורת הנגלה ותורת החסידות וגם שיהי' הלימוד בחיות כדבעי, אלא שכמו שלכל דבר צריך סייעתא דשמיא שגם הנ\"ל בכלל זה, צריך הוא לשמור את שלשת השיעורים השוים לכל נפש מתקנת כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע והם בחומש תהלים ותניא הידועים, וכן מהנכון שבכל יום מימות החול קודם תפלת הבקר יתן איזה פרוטות לצדקה שזהו סגולה שתקובל התפלה, ובטח למד בעיון ומקיים מ\"ש בלקו\"ת סד\"ה תחת אשר לא עבדת כו'.</p>\n<p>בברכת הצלחה בכל הנ\"ל.</p>\n<p><b>מזכיר</b></p>"],[1200830025,"ב'תרמו\n\n<p>ב\"ה, י\"א אייר, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>מה שכותב אודות התכנית למצה שמורה. הנה כיון שקשור זה בעניני תרומות ומעשרות, עדיין לא באתי לידי מסקנא בענין מסובך זה. כיון שנמרחו בארץ (צבי לצדיק בשו\"ע יו\"ד [סי' שלא סי\"ב]). ואף שלהנמצאים בארץ יש הנהגה ברורה ופשוטה בזה הרי בודאי בדאי אפשר שאני, משא\"כ להנמצאים בחו\"ל וד\"ל ובל\"נ כשתהי' איזה החלטה בזה אודיע.</p>\n<p>בברכת הצ' בגו\"ר.</p>\n<h4><i><b>ב'תרמו</b></i></h4>\n<p><b> התכנית</b><b>:</b> לקצור חטים, לשמרם לבררם ולטחנם באה\"ק במיוחד בשביל כ\"ק אדמו\"ר שליט\"א.</p>"],[1200830026,"ב'תרמז\n\n<p>ב\"ה, י\"א אייר, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ מוה\"ר<br>\nאברהם שי'</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מג', ט' י\"ב כ\"ו ניסן, ותקותי אשר נתקבלו המברקים שלי לחג הפסח וכן לכינוס צעירי אגו\"ח בזמנם. ובודאי יכתוב בפרטיות המתאימה איך שעבר הכינוס, מהות וכמות המשתתפים, והעיקר בנוגע להפועל ממש, שצמח ממנו...</p>\n<p>מצער אותי מה, שכנראה, אין ידוע במחנם הטעם שלע\"ע דחו נתינת הרשיון להביא הספרים, כי אז הי' בנקל לערער עליו. כי בפה אמרו הטעם - כמעט באופן רשמי - כי ספרי קה\"ת מתחרים עם הספרים הנדפסים באה\"ק ת\"ו. ומובן אשר אין לזה שחר, כי זהו היפך המציאות. וכיון שתקותי חזקה שיאשרו הקאנטראקט, הנה נשלחה רשימה, כבקשתו, מהוצאות קה\"ת בתור הצעה למשלוח חדש.</p>\n<p>... להחדיר באנ\"ש הרעיון אשר כולנו הננו חלקים מקומה שלימה אחת, וכאשר האחד רוצה לעשות \"שבת פאר זיך\" אין התוצאה מזה שמקבלים חלק יותר גדול בלויתן ושור הבר וכבוד יותר גדול בעוה\"ז הגשמי וביותר בעוה\"ז החומרי, אלא אדרבה, ואי אפשר שחלק אחד מקומה שלימה יהי' כדבעי ובתוספת בה בשעה שהוא משתדל ארויסצוחאפען בא א צווייטען חלק או עכ\"פ שלא להניחו למקומו השייך אליו ושיטה כזו מביאה לקלקולים הן מצד חשבון מוטעה הנ\"ל והן מפני החפזון והסודיות הבלתי רצוים כלל וכלל, ועיין ג\"כ באגה\"ק סי' ל\"א...</p>\n<p>בברכה לבריאות הנכונה לו ולכל ב\"ב שיחיו - המחכה לבשו\"ט בכל הנ\"ל.</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ב'תרמז</b></i></h4>\n<p><b> מוה\"ר אברהם</b><b>:</b> פריז, אגרות נוספות אליו - לעיל ח\"ז ב'קמח, ובהנסמן בהערות שם.</p>\n<p>לקמן ב'תשעז.</p>\n<p><b> לכינוס צעירי אגו\"ח:</b> דלעיל ח\"ח ב'תקצו.</p>\n<p><b> הספרים</b><b>:</b> ס' קה\"ת שנשלחו לאה\"ק. ראה גם לקמן אגרת ב'תערב.</p>"],[1200830027,"ב'תרמז*\n\n<p>ב\"ה, י\"א אייר, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>זה עתה נתקבל מכתבו המהיר מכ\"ה למנין בני ישראל, בו כותב אודות המצב בעניני שו\"ב. וכבר קבלתי מזה שאלה... ובאמת הנה כל השאלה כולה אין לה טעם כששואלים דבר אחד כו\"כ פעמים. והרי ממ\"נ אם רוצים לשמוע בחוות דעתו של מי שהוא די ומספיק בהמענה בפעם הראשונה, ואם אינם רוצים מהי התועלת לשאול כו\"כ פעמים. ובכל זה מפני הכבוד הנה מוסגר פה העתק מהמענה שלי להנ\"ל שממנו מובנת ג\"כ עמדתי בשאלה זו, ועוה\"פ אכפול, שאם יעמדו בתוקף אמיתי יצליחו. ובכלל אינו מובן מה ענין של הלכות צדקה להלכות שחיטה ואין לערב דבר בחבירו, אלא שהרצון מטעה את השכל, ואם ח\"ו לא יתנהגו בתוקף בזה כמו שלדעתי אינם מתנהגים בתוקף בעניני רבנות הרי יש ללמוד בנין אב מענין אחד על חבירו, והשי\"ת יצליחו ביחד עם כל אנ\"ש שי' להתנהג בתוקף שדרשו נשיאנו הק' וואס דענסטמאל גייט מען אויף אייזערנעם בריק ועל אחריותם.</p>\n<p>בכבוד וברכה בגשמיות וברוחניות.</p>"],[1200830028,"ב'תרמח\n\n<p><i> [י\"ג אייר תשי</i><i>\"</i><i>ד</i><i>]</i></p>\n<p>... ובהמשך לענין מכתבי הגניזה, הנה אף שאין הזמן גרמא לבוא באריכות הדרושה ובפרטיות, בכ\"ז אענה על איזה נקודות, והן:</p>\n<p>רובם המכריע של מכתבי וכ\"י הגניזה נכתב על קלף ולא על נייר. וכוונתי ב\"רובם המכריע\" אינו לקצת יותר מחצי אלא להרבה יותר משלשה רביעים.</p>\n<p>המכתבים שנדפסו בקובץ \"התמים\", הנה מובן שלהמסדר בדפוס (הזעצער) לא נתנו מכתבי הגניזה עצמם אלא העתקתם. והיתה מוכנת מלפני כמה שנים, והעתקה זו נעשתה ע\"י אברך ד.י. הי\"ד בריגא, אשר הי' ירא שמים בל לא דייקן, ובפרט בענינים שלא תפסו מקום כ\"כ אצל החסידים כמו התאריכים וכיו\"ב.</p>\n<p>בנוגע לסגנון המכתבים. הנה נפלאת הטענה, \"שכולם נכתבו בסגנון אחד ממש\". כי הנחה זו מופרכת לגמרי מעיקרא כיון שבין הכתבים ישנם: סיפורי מעשיות, צוואות, פ\"נ, קבלות וכו' וכו' ואי אפשר לכ\"ז שיהי' בסגנון אחד ועוד להוסיף בזה מלת \"ממש\". ואולי הכוונה להמכתבים ממש שבהם. וגם בזה לא יצדק הטוען, כי אחדים מהמכתבים נדפסו עשיריות שנים קודם גילוי גניזה זו ונמצאים ג\"כ במכתבי הגניזה, וא\"כ מובן שאדרבה, אלו האומרים שכל הגניזה מזויפת, הרי א\"א שיהי' הסגנון שוה בין המכתבים שנדפסו ואמיתתם בלי ספק ואותם שזויפו גם התוכן וגם הלשון לפ\"ד הטוענים. מובן מעצמו שיש שיווי ביניהם ובפרט בין חסידים לרבותיהם, שמשתדלים בסגנון מכתביהם והליכותיהם בכלל, להדמות לרבם. וכבר ידוע הצחות בזה, ע\"פ מרז\"ל (סוטה י\"א ע\"א): אחרי ה' אלקיכם תלכו - וכי אפשר לו לאדם להלך אחר שכינה וכו', משא\"כ תלמיד אחר רבו. ודוגמא אופינית בזה הוא מהידוע, שמעתיקים של כתבים ומאמרי דא\"ח לדורותיהם השתדלו לחקות בכתב ידם את כתב ידו של הרבי, עד שלפעמים תכופות הנה גם מבלי לעיין בגוף המאמר, יש להכיר מכתב-היד עצמו, אם הי' זה מעתיק בדורו של אדמו\"ר האמצעי או אדמו\"ר הצמח צדק וכו'.</p>\n<p>במה שהעירו שנמצאו כו\"כ שגיאות. הנה כבר כתבתי (במכתבי מאדר א' תשי\"ד) אשר אם רק נכונה ההשערה שנעתקו המכתבים מגוף כתבי-היד בשביל פקידי הממשלה הצארית, ובמילא נעשה הדבר בחפזון ולא דוקא ע\"י מעתיקים מומחים וביותר שכנ\"ל חסידים לא הקפידו מעולם על התאריכים, הרי אין פלא על רובא דרובא של השגיאות שנפלו. ובמכש\"כ ממעתיק עתה מכת\"י, שקודם ההגהה ישנו אחוז גדול של שגיאות, ובפרט אם מעתיק מכת\"י מסולסל שאות אחת נמשכת לחברתה וכו', ובפרטי פרטיות אם המעתיק רוצה לפרש את הראשי תיבות וגם זה עושה בחפזון, אשר עי\"ז יגדל לא רק מספר השגיאות אלא גם סוג השגיאות (ויבקשו נא את מי שהוא שאינו מומחה להעתיק מבלי אריכות זמן אחד מגוף כי\"ק דזמן ההוא, כמו מכתב הבעש\"ט או הרה\"צ כו' הרמ\"מ מהורודוק שנדפסו בקובץ \"התמים\" (חוברת א' וב') ויבחנו נא אח\"כ את השגיאות שיהיו אצלו!). ובפרט שבנדון דידן, ע\"פ השערה הנ\"ל, לא הקפידו מלכתחילה על הדיון מההעתקה.</p>\n<p>ע\"פ השערה הנ\"ל שההעתקה מגוף הכ\"י נעשתה בשביל אנשי הממשלה בכדי ובמטרה להטעותם שזהו הכ\"י, במילא מובן מפני מה מראם החיצוני הי' מוכרח להיות כשל אגרות מקוריות, וכן כמעט על כל אחד ואחד מעבר לדף באה הכתובת ברוסית של הפקיד. מפני מה האחוז של מכתבים תוכניים הוא קטן כ\"כ ובפרט מכתבים בדברי תורה כו'? - קושיא זו מתורצת במכתב כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע אודות מכתבי הגניזה בקובץ \"התמים\" חוברת א' - וז\"ל בסיום מכתבו: \"ישנם דברים כאלו כמו עניני קבלה מעשית צרופי שמות והדומה לזה ענינים עמוקים בקבלה שא\"א למסרם רק ע\"י כו'\" [קטע זה הושמט ב\"אגרות בעל התניא ובני דורו\" וכן גם הקטע <b>העיקרי</b> שבמכתב כ\"ק מו\"ח אדמו\"ר בו כותב דעת אביו לאחר בקורת \"כל הכ\"י וקריאת כל סיפורי המעשיות והכתבים, הפליג בשבחם וגילה דעתו הק', אשר כל הכתבים והמכתבים הם רק העתקות וכו', אבל תוכן הכתבים והמכתבים אמיתי הוא. ואם המצא תמצא איזו סתירת דברים קלי ערך הם לגבי הפלאת תוכנם ואינם אלא שגגת המעתיקים\" עכ\"ל].</p>\n<p>ובמילא לא לפלא שאחוז מכתבים תוכניים קטן הוא לגבי מכתבים האחרים כיון שכהנ\"ל לא נמסרו להדפיסם בקובץ \"התמים\".</p>\n<p>מי שיש לו ידיעה קלה ביותר בהנהגת נשיאי החסידים בדורות ההם, יודע הוא אשר לא כתבו את תורתם. ואדרבה נזהרו מלכתוב מפני כו\"כ טעמים, ורק במקרה יוצא מן הכלל ביותר, וכשלא הי' באפשרי לאמר המענה בע\"פ, באו בכתובים בזה, וגם אז רק בקיצור נמרץ. וכל המקשה, מפני מה בין כתבי אחד הנשיאים והאדמו\"רים בדורות שעברו נמצא אחוז קטן ביותר של דברי תורה וכו', הרי אין זה אלא הוראה שאין לו דיעה <b>כלל</b> בהנהגתם. ולא עוד אלא שאפילו בזמן כ\"ק מו\"ח אדמו\"ר ואביו כ\"ק אדמו\"ר מוהרש\"ב זצוקללה\"ה נבג\"מ זי\"ע, שענו לשואליהם דבר גם בענינים דנגלה דתורה ובתורת החסידות <b>הרבה</b> יותר מנשיאי חב\"ד שלפניהם, ועאכו\"כ מהאדמו\"רים בדורו של הבעש\"ט והרב המגיד, וארכיונם נשמר וידוע <b>ברור</b> שזהו כתב ידם או העתקה מגוף כת\"י, הנה בכ\"ז אחוז קטן הנם המכתבים בד\"ת וכו'. והוא מובן, כיון שמרובים צרכי עמך וכו', הרי רבו יותר ממרחק השואלים בענינים גשמיים או מבקשים ברכה וכו', מאשר השואלים בד\"ת, בנגלה ובתורת החסידות, אשר רובם ככולם היו שואלים אותם בע\"פ, כשהיו נוסעים להאדמו\"רים לרגלים ולמועדים ונכנסים אז ליחידות כיון שאין שאלות אלו ענין דחוף שא\"א לחכות בפתרונן איזה שבועות וחדשים.</p>\n<p>מה שכמה מהכתבים נחתמים בצירוף שם האם כמו בפ\"נ ולא בצירוף שם האב? מי שיש לו ידיעה במנהגי החסידים בכתבם לרבם יודע, אשר לפעמים תכופות ביותר חותמים בצירוף שם האם ואפילו במכתבים ולא דוקא בפ\"נ.</p>\n<p>ההנחה, שאם רק יוכיחו שמכתב אחד מזויף ה\"ז הוכחה גמורה שכל הגניזה מזויפת - הנה פשיטא שהנחה זו מופרכת מעיקרא. כי א\"כ הרי אפשר להוכיח זיוף של כל ספרינו ח\"ו על היסוד שנמצאו בהם טעויות הדפוס ונמצאות הוספות מזמן מאוחר וכו'. והרי ידוע, שבש\"ס יש הוספות מרבנן סבוראי ועד\"ז בכמה מהספרים שלאח\"ז.</p>\n<p>ואדרבה אם ימצאו בין המכתבים ואפילו רק מכתב אחד שהי' ידוע במסורה <b>סודית</b> רבי מפי רבי, הרי אין זה ענין שיכול מי שהוא לזייף ולהמציא כסומא בארובה וצ\"ל שהעתיקו מגוף כת\"י אלו שידעו ממסורה סודית זו. ואין נ\"מ אם זהו צרופי שמות, או עניני קבלה עמוקים, השבעת מלאכים וכו', ככל הדברים והסוגים שמונה אותם כ\"ק מו\"ח אדמו\"ר במכתבו הנ\"ל. ויש לתמוה שנעלם \"המזייף\", ואיננו וגם לא נודע לפני זה, הנה בעיני פלא הדבר ביותר, כי בכדי לזייף מכתבים אפילו רק אלו שנדפסו ועאכו\"כ אלו שלא נדפסו, שכפי המבואר במכתב כ\"ק מו\"ח אדמו\"ר הנ\"ל למדו אביו כ\"ק אדמו\"ר מוהרש\"ב הרבה פעמים והפליג בשבחם, הרי צריך להיות לא רק בעל כשרון של זיוף אלא גם בעל ידיעה חשובה בעניני קבלה וחסידות, נוסף על ידיעה פנימית ביחסי האדמו\"רים אחד לחבירו ובני ביתם הנזכרים במכתבים. ופלא גדול שאיש בעל כשרונות כאלו לא יפרסם מה שהוא בשנים שלפני גילוי הגניזה ולא אחרי כן. והרי כבר ידוע בדורות שעברו, כשפקפקו במחברו של איזה ספר, הרי הסבירו ג\"כ את מי יש לחשוד בחיבורו של ספר או כתב וראוי לכך מפני ידיעותיו. ולמותר להזכיר אשר בנוגע ל\"הזהר\" הזכירו את שם הר\"מ דיליאן. בנוגע לכמה תשובות הראשונים הנה החליפו את הרמב\"ן והרשב\"א והריטב\"א זה בזה וכו'. וכן גם בדורות האחרונים, בהנוגע לשו\"ת \"בשמים ראש\", המצבות שמצאו בקרים, הירושלמי ס' קדשים וכו' וכו' והאריכות בדבר הפשוט אך למותר.</p>\n<p>תקנה היתה מלפנים שלא ידפיסו ספרים - יהי' מי שיהי' המחבר - מבלי הסכמות, והטעם פשוט, כי כל בן אדם עלול לטעות, ועל כל פשעים ושגיאות תכסה אהבת עצמו והאמונה בשכל עצמו. ואפילו גדולי ישראל וחד-בדרא אמיתיים (סנה' ז' ע\"ב) היו מתייעצים ושואלים חוו\"ד אחרים קודם שיפסקו פסק דין.</p>\n<p>ובדורנו עלוב זה, אין צורך כבר בהסכמות, וכל הרוצה אומר, אשר גם הוא ביכלתו להיות דן יחידי, במקצוע שלו בודאי, ואם המקצוע אינו שלו - הרי הוא משער השערות ועל פיהן יקום דבר. והמדפיס מדפיס והקורא מחליט, שאין אחר מעשה דפוס ולא כלום.</p>\n<p>הרבי ממונקאטש - בעהמ\"ס \"מנחת אלעזר\" ועוד - אשר בסופה וסערה היתה דרכו ולא ניחת מביטויים חריפים וכו' בכתבו ע\"ד כללות מכתבי גניזה זו כותב בזהירות ידועה: \"ידי זרים המזייפים שלטו בהם\", \"השמר והזהר מבלי תאמין בם\", \"המכתבים האלו החשודים בזיוף\" (דברי תורה מהדורא ה', ס\"ט).</p>\n<p>כ\"ק מו\"ח אדמו\"ר מודיע החלטת אביו, לאחר שבחנו כל כתבי הגניזה (מלבד מכתבים <b>בודדים</b> שבאו לאחרים) <b>במשך כמה חדשים,</b> אשר תוכן הכתבים והמכתבים אמיתי הוא והסתירות שימצאו קלות ערך הן לגבי הפלאת תוכנם.</p>\n<p>והם <b>היחידים שראו את חלק כתבי גניזה זו שתוכנם: עניני קבלה, כינויים</b> <b>שונים משמותיו של הקב\"ה, שמות מלאכים ושירתם, צירופי שמות והשבעתן</b> <b> ועוד</b><b>.</b></p>\n<p></p>\n<p>ואף על פי כן הנה כותב בעל \"אגרות בעל התניא ובני דורו\": <b>\"שכולם</b> (החוקרים בדבר אמיתות הכתבים) לא נחתו לבדיקה כללית ויסודית של תוכן הכתבים. והגעתי למסקנה שכל (!!!) מכתבי הגניזה שראו אור הדפוס הנם מזוייפים. ומהם שנדפסו והופצו גם בהסכמתם של גדולי ישראל שטעו בזה\".</p>\n<p>ומי קורא תמים שיטיל ספק בוודאות פשוטה כזו?</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ב'תרמח</b></i></h4>\n<p>נדפסה ב\"הספר\" (תשט\"ו) בהוצ' שני' של \"התמים\" (ע' 852). אג\"ק אדה\"ז ע' תעו. והיא בהמשך לאגרת דלעיל ח\"ח ב'תצז.</p>"],[1200830029,"ב'תרמט\n\n<p>ב\"ה, י\"ג אייר, תשי\"ד</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ עוסק בצ\"צ מוה\"ר דוד שי'</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו ממוצש\"ק אמור ונהניתי במה שגרמתי לו נחת במכתבי אף שכתבתי הדבר כמו שהוא מבלי הוספה כדי לגרום נחת...</p>\n<p>נהניתי ממ\"ש אודות חלוקת המצה שמורה, ואשר עינו היתה טובה בשל אחרים לזכותם ג\"כ, ולו ידעתי מראש הייתי שולח יותר, אבל אין צועקים על העבר והכל תלוי במזל, ויה\"ר אשר לשנה הבאה, הנה כל הענינים שמקבלים אנו אותם עדיין באמונה, ובמילא סיוע בזה מיכלא דמהימנותא, יתיישבו אז בשכל ודעת, וישתמשו בכח האמונה לענינים יותר נעלים. וע\"ד המבואר בכ\"מ בדא\"ח שכמה דרגות באמונה, וכשמתעלה האדם בכח שכלו, הרי תופס בשכל מה שאתמול הי' עדיין אצלו רק באמונה, ואעפ\"כ נשארו אצלו כמה ענינים, שלע\"ע קצר שכלו להשיגם ומאמין בהם באמונה פשוטה. והוא ע\"ד הנראה גם עתה, שילד קטן אמיתית כמה דברים הוא אצלו באמונה, מה שהגדול מבינם ויודעם. ובמילא מובן שאצל הגדול יותר מגדול זה - מובן בשכל מה שהגדול נזקק לאמונה שלו.</p>\n<p>נהניתי ממ\"ש שממשיך בהדפסת לקוטי מאמרי רז\"ל במכתבי עתים שונים ובטח ישלח גם לכאן קטעים אלו ות\"ח מראש...</p>\n<p>בברכה לבר' הנכונה ולנחת מכיו\"ח שי'.</p>\n<h4><i><b>ב'תרמט</b></i></h4>\n<p>נדפסה בלקו\"ש ח\"ז ע' 246, והושלמה ע\"פ העתק המזכירות.</p>\n<p><b> מוה\"ר דוד</b><b>:</b> הלמן. אגרות נוספות אליו - לעיל - ח\"ח ב'שנד, ובהנסמן בהערות שם.</p>\n<p><b> במכתבי</b><b>:</b> דלעיל שם.</p>"],[1200830030,"ב'תרנ\n\n<p>ב\"ה, י\"ג אייר, תשי\"ד</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ עוסק בצ\"צ מוה\"ר בצלאל<br>\nשי' שד\"ר</p>\n<p> שלום וברכה!</p>\n<p>... ובמ\"ש בהשאלה כשמוציאים ס\"ת אחרת באמצע הקריאה איך היא ההנהגה בענין הברכה.</p>\n<p>הנה לא שמעתי בזה שמועות מיוחדות ובמילא אין בזה אלא הנדפס באחרונים ובפרט בשער אפרים ונ\"כ. - הועתק בשעה\"כ ש\"ה ס\"ב.</p>\n<p>המחכה לבשו\"ט אודות הצלחת המגבית בשביל הבנין החדש של ישיבת אהלי יוסף יצחק במעלבורן ופ\"ש כל אנ\"ש שיחיו.</p>\n<h4><i><b>ב'תרנ</b></i></h4>\n<p><b> מוה\"ר בצלאל:</b> ווילשנסקי. אגרות נוספות אליו - לעיל ח\"ח ב'תקטו, ובהנסמן בהערות שם. לקמן ב'תתפח.</p>\n<p><b> הבנין החדש:</b> ראה בזה לעיל ח\"ח אגרת ב'שי, ובהנסמן בהערות שם. לקמן ב'תרפא.</p>\n<p>ב'תשכז. ב'תשסו. ב'תשעב. ב'תתקכ. ב'תתקנו.</p>"],[1200830031,"ב'תרנא\n\n<p>ב\"ה, פסח שני, ה'תשי\"ד</p><p>ברוקלין, נ.י.</p><p>הוו\"ח אי\"א נו\"מ עוסק בצרכי ציבור בעל<br>\nמדות<br>\nתרומיות ענף עץ אבות וכו' מהרש\"ז שי'</p>\n<p> שלום וברכה!</p>\n<p>נעמה לי הזדמנות ביקורו בשבוע העבר, והרב חדקוב שי' מסר לי ממהלך הדברים בענין תכנית עבודתנו המחקרית באוצר כתביו מאמריו וספריו של אדמו\"ר הזקן. ובטוח אני שיקויים בו מרז\"ל המתחיל במצוה אומרים לו גמור, ויגמור הענין לפועל טוב. ובפרט אשר שמא גרים, שמע\"כ שי' נקרא ע\"ש אביו זקנו שנקרא ע\"ש רבינו הזקן. והאריכות בגודל הזכות שקשור בזה למותר הוא לדכוותי'.</p>\n<p>על פי הצעת מע\"כ שי', מוסג\"פ המכתב למר שפירא בצירוף רשימת תכנית מחקרנו זה. כפי שיראה, הכנסנו לתכנית זו, לשלימות הדבר, גם פרק מחקרי בתולדות ימי אדמו\"ר הזקן וביבליאוגרפיא של ספרים ופירושים שנתחברו על ספרי אדמו\"ר הזקן על ידי נשיאי חב\"ד הבאים אחריו וחסידיו.</p>\n<p>וחפץ ה' בידו יצליח להוציא הענין לפועל ממש, וליום ההילולא דרשב\"י נעשה התחלה טובה למלוי תכנית נעלה זו בעזר השי\"ת.</p>\n<p>בכבוד ובברכה.</p>\n<h4><i><b>ב'תרנא</b></i></h4>\n<p><b> מהרש</b><b>\"</b><b>ז</b><b>:</b> שזר. אגרות נוספות אליו - לעיל ח\"ח ב'שמג, ובהנסמן בהערות שם. לקמן ב'תשצה.</p>"],[1200830032,"ב'תרנב\n\n<p>ב\"ה, י\"ד אייר, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מי\"א אייר, בו כותב אשר מתקשה בהבנת לימוד הנגלה ולדעתו זהו מפני שמגיד השיעור לא התרגל להסביר בלשון הקדש, והנה ידוע פסק רז\"ל, לא יגעת ומצאת אל תאמין יגעת ולא מצאת אל תאמין.</p>\n<p>ולדעתי גם בנוגע אליו כן הוא, כי כשיש הרצון לאיש הישראלי ללמוד תורה, ובפרט אם הלימוד הוא ביראת שמים, הרי היצר הרע מתקומם נגד זה בתחבולות שונות ומשונות, ומובן אשר משתדל להסביר להאדם שאין הענינים תלוים בו כלל אלא בזולתו, ובמילא אי אפשר לעשות דבר בזה, כיון שהוא מצדו כבר עשה המוטל עליו, ואם ח\"ו פיתוי זה מתקבל הרי זה עלול להביא היזק גדול לא רק בלימוד התורה אלא גם בקיום המצות ואפי' מצות מעשיות כי כנ\"ל בא היצר ומוכיח בראיות שונות ומשונות, איך שגם בהנוגע לקיום המצות המצב הוא כנ\"ל, וכמו שבכל מלחמה, הרי קל יותר לנצחה בתחילתה מאשר לאחרי זה שכבר נתחזק השונא. וכלשון הזוהר הקדוש (ח\"ג דפ\"ז ב') על הפסוק מפני שיבה תקום שמזדקן בו היצר הרע ולכן עצת התורה <b>מפני</b> שיבה תקום, הרי גם בנידון דידיה כן הוא, היינו שבהקדם היותר אפשרי עליו לבטל טענות יצר הרע הנ\"ל ולבטשו, כמבואר הדרכים בזה בספר תניא קדישא בפירוש מאמר רז\"ל לעולם ירגיז אדם יצר טוב על יצר הרע, ואז יצליח הן בלימוד התורה והן בקיום המצות וביראת שמים שהיא היא אוצרו.</p>\n<p>אפשר שמפני אי התרגלות דהראש ישיבה והתלמידים - ישנם איזה קישויים בההבנה ההדדית, אבל כלא וכאין נחשב הוא, נגד האושר שבא לאיש הישראלי ע\"י לימוד תורתינו הקדושה, חכמתו ורצונו של הקב\"ה, ולפום צערא אגרא.</p>\n<p>אפשר הדבר שגם בין חביריו נמצאים כאלה שנדמה להם ג\"כ שהמניעה בלימוד התורה ושקידה הדרושה היא פני טעם הנ\"ל וכיו\"ב, הרי מטובו להסביר גם כן אותם כל הכתוב בזה, ובודאי ימצא אותיות המתאימות הדרושות.</p>\n<p>בברכה.</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>\n<h4><i><b>ב'תרנב</b></i></h4>\n<p>נדפסה בלקו\"ש חכ\"א ע' 360, והוגהה ע\"פ העתק המזכירות.</p>"],[1200830033,"ב'תרנג\n\n<p>ב\"ה, ט\"ו אייר, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>... וענין עיקרי והוא נוסף על מה שמסר לו הרה\"ח כו' מוהרחמ\"א שי' חדקוב ע\"י הטלפון, אשר אינני מבין הנהגתו כלל וכלל במה שנמסר לי אודות העדר האכילה הדבור כו' וכו'.</p>\n<p>בטח יש לו איזה טעם בזה אבל כיון שהאשה דמעתה מצוי' ונשים דעתן קלה, וגם להשתנות להנהגה טובה יותר הלא לא בכפי' בדבור ובשוטים חפץ ה' וזה נוסף על ציווי הבעש\"ט הרב המגיד ורבנו הזקן וכו' בהכרח שמירת בריאות הגוף וכמבואר ג\"כ במאמר דיו\"ד שבט האחרון והאריכות בזה אך למותר, וכבר ידוע המובא בדא\"ח במה שאפשר הי' ליעקב לבחור למנחה גם בהמות טמאות אף שזהו ע\"ד הקרבת קרבנות, כי קודם מתן תורה כמה דרכים ישנם אבל לאחר מעמד הר סיני מה שנאסר נאסר ואין מקום להוראת היתר (מלבד נביא ששמע ציווי ה' נגד זה ובדרך הוראת שעה, ומובן שאין אני חושדו בזה), ואחכה לבשו\"ט שמכאן ולהבא השלום במעונם ומוסיפים הם בבריאות הגוף ובריאות הנשמה והשי\"ת יצליחם.</p>\n<p>בברכה - המחכה לבשו\"ט.</p>"],[1200830034,"ב'תרנד\n\n<p>ב\"ה, ט\"ו אייר, ה'תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ג והרה\"ח וו\"ח אי\"א נו\"מ עוסק בצרכי<br>\nציבור בעל<br>\nמרץ ורב פעלים וכו' מוהרצ\"ה שי'</p>\n<p> שלום וברכה!</p>\n<p>קבלתי הגליונות של הספר פירושי התורה להרמב\"ן בצירוף הערות כת\"ר שי', ות\"ת על טרחתו לשלחם אלי. ונהניתי בעברי על הדפים ובראותי כמה מלאכה וחכמה השקיע בהערות אלו, ועל פי המנהג, הנני מצרף בזה איזו הערות משלי בהנוגע להתחלת פתיחת הרמב\"ן.</p>\n<p>כן מוסג\"פ איזה הערות על קונטרסו \"הצעה לתיקון עירובין\". וכבר ידוע פירוש רז\"ל על הפסוק ואת והב בסופה.</p>\n<p>ובהזדמנות זו עה\"פ אביע את איחולי לכת\"ר שי' לנסיעה כשורה ובהצלחה ולנצל את השפעתו בהיותו באה\"ק ת\"ו להרמת קרן ישראל סבא בגאון וביד רמה.</p>\n<p>בכבוד וברכה.</p>\n<p><b>הערות לקונטרס פי' התורה להרמב\"ן וכו</b><b>'.</b></p>\n<p><b> שורה ג. הא' - והנורא.</b> יש להעיר: מלה\"כ דברים י, יז. וראה יומא סט, ב.</p>\n<p><b> שם. אתחיל וההערה ע\"ז.</b> גם בהקדמת הי\"ד משתמש בל' עתיד <b>ואחלק ההלכות</b><b>...</b> <b> אחלק אותו</b><b>.</b> ובכלל תמוה קצת לומר שנכתב הספר קודם לההקדמה. - והסתירה שבין השנים, בהל' שמיטה ויובל (פ\"י ה\"ו) אלף ק\"ז לחורבן ובהקדמה - אלף ק\"ח - הרי כבר העיר שבלאה\"כ צריך בירור, מה שבהל' קדה\"ח (פי\"א הט\"ז) נמצא אלף ק\"ט (כצ\"ל) לחורבן.</p>\n<p>ויש להוסיף ע\"ז מה שבהל' קדה\"ח עצמן משמע קצת, שנכתבו בשנת אלף ק' לחורבן (פ\"ט ה\"ה).</p>\n<p>וכל הנ\"ל מובן ע\"פ הידוע, שהרמב\"ם כתב ספר היד ותקנו וחזר ותקנו וכו' - (וראה בזה רמב\"ם הוצאת שולזינגער סוף כרך חמישי) -, ומובן שלא שינה במהדורא ב' אלא הלכות הצריכות תקון, אבל לא כל הכת\"י, ובפרט שכבר נתפשטו ההעתקות ממהד\"ק וכמובא באגרות הרמב\"ם ובנו וכו'.</p>\n<p>ולכן אפשר, אשר פ\"ט מהל' קדה\"ח נכתב במהד\"ק בשנת אלף ק' ונכנס הפרק כמו שהוא במהדורות שאחריו. ופי\"א חלו בו שינוים או תיקונים לאחר זמן, ועריכתו הסופית הייתה בשנת אלף ק\"ט.</p>\n<p>וההקדמה הרי נכתבה לאחר שכבר יכול הי' הרמב\"ם לקבוע לא רק מספר הספרים, אלא גם ההלכות והמצות שנת' בכל ספר וספר, וכמו שמפרטן בסוף ההקדמה - היינו שכבר הי' כל ה\"חומר\" מוכן אצלו, אבל - קודם לכתיבת הספר, וכמו שמסיימה: <b>ועתה</b> <b> אתחיל</b> לבאר משפטי כל מצוה וכו'.</p>\n<p>וע\"פ כהנ\"ל מובן ג\"כ, שיש מקום לכל הדעות ע\"ד שנת <b>התחלת</b> עסק הרמב\"ם בספרו משנה תורה (הובאו בסה\"ד ובכ\"מ. והמוקדמת שבהם - שנת אלף ק'. וכנ\"ל).</p>\n<p><b> שם. באימה... בזיע</b><b>.</b> יש להעיר: מלשון הגמרא ברכות כב, א. - ומה שהוסיף הרמב\"ן כאן <b>במורא</b> - צ\"ע, כי ע\"פ תורת הסוד ד' ביטוים אלו מדויקים, והם כנגד ד' אותיות שם הוי' (לקוטי הש\"ס להאריז\"ל למס' מו\"ק. דרך אגב: יש שם - בכל הדפוסים שראיתי - השמטה דמוכח, ותוכנה, ביאור ענין זיע, שהוא באיברים החצונים בסוד ה' שבשם, מלבוש החיצון כו'. ודלג המעתיק מ\"שבשם\" השלישי ל\"שבשם\" הרביעי, ול\"ע, ל\"מ מי שהעיר בזה!). - והי' יכול לשמור גם סיום החרוז (אות קמוצה) ע\"י שינוי הסדר ולכתוב בזיע... באימה - ואולי אפ\"ל, אשר <b>במורא</b> הוא כנגד קוצו של יו\"ד, שבכמה ענינים בא רמז עליו בפ\"ע ולא נכלל בהיו\"ד. וכמו במרז\"ל ה' שמות נקראו לה (ב\"ר פי\"ד, ט), אף שבזהר (ח\"א עט, ב) כוללם בד' שמות. - ובברכות לא מנה אלא ד' דברים, וע\"ד כמו בזהר הנ\"ל, דמורא נכלל באימה. ואכ\"מ.</p>\n<p><b> שם. שורה ד. סליחה... מחילה וכפרה.</b> להעיר מירושלמי סוף יומא. אחרונים לשו\"ע או\"ח סתר\"ז. שו\"ע רבנו שם ס\"ז, ובסידורו.</p>\n<p><b> שם. שורה ה. בקידה. בבריכה. בהשתחוי'.</b> להעיר: מל' הגמרא ברכות לד, ב.</p>\n<p><b> שם. שורה וא\"ו. ביצת הנמלה</b><b>.</b> לע\"ע, לא מצאתיו במ\"א. וצ\"ע ובירור, אולי נשתבש ע\"י המעתיקים, וצ\"ל <b>ביצת הכינה,</b> אשר הוא מין בע\"ח היותר קטן שבעולם (שבת קז, ב), ומקביל ל\"גלגל העליון\" - בריאה היותר חשובה שבעולם. - ולהעיר מרמב\"ם הל' יסוה\"ת פ\"ב ה\"ט. שער היחוד והאמונה - לרבנו הזקן - פ\"ז (פג, א).</p>\n<p><b>הערות לקונטרס הצעה לתיקון עירובין</b><b>.</b></p>\n<p><b> ע\"א. ס\"ב. שיטת רש\"י.</b> כ\"פ רבנו הזקן בשולחנו סשמ\"ה סי\"א. ובכ\"מ. ובשו\"ת בית אב תנינא ס\"ה ובמפתחות מונה שלשים פוסקים מהראשונים דס\"ל כרש\"י.</p>\n<p><b> שם. אא.</b> הטעם שבמספר ס\"ר - גם א\"י בכלל, י\"ל, כי שבת במרה נצטוו (ראה תוד\"ה אתחומין שבת פז, ב), ועדיין דין ב\"נ להם (וכידוע דעת כמה ראשונים בזה). וגם לאח\"כ, במ\"ת, נגדרו עניני שבת \"כאשר צוך\" - במרה.</p>\n<p><b> ע\"ב. ס\"ג. לכו\"ע רה\"ר מה\"ת.</b> צ\"ע ובירור. דכמדומה הרחובות כולם מסתיימות, <b> סו</b><b>\"</b><b>ס</b><b>,</b> בגשרים ומנהרות הסתומות ע\"י צוה\"פ או גם מחיצה ו\"שראנקען\" כדי לגבות מס וכיו\"ב. - לעיין א\"א להר\"א מבוטשאטש סשמ\"ה.</p>\n<p><b> ע\"ג. גדר ים ונהר.</b> (נפ\"מ בכתיבת גט וכיו\"ב) לכאורה י\"ל אם מימיו מיקווי וקיימי במקומם (אף שישנם גלים), או שוטפים (מקואות פ\"ה מ\"ד. מכות ד, א. יבמות קמא, א.</p>\n<p>ועוד. וראה שו\"ת צפנת פענח להגר\"י מרגצוב סנ\"ח-נט) - אבל אליבי' דאמת נ\"ל, שבכ\"מ הוא לפי ענינו. ובהל' עירובין תלוי במה שרואים הבפועל אם (לפעמים עכ\"פ) מעלה שרטון ונקרש. א\"ל. - ובזה מבואר מה שבראשונים ואחרונים נפרטו כמה דינים וחילוקים בחששות הנ\"ל, בנהרות שונים, בעוקי וכו' - אף שאינם מבוארים בש\"ס -</p>\n<p>ועפ\"ז יש לברר כל חלקי היקף מנהעטאן המובאים כאן. - ויל\"ע בספרים שהובאו בזה בארחות חיים (החדש) סשמ\"ג.</p>\n<p><b> ע\"ג. חשש שמא יעלה הים שרטון אליבא דחד ס\"ד.</b> צ\"ע כי כ\"פ הרמ\"א (ראה יד מלאכי כללי הרמ\"א חי). והעתיקו לפסק הלכה אדה\"ז סשס\"ג סל\"ח.</p>\n<p><b> שם. דעת החת</b><b>\"</b><b>ס</b><b>.</b> דעת אדה\"ז (שם) שטוב לחוש לדברי האוסר.</p>\n<p><b> ע\"ד. ס\"ח. דאפשר לראות מראש הבתים הגבוהים וכו</b><b>'.</b> - אין נפלענ\"ד כלל לומר, דע\"י בנין מגדל וראשו בשמים באמצע שטח גדול ביותר מוקף <b>יהפך</b> כל השטח מרה\"ר <b> דאורייתא</b> לרה\"י. ואין לומר דכל <b>הראוי</b> לראות ההיקף ע\"י בנין וכיו\"ב - רה\"י הוא מה\"ת, דא\"כ קושית הש\"ס דכו\"ע מקיף לי' אוקינוס (עירובין כב, ב, לפי הפי' המובא בקונטרס שצ\"ל ההיקף) במקומה עומדת, וכמסופר בשלמה (ירושלמי. הובא בתוד\"ה ככדור ע\"ז מא, א).</p>\n<p>ועכצ\"ל דלפי הנ\"ל צריך שיראה בעמדו בשטח הארץ. ובבכורות (נד, א) שהוא טז מיל.</p>\n<p>ואולי בנדו\"ד הוא יותר ע\"ז כי שם צ\"ל שלטא בה עינא לשמור ולמנות משא\"כ בהיקף מחיצות.</p>\n<p>- ולהעיר להנ\"ל מפסחים (צד, א) יכול ליכנס בסוסים ובפרדים כו'. ועייג\"כ בשיעור מקום קרוב (מו\"ק כב, א), בימינו דנוסעים במסה\"ב, באוירון וכיו\"ב - דשקו\"ט בזה בספרים הובאו בס' כל בו - להרב גרינוואלד - ח\"א ע' של.</p>\n<p><b> ע\"ה סוסי\"א.</b> יל\"ע בשו\"ע רבנו הזקן סשמ\"ג סמ\"ג.</p>\n<p><b> שם. סי\"ב. אא</b><b>.</b> יעוין ביאור הלכה לבעה\"מ משנ\"ב סשנ\"ח ס\"ט.</p>\n<p><b> שם. גג</b><b>.</b> בפלוגתא שנוי' - ראה ס' הובאו בהגהות מהרש\"ם שבארחות חיים (החדש) סשנ\"ח.</p>\n<p>* * *</p>\n<p>בענין שמצוה היא לתקן עירובין. - ראה עירובין כח, א. טושו\"ע או\"ח סשס\"ו סי\"ג.</p>\n<p>שט\"מ ביצה (טז, ב). שו\"ת הרא\"ש כלל כא. רשב\"ץ (ח\"ב, סל\"ז). חת\"ס חאו\"ח סצ\"ט.</p>\n<p>שו\"ת בית אב תנינא סי' א.</p>\n<p>ולהעיר, אשר כל הספר האחרון דן בעניני עירובין, ושקו\"ט שם בכמה פרטים המובאים בקונטרס זה.</p>\n<p><i> ב'תרנד</i></p>\n<p>נדפסה בלקו\"ש ח\"כ ע' 547, והושלמה ע\"פ העתק המזכירות.</p>\n<p><b> מוהרצ\"ה:</b> אייזנשטט.</p>\n<p><b> וכל הנ\"ל מובן</b><b>:</b> ראה בזה גם שיחת ש\"פ חוקת תשד\"מ.</p>\n<p><b> לתיקון עירובין</b><b>:</b> ראה גם לקמן אגרת ב'תשפו.</p>"],[1200830035,"ב'תרנה\n\n<p>ב\"ה, ט\"ו אייר, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו, בו כותב אודות אשר עבר עליו ומתאונן על מצבו עתה שמלמד הוא תינוקות של בית רבן וחושב שעל ידי זה נפל בלימודו ובמילא רוצה או לנסוע לאה\"ק ת\"ו או שיתנו לו כתה גבוה ללמוד.</p>\n<p>והנה בכלל ענינים כמו אלו שייכים להנהלת מוסדות אהלי יוסף יצחק ליובאוויטש אשר במרוקה ובמילא מסרתי בקשתו להם ויבואו בקשר אתו.</p>\n<p>אבל מה שמפליאני ביותר הוא מה שמצטער על עסקו עתה ועל סיומו במכתבו שכותב שהוא בצער עצום עי\"ז ואומר אשר ע\"י התעסקותו הנ\"ל נפל בלימודו. והרי ידוע ומפורסם תורת הבעש\"ט ששמענוה כ\"פ מכ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע אשר כדאית ירידת הנשמה למטה ולהיות כאן בגוף גשמי משך שבעים שמונים שנה בשביל לעשות טובה פעם אחת במשך ימי חייו לאיש או אשה הישראלים בגשמיות או ברוחניות והנשמה הרי היא חלק אלקה ממעל ממש וחצובה מתחת כסא הכבוד, ובכל זה אומרת השכינה אשר כדאי שתרד ממקום כבודה מאיגרא רמה לבירא עמיקתא בשביל עשיית טובה פעם אחת, וכאשר זיכהו השי\"ת והצליחו שבכל יום ויום עושה מה בקירוב לבם של בני ישראל לאבינו שבשמים שעל ידי זה יש לו חלק בשמחת ה' במעשיו ושמחת ישראל בעושיו, הרי אומר הוא שאפשר ליפול בלימודי התורה עי\"ז ונמצא הוא בצער עצום, וכשהדבר ברור ופשוט כ\"כ מאין באים טענות אלו הרי כנראה שספק הוא אצלו וקס\"ד שהוא טענות היצר טוב.</p>\n<p>כלך מדרך זה לגמרי וימסור את עצמו לעבודתו בקדש ללמד את בני ישראל תורה, שהלומד מתחיל מלימוד אל\"ף בי\"ת וכו' ואין אתנו יודע עד מה מה נחשב יותר לפני המקום נוסף על מרז\"ל אל תהי' יושב ושוקל במצותי' של תורה כו' שנאמר אורח חיים <b> פן תפלס</b><b>.</b> ומובן אשר צריכה להיות עבודה זו בשמחה על שזכה לזה ואז יצליח גם בעניניו הפרטים שיעשו מוחו ולבו - כלשון רבנו הזקן - זכים אלף פעמים ככה ויעלה בלימוד תורת הנגלה ובתורת החסידות.</p>\n<p>בברכה,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>\n<h4><i><b>ב'תרנה</b></i></h4>\n<p><b> תורת הבעש</b><b>\"</b><b>ט</b><b>:</b> ראה גם לעיל אגרת ב'תרמא, ובהנסמן בהערות שם.</p>\n<p><b> כלשון רבנו הזקן</b><b>:</b> תו\"א בתחלתו.</p>"],[1200830036,"ב'תרנו\n\n<p>ב\"ה, ט\"ו אייר, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מט' אייר, הנה ידוע תורת הבעש\"ט שהוא יסוד תורתנו הק' אשר כל הענינים שבעולם הם בהשגחה פרטית ממנו ית' אשר הוא המשגיח על כל אחד מבני ישראל לא רק בכללות אלא גם בכל הפרטים ופרטי פרטים שבחיי היום יומים ובמילא על כל אחד אומר הכתוב, ד' לי לא אירא, ואף שלפעמים מסיחים דעת מזה הרי אין זה אלא עצת היצר שרוצה להפחיד ח\"ו את ישראל מאבינו שבשמים ע\"י טענות של שטות וכמרז\"ל בזה. כי הרי האמת הוא כנ\"ל אשר כל אחד ואחת מישראל בנים הם לאבינו שבשמים ואי אפשר להפריד בין אב לבן ובת. היוצא מזה שאין כל מקום לפחד ח\"ו כלל כיון שה' צלך על יד ימינך והוא ית' שומר ומשגיח על כל אחד ואחד מאתנו. ותקותי ששורותי אלה המעטים בכמות יספיקו שיהיו חזקים בבטחונם בהשי\"ת בחיי היום יומים ובבטחה ובשמחה יתעסקו בעניניהם.</p>\n<p>והשי\"ת ימלא ימי הריונה כשורה ובנקל ותלד זחו\"ק בעתה ובזמנה כשורה ובקל.</p>\n<p>בברכה.</p>\n<p>נ.ב.</p>\n<p>מהנכון הי' לבדוק את המזוזות בביתם שכנראה יש בהם שצריך להחליפם, וכן גם לבדוק את התפילין שלו.</p>"],[1200830037,"ב'תרנז\n\n<p>ב\"ה, ט\"ו אייר, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו ממוצש\"ק, ובתור מאמר המוסגר הנה פלא על השתדלותו להיות רק - כפתגם כ\"ק מו\"ח אדמו\"ר - פון די צרות חסידים, היינו אשר כותב בעת צרה ל\"ע ול\"ע, ולולא זאת הנה נסתם כל חזון ממנו.</p>\n<p>ובהנוגע לשאלתו הנה מלפני זמן רב עוררתיו וכתבתי לו על הנחיצות הכי גדולה להיות בקירוב הדעת עם בע\"ב ובפרט כאלו שאם נדמה שסובלים מהם הוא לא מפני העדר היר\"ש שבהם ולכל היותר רק מפני חסרון ידיעה ובמילא במכש\"כ וק\"ו שצריך לקרבם באופנים המתאימים ובפרט בהנוגע... שלא ישרה כלל בעיני היחס שביניהם וכיון שהוא הצעיר והשי\"ת זיכהו ללמוד בישיבת תו\"ת ולקבל כמה הדרכות מכ\"ק מו\"ח אדמו\"ר בעניני הנהגה בכלל ובענין דאהבת ישראל שבזה בפרט הרי היזמה בזה והצעדים הראשונים ואולי עוד יותר מזה צ\"ל מצדו, ואין בזה ענין של מיעוט הדמות או עלבון דכבוד התורה כו' וכו' כמובן. וכבר ידוע סיפור החכם כמדומה מובא בס' מבחר הפנימים להבדרשי בביאור הענין מפני מה הולכים החכמים אל העשירים ולא העשירים אל החכמים שהטעם בזה הוא שהעשירים כשאינם חכמים אינם יודעים מעלת החכמה ואשר חסרה אצלם. משא\"כ החכמים הנה מוצאים המעלה שיש בעשירות ושיש לנצלה, וה\"ה בנדון דידן...</p>\n<p>בברכת הצלחה בכל הנ\"ל.</p>\n<h4><i><b>ב'תרנז</b></i></h4>\n<p><b> צרות חסידים:</b> ראה גם לעיל ח\"ג אגרת תשיג, ובהנסמן בהערות שם.</p>"],[1200830038,"ב'תרנז*\n\n<p>ב\"ה, ט\"ו אייר, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>עס איז ערהאלטען געווארען אייער בריף פון ה' בהר.</p>\n<p>א) בנוגע צו אפשטעלען דעם זמן החתונה, איז כדאי משתדל זיין זיך אויב עס איז נאר מעגליך אז עס זאל זיין א חופה טהורה, און אויב דאס קען זיין ראש חדש אפילו דעם ערשטען טאג - ווען ראש חדש איז צוויי טעג - איז אויך גוט. זעלבסט פארשטענדליך ניט ראש חדש סיון וועלכער איז אין די ספירה טעג אבער עס קען זיין ר\"ח תמוז אדער ר\"ח אלול. און אויף ווען איר וועט באשטעלען זאל דאס זיין בשעה טובה ומוצלחת ולמזל טוב...</p>\n<p>בברכה ובפ\"ש כל אנ\"ש המחכה לבשו\"ט.</p>"],[1200830039,"ב'תרנח\n\n<p>ב\"ה, ט\"ז אייר, תשי\"ד</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ כו' מוה\"ר דן שי' הכהן</p>\n<p> שלום וברכה!</p>\n<p>נתקבל מכתבו מי\"א אייר, וכבקשתו אזכיר את כל אלה שכותב אודותם בהיותי על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, בעת רצון. ולפלא שאינו מזכיר במכתבו אם כותב הוא בשליחותם וע\"ד מאמר רז\"ל ששלוחו של אדם כמותו או שכותב מדעת עצמו מצד הענין דאהבת ישראל שהוא כלל גדול בתורה וכמאמר רבנו הזקן בעל התניא - פוסק בנסתר דתורה - והשולחן ערוך - פוסק בנגלה דתורה - שזהו כלי לואהבת את ה' אלקיך, אשר מצות אהבת השם היא שרש לקיום כל מצות עשה שבתוכה גם מצות יראת ה' שרש לקיום כל מצות לא תעשה ונמצא אשר אהבת ד' היא שרש לכל המצות בכלל. ובודאי כשיהי' אצלו בשורות טובות אודות המוזכרים במכתבו יודיע ות\"ח.</p>\n<p>בהנוגע לסיום מכתבו אודות שכר טרחה. הנה שכר מצוה מצוה, ובעד כל הנ\"ל עליו להוסיף אומץ בקירוב לבם של בני ובנות ישראל לאבינו שבשמים על ידי השפעה דימין מקרבת ומתוך אהבת ישראל וכשיעשה בזה במסירה ונתינה המתאימה בודאי יצליח והי' זה שכרי.</p>\n<p>בודאי יש לו קביעות עתים ללמוד גם בפנימיות התורה, וכיון שבא בקישור מכתבים אתי לא אפונה אשר יקבע שיעור בלימוד ספרי חב\"ד מתחיל מספר התניא קדישא.</p>\n<p>בברכה,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>\n<p>נ.ב.</p>\n<p>במכתבו מזכיר שאלו שכותב אודותם נמצאים בעיר ג'רבה ובטח כוונתו להעיר טשרבה וק\"ק דשם. ואתענין לדעת כל דבר לימוד פנימיות התורה, האם מתקיים הוא שם ובאיזה אופן.</p>\n<h4><i><b>ב'תרנח</b></i></h4>\n<p><b> מוה\"ר דן:</b> בנגרדן. אגרת נוספת אליו - לקמן ב'תשטו.</p>\n<p><b> וכמאמר רבנו הזקן</b><b>:</b> ראה גם לעיל ח\"ו אגרת א'תקמא, ובהנסמן בהערות שם. לקמן ב'תרסה.</p>"],[1200830040,"ב'תרנט\n\n<p>ב\"ה, ט\"ז אייר, תשי\"ד</p><p>ברוקלין.</p>\n<p> ברכה ושלום!</p>\n<p>איך בין געווען צופרידען צו באקומען דיין בריף פון אנהויב וואך, אין וועלכען דו שרייבסט אז דו האסט אנגעהויבען טאן אין א מסיבת שבת וועלכע איז ארגאניזירט געווארען דורך די אנשי ליובאוויטש.</p>\n<p>ווארום אז מען טוט א טובה וועלכע טובה עס זאל ניט זיין מיט א צווייטען זאגען אויף דעם רבותינו זכרונם לברכה יותר ממה שבעל הבית עושה עם העני, העני עושה עם בעל הבית, און ווען די טובה איז א רוחניות'דיקע, וואס מען איז מקרב לאבינו שבשמים לתורה ולמצות, איז די טובה וואס מען באקומט אליין דורך דעם נאך פיל פיל גרעסער, און בפרט דריקט זיך דאס אויס אין דער ברכה פון השם יתברך אז ער העלפט דעם וואס טוט די טובה ברוחניות אז ער אליין זאל זיך קענען אויפפירען לויט דער פאדערונג פון תורתנו הק' אן שטערונגען און אויך אין די פריוואטע ענינים זיינע זאל ער שטייגען מחיל אל חיל.</p>\n<p>און השם יתברך זאל דיר העלפען אז דו זאלסט טאן אין דער אויבען דערמאנטער מסיבת שבת מיט א איבערגעבענהייט וואס עס ווערט ערווארטעט פון א אידישער טאכטער און זאלסט מצליח זיין אין דעם צו זעהען גוטע פעולות פון דיין ארבעט אין דעם און זאלסט קענען אנזאגען גוטע בשורות אין דעם און אויך פון דיין הצלחה אין דיינע לימודים און מעשים בכלל.</p>\n<p>בברכת הצלחה.</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>\n<p>נ.ב...</p>\n<p>בקשתי - איבערגעבען א גרוס צו די וועלכע באטייליגען זיך מיט דיר אין דער ארבעט און אויך איבערגעבען זיי דעם אינהאלט פון דאס אויבען געשריבענע און ווינש זיי אלעמען ברכה והצלחה.</p>"],[1200830041,"ב'תרס\n\n<p>ב\"ה, ט\"ז אייר, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מאדר\"ח אייר. בו כותב אשר לפנים למד בישיבת תומכי תמימים... ואח\"כ נתרשל בלימודו ועבד חלק מ[ז]מנו בעבודות שונות בכפר חב\"ד, ושואל דעתי מה עליו לעשות בחדשים הקרובים.</p>\n<p>הנה לדעתי יכנס בהקדם להישיבה וילמוד שם במסירה ונתינה ובשקידה אשר זה יהי' הכנה טובה בכלל וגם בענין הכניסה לבית ספר למלאכה, כי מובן אשר דין קדימה יותר בקבלה לתלמיד בבית ספר זה לאלו האברכים שיראו אשר המוח שלהם שליט על רצונם ויכולים הם למלאות תפקידם שנמסר להם כדבעי, ואלה שעושים את העולה במחשבתם אינם שייכים למשמעת ולהנהגה דקבלת עול והקדמת נעשה לנשמע.</p>\n<p>בודאי אומר בכל יום אחר התפלה בבקר את השיעור תהלים וגם עתה יש לו קביעות בלימוד תורת הנגלה ותורת החסידות והשי\"ת יצליחו.</p>\n<p>המחכה לבשו\"ט,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<h4><i><b>ב'תרס</b></i></h4>\n<p><b> להישיבה... לבית ספר למלאכה:</b> ראה גם לקמן אגרות ב'תרעז. ב'תשכט. ב'תתי.</p>"],[1200830042,"ב'תרסא\n\n<p>ב\"ה, ט\"ז אייר, תשי\"ד</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ איש בעל מרץ ורב פעלים<br>\nהרב מוה\"ר<br>\nיצחק שי'</p>\n<p> שלום וברכה!</p>\n<p>בנועם קבלתי פ\"ש ממנו ואחרי כן גם ספרו נעים זמירות ישראל חלק רביעי, וכמעשהו בראשונים מעשהו בזה להגדיל תורה ולהאדירה ע\"י ענינים דיראת שמים ודברי התעוררות בזה אשר אז יראת ה' היא אוצרו של הלומד תורה. ולמרות מה שמסר לי הוו\"ח אי\"א נו\"נ עוסק בצ\"צ מוה\"ר ליב שי' זלמנוב, תקותי שיוסיף אומץ גם בעסקנותו בצ\"צ וכידוע פסק הירושלמי במעלת הענין וחפץ ד' בידו יצליח להוסיף אור בלבב כל אלו הנמצאים בסביבתו שיוכלו להתגבר על החשכה חשכת הגלות דדורנו דרא דעקבתא דמשיחא ולקרב עי\"ז היעוד המקווה דלילה כיום יאיר בגאולה האמיתית והשלימה ע\"י משיח צדקנו.</p>\n<p>בכבוד ובברכת הצלחה.</p>\n<h4><i><b>ב'תרסא</b></i></h4>\n<p><b> מוה\"ר יצחק:</b> גרשטנקורן. אגרת נוספת אליו - לעיל ח\"ח ב'רנא.</p>"],[1200830043,"ב'תרסב\n\n<p>ב\"ה, ל\"ג בעומר, ה'תשי\"ד</p><p>ברוקלין.</p><p>הנהלת בית הספר והסמנריון \"בית רבקה\"<br>\nיערש, צרפת<br>\nה' עליהם יחיו</p>\n<p> שלום וברכה!</p>\n<p>בנועם קבלתי הידיעה על דבר תיקון ספר זכרון לתומכי מוסדות האמורים, והריני גם אני משתתף בו בחפץ לב.</p>\n<p>ואני תפלה אשר ספר זכרון זה יתאים למה שנאמר: אז נדברו יראי ה' גו' ויכתב ספר זכרון לפניו גו' ולחושבי שמו. שבפסוק זה כלולים ג' הלבושים של הנשמה, הן שלש דרכי הפעולה של האדם: מחשבה דיבור ומעשה.</p>\n<p>ומעשה עיקר, שכל ענין הקשור במעשה בפועל - יש לו המשך וקיום, ועל אחת כמה וכמה בעניני טוב אמת וקדושה, שכללות ענינם היא - שהם נצחים,</p>\n<p>ובפרט ענין הקשור בחינוך על טהרת הקדש, ועל כולנה מוסד חינוך \"בית רבקה\", שמטרתו לא רק לחנך בנות ישראל שתהיינה ראויות לשמן, בנות שרה רבקה רחל ולאה אשר בנו את בית שראל, אלא - הוא גם מוסד המחנך מחנכות, מחנכות באופן של גידולי פירות ופירי פירות, מוסיף והולך מוסיף ואור.</p>\n<p>ויהי רצון שכל הנרשמים בספר זכרון זה, יעלה זכרונם ופקדונם לפני ה' לטובה לחן ולחסד ולרחמים ולחיים טובים ולשלום, בגשמיות וברוחניות גם יחד.</p>\n<p>בברכה.</p>\n<h4><i><b>ב'תרסב</b></i></h4>\n<p>נדפסה בלקו\"ש חכ\"ב ע' 429.</p>"],[1200830044,"ב'תרסג\n\n<p>ב\"ה, י\"ח אייר, תשי\"ד</p><p>ברוקלין.</p><p>הנהלת צעירי אגודת חב\"ד בעיה\"ק ירושלים<br>\nת\"ו<br>\nה' עליהם יחיו</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבם מי\"ג אייר, אשר נתקבל בהיום הבהיר הוד שבהוד הילולא דרשב\"י פתח את צנור ההשפעה דהענין דועלי תשוקתו בשני הפירושים אשר על ידי הפתיחה שלו ביכולת ובכח כל אחד מישראל להגיע לזה (עיין הקדמת קונטרס ל\"ג בעומר תש\"י קונטרס ע\"ח) וע\"פ הידוע בשייכות דרשב\"י אחי' השילוני הבעש\"ט ורבנו הזקן ה\"ז נוגע ביחוד לכאו\"א מאתנו המקושרים לרבנו הזקן ע\"י ממלאי מקומו הם נשיאי חב\"ד לדורותיהם עד ועד בכלל דכ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע.</p>\n<p>בו כותבים ע\"ד השקו\"ט שהיתה אצלם בהנוגע להנהלת צעירי אגו\"ח אשר בירושלים ת\"ו אשר הנהלה הקודמת אמר שקשה עלי' העבודה כו' וכו'.</p>\n<p>ומובן אשר ע\"פ הנ\"ל בהענין דל\"ג בעומר דענינו נמשך על כל השנה כולה וע\"פ הודעת הבעש\"ט בשם משיח צדקנו אשר ביאתו תלוי' לכשיפוצו מעינותיו חוצה, הנה פליאה גדולה אשר אותם שזכו לעמוד בהנהלת עבודה כזו יאמרו שקשה עליהם העבודה וכו' בה בשעה שזהו תכלית כל סדר ההשתלשלות ובריאת העולם כזה בפרט כמבואר בתניא פרק ל\"ו. מובן שהחוב והזכות על כל אחד מהחברים לסייע לההנהלה בעבודתה ככל אפשריותם, אבל להשתמט מזכות גדול כזה מלהשתדל בזה בתוספת אומץ, לכאורה הוא נגד השכל. מובן שאין פירוש מכתבי זה להתערב בהנ\"ל ואפילו לא בדרך הצעה, כי הרי כל עבודה כדי שתהי' כדבעי ובהידור צריכה להעשות בלב שמח ולא בדרך קבלת עול בלבד, אלא לעורר על פנימית עבודתם כמו שהנני רואה אותה שצריכה להיות ועל היחס שצריכה לעורר עבודה כזו. והשי\"ת יברך ויצליח את כל חברי ההנהלה בעבר ובעתיד להוסיף אומץ בעבודתם בשמחה אשר זה גופא ימעט העלמות והסתרים וההצלחה תעלה מעלה מעלה.</p>\n<p>בברכה להתקרב עכ\"פ לאט לאט לפתיחת רבי שמעון בעל ההילולא דבחד קטירא אתקטר בי' בקוב\"ה ובגין כך ועלי תשוקתו.</p>\n<h4><i><b>ב'תרסג</b></i></h4>\n<p>נדפסה בלקו\"ש חי\"ז ע' 512, והושלמה ע\"פ העתק המזכירות.</p>"],[1200830045,"ב'תרסד\n\n<p>ב\"ה, י\"ח אייר, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>... ומ\"ש מה היתה כוונתי אודות פעולותיו בכרם חב\"ד - הנני נהנה מזה שנמצא הוא בעולם המסחר, ופשיטא שלא היתה כוונתי על משרה בתור מלמד וכו', אלא שישתתף בפעולות חב\"ד בהפצת החסידות הדרכותי' ומנהגי', מתוך אהבת ישראל ובסדר מסודר, וכפי דרישת מדינה זו, אשר אין מורגלים למה שנקרא בלשונם \"ווילדקייט\" בהנהגה חיצונית, וכיון שווילדקייט כזו אין זה ענין של יראת שמים יש לוותר עלי' כיון שזה יועיל לקרב לבם של בני ישראל הנמצאים כאן לחסידות ועניני'. והשי\"ת יצליחו בכל הנ\"ל מתוך פרנסה בהרחבה ובריאות הנכונה...</p>\n<h4><i><b>ב'תרסד</b></i></h4>\n<p>נדפסה בלקו\"ש חכ\"ג ע' 516, והוגהה ע\"פ צילום האגרת.</p>"],[1200830046,"ב'תרסה\n\n<p>ב\"ה, כ' אייר, תשי\"ד</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ כו' מוה\"ר ישראל יהודא<br>\nשי'</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מג' אייר, בו כותב אשר אתמול חזר הביתה. הנה לפלא שאין מזכיר דבר ע\"ד פעולותיו בקירוב לבם של בני ישראל לאבינו שבשמים בהיותו בצבא המילואים והרי ידוע פסק דין הבעש\"ט ששמענוהו כ\"פ מכ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע שבכל ענין שאיש היהודי רואה או שומע יש בזה הוראה בעבודתו את בוראו ועאכו\"כ כשנתגלגל יהודי בסביבה חדשה למשך זמן שבודאי עליו לנצל הזדמנות זו בעבודתו את בוראו מתאים להסביבה והתנאים החדשים והרי ואהבת לרעך כמוך הוא כלל גדול בתורה וכלי למצות ואהבת את ה' אלקיך שהיא היא היסוד לכל המצות עשה שגם מצות יראת ד' בכללם והרי היראה היא יסוד לכל מצות לא תעשה. נמצא שואהבת לרעך כמוך היא כלי והכנה וסיבה לקיום כל המצות, וק\"ל ואין לך דבר העומד בפני הרצון והשי\"ת יצליחו.</p>\n<p>בברכה לבריאות הנכונה הן בגשמיות והן ברוחניות.</p>\n<h4><i><b>ב'תרסה</b></i></h4>\n<p><b> מוה\"ר ישראל יהודא שי</b><b>':</b> לוין. אגרת נוספת אליו - לעיל ח\"ה א'רלג.</p>\n<p><b> וכלי למצות ואהבת</b><b>:</b> ראה גם לעיל אגרת ב'תרנח, ובהנסמן בהערות שם.</p>"],[1200830047,"ב'תרסו\n\n<p>ב\"ה, כ' אייר, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על שאלותיו במכתבו:</p>\n<p>א) בלמדו תניא סוף פרק א' אודות מקור נפשות האומות אינם יהודים ושואל בהנוגע לנפשות חסידי אומות העולם.</p>\n<p>נפשות חסידי או\"ה נלקחים מנוגה כמבואר בכמה מקומות בדא\"ח ומהם בהנדפסים בלקוטי ביאורים על קונטרס התפעלות דף מ\"ז, עמוד ד'. וראה ג\"כ זח\"ב צה: ואילך.</p>\n<p>ב) איך הוא בגר שנתגייר, אם נשמתו נשארה כמו שהי' בגויותו.</p>\n<p>הנה ח\"ו לומר כן כי פשיטא אשר נמשכה לו נשמה דקדושה וזה ג\"כ אחד הפירושים בלשון רז\"ל גר שנתגייר כקטן שנולד דמי וראה בהקדמת ספר הזהר דף י\"ג סע\"א וריש עמוד ב' במקור נשמת הגרים.</p>\n<p>בודאי יודע מהתקנה השוה לכל נפש לאמר בכל יום אחר התפלה שיעור</p>\n<p>תהלים - כפי שנחלק התהלים לימי החודש - וכן ללמוד פרשה חומש עם פירוש רש\"י מפרשת השבוע ושומר תקנות אלו שהם סגולה גם להצלחה בלימוד תורת הנגלה ותורת החסידות.</p>\n<p>בברכה.</p>\n<p>מזכיר</p>"],[1200830048,"ב'תרסז\n\n<p>ב\"ה, כ' אייר, תשי\"ד</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ כו' מוה\"ר אהרן שי' הכהן</p>\n<p> שלום וברכה!</p>\n<p>איך בין געווען צופרידען צו באקומען א גרוס פון אייך דורך אייער ברודער הוו\"ח אי\"א נו\"נ עוסק בצ\"צ מו\"מ באמונה מוה\"ר יעקב שי' הכהן, ער שרייבט מיר אבער ניט קיינע פרטים וועגען אייך און איך האף אז אויך דאס וועט איר מיר מודיע זיין.</p>\n<p>און השי\"ת זאל אייך מצליח זיין אז דאס זאל זיין נאר גוטע בשורות וועגען זיך און אויך וועגען אייער השפעה אויף אייער אומגעבונג אויף צו מקרב זיין אידען לאבינו שבשמים יעדערען נאך זיין אופן נאך. ווארום תורה ומצות זיינען פאר אלע אידען <b>גלייך</b> מדארף אבער צו האבען א פאסענדע פאר <b>עם התחלה</b> אין דעם. איז ער א סוחר דארף ער האבען געוויסע אפגעשטעלטע צייטען אויף לערנען און דער עיקר עבודה זיינע איז אין ענינים וועלכע זיינען פארבונדען מיט מסחר, געבען צדקה, זיין אפגעהיט פון השגת גבול, גזילה וכו'.</p>\n<p>און די וועלכע זיינען מיט א כלי קדש שטעלע ווי א רב שו\"ב מלמד אדער ישיבה תלמידים דארפען אויך געבען צדקה און זיין אפגעהיט פון השגת גבול גניבה וכו'.</p>\n<p>און דער עיקר ארבעט זייערע איז צו זיין אפגעהיט אין לערנען תורה און עבודת התפלה און נאך אזעלכע ענליכע חילוקים בא פערשידענע קלאסען מענשען, חאטש ווי געזאגט פריער זיינען אלע אידען מחויב גלייך אין אלע מצות, אן קיין שום אויסרייד אז די מצוה וויל ער יע און די אנדער מצוה איז עם שווער און וויל יוצא זיין מיט א אנדערער.</p>\n<p>פון דעם איז פארשטענדליך אז דער וועלכער האט א רעדנער קראפט אדער בכל בעשאנקען מיט איינפלוס אויף באקאנטע און פריינד מוז זיין עבודה זיין צו אוועקגעבען זיך אויף פראפאגאנדע צו מאכן זיי פאר אידען לומדי תורה ומקיימי מצות.</p>\n<p>און וויבאלד אז מען מאנט דאס פון א אידען, איז זיכער אז השם יתברך גיט כחות אויף דעם צו קענען דאס אויספירען, און צאלט פאר דעם מיט ברכה והצלחה אין דעם וואס מען נויטיגט זיך אליין און די פאמיליע שיחיו און השי\"ת זאל אייך מזכה זיין צו אנזאגען גוטע בשורות אין דאס אלעס אויבען דערמאנטע.</p>\n<p>בברכת הצלחה.</p>\n<h4><i><b>ב'תרסז</b></i></h4>\n<p><b> מוה\"ר אהרן:</b> כץ. אגרות נוספות אליו - לעיל ח\"ו א'תשי, ובהנסמן בהערות שם.</p>"],[1200830049,"ב'תרסח\n\n<p>ב\"ה, כ' אייר, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>ידוע פסק המשנה אין דן יחידי אלא אחד, אשר, לדעתי - האחד הזה הוא הקב\"ה ולא בן אדם יהי' מי שיהי'... איך רעכען, אז אויב רב אשי וועלכער איז געווען א גרויסער גביר און א גדול בישראל וחד בדרא, איז ווען ער האט גע'פסק'נט א שאלה פון א בהמה, האט ער געפרעגט בא יעדער קצב פון זיין שטאט זיין מיינונג. על אחת כמה וכמה - אז דער וואס איז ניט קיין חד בדרא מעג עם אנשטיין צו הערען א מיינונג פון נאך א אידען, און ניט דרייען און פארדרייען, אז ער זאל זיין א דן יחידי אין א ענין וואס עס איז נוגע הונדערטער אידישע קינדער, און אין א ענין וואס עס איז פארבונדען מיט כ\"ק מו\"ח אדמו\"ר והרביים שלפניו - זצוקללה\"ה נבג\"מ זי\"ע. וואס במילא קען זיין אז מען איז פארבונדען מיט די רביים, אדער, ח\"ו, להיפך.</p>\n<p>... וכבר ידוע פתגם כ\"ק מו\"ח אדמו\"ר, אשר ידוע פסק המשנה שכאו\"א צריך לדונו לכף זכות, אבל יש להזהר שלא יחריבו עי\"ז ענינים דקדושה.</p>\n<p>המחכה למענה בהקדם על כל הנ\"ל.</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ב'תרסח</b></i></h4>\n<p><b> רב אשי</b><b>:</b> סנהדרין ז, ב.</p>"],[1200830050,"ב'תרסט\n\n<p>ב\"ה, כ\"א אייר, תשי\"ד</p><p>ברוקלין.</p><p>מחות' הרה\"ג והרה\"ח אי\"א נו\"נ ענף עץ<br>\nאבות<br>\nמוה\"ר אברהם יהודא שי'</p>\n<p> שלום וברכה!</p>\n<p>... בשאלתו מי מאנ\"ש הנמצאים בסביבתו מוכשרים ומסוגלים להעבודה בסידור הביכלעך, הנה צריך לברר את זה על אתר כי ההיכירות שלי אתם הוא ע\"י מכתבים ובמילא אינני מכירם בהנוגע לענין הנ\"ל ובודאי למותר להעיר לדכוותי' שכיון שכמה הרפתקאות עברו על כתבי יד אלו בודאי שיש לשמור עליהם אפילו בעבודה הנ\"ל שלא ישמשו בהם ידי זרים, ולא עביד קוב\"ה נסא במגנא, היינו סטרא דלעו\"ז ששם הענין דחנם בלא מצות ואפילו לא זר כפירוש המבואר בהמשך והחרים תרל\"א היינו זר בענין זה עיי\"ש סד\"ה והחרים.</p>\n<p>ובפרט אתענין כיון שמוצאים עתה לאור דרושי הרה\"צ כו' ר' הלל מפאריטש על ס' שמות שנמצא כאן ביכל מסודר כתבנית פלח הרמון על ס' בראשית, הנה אם יש בין מאמרים הנ\"ל שבביכלעך שכותב אודותם גם מאמרים הנ\"ל על ס' שמות אפשר שיש בהם מילואים וכו' אף שבכלל הביכעל שתחת ידי כאן מסודר הוא לדפוס ולא עוד אלא שעבר עליו גם בקורת הצנזורה מלפנים כנראה מהתיקונים השונים שבו...</p>\n<p>כבקשתו אזכירו ואת כל אלו שכותב אודותם בהיותי על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע והשי\"ת יזכה את כאו\"א מאתנו להודיע טובות בגשמיות וברוחניות.</p>\n<p>בכבוד ובברכה מחות'.</p>\n<h4><i><b>ב'תרסט</b></i></h4>\n<p><b> מוה\"ר אברהם יהודא</b><b>:</b> חן. אגרות נוספות אליו - לעיל ח\"ח ב'שלט, ובהנסמן בהערות שם.</p>\n<p><b> בסידור הביכלאך:</b> מעזבון אביו הרד\"צ. ראה לעיל שם.</p>"],[1200830051,"ב'עתר\n\n<p>ב\"ה, כ\"א אייר, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>... בקשר עם מ\"ש במכתבו, הרי בטח למותר לעוררו עוד הפעם על המצווה בתוה\"ק לשמור על בריאות הגוף וכמבואר ג\"כ בהמאמר דיו\"ד שבט דהאי שתא ובכמה מקומות, ודבר פשוט כזה אין צריך ראיות נוספות ובמילא אופן הלימוד שלו או המחשבה בדברי תורה בודאי יש לסדרם באופן שלא יגעו במצב בריאותו, ולא יטעה א\"ע לאמר כי טענת הבריאות הם באים מצד היצה\"ר, אף שלפעמים כן הוא אבל בכלל הציווי בכל דרכיך דעהו ה\"ז עיקר גדול שיהי' הגוף בריא ושלם, ובמילא כשמרגיש עיפות בלימודו או כשחוזר במחשבה על לימודו, הרי או שיחליף את הלימוד ללימוד מסוג אחר או שיפסיק לשם מנוחה לאיזה זמן, שמלבד שזהו מצוה וכנ\"ל הרי גם בענין הת\"ת עצמה ה\"ז הכנה כדי שאפשר יהי' הלימוד לאח\"כ ובכמה ענינים הכשר מצוה כמצוה.</p>\n<p>בודאי עלה לתורה בסמיכות ליום הולדתו וכן נתן לצדקה ביום הולדתו לפני תפלת הבקר ותפלת המנחה וכל הנ\"ל ימשיך לו תוספת ברכה והצלחה בעניניו הפרטים ובעסקנותו בכרם חב\"ד.</p>\n<p>בברכת הצ' ופ\"ש אנ\"ש שי'.</p>\n<h4><i><b>ב'עתר</b></i></h4>\n<p><b> בהמאמר דיו\"ד שבט דהאי שתא:</b> באתי לגני תשי\"ג (אות ו), שנדפס בתחלת שבט תשי\"ד, כדלעיל אגרת ב'תרנג. ח\"ח ב'תעו. ב'תקסא. ב'תקסד. לקמן ב'תשכד. ב'תשפ.</p>\n<p>ב'תתקח. וראה גם לעיל ח\"ז אגרת ב'נה, ובהנסמן בהערות שם.</p>\n<p><b> יום הולדתו</b><b>:</b> ראה גם לעיל ח\"ח אגרת ב'שנ, ובהנסמן בהערות שם. לקמן ב'תשמא.</p>\n<p>ב'תשסא. ב'תשצז.</p>"],[1200830052,"ב'תרעא\n\n<p>ב\"ה, כ\"א אייר, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ג והרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמוה\"ר יוסף שי'</p>\n<p> שלום וברכה!</p>\n<p>... ולהודעתו אשר ביום ג' אייר נמלאו לו שלש שנים לבנם יצחק שי', הנה יה\"ר מהשי\"ת שהוא וזוגתו שיחיו יגדלוהו לתורה ולחופה ולמעשים טובים מתוך בריאות הנכונה ומנוחת הנפש והגוף.</p>\n<p>בברכת הצלחה בעבודתו הק' ולבשו\"ט בכל</p>\n<p>הנ\"ל.</p>\n<p>נ.ב.</p>\n<p>במה שכותב אודות עשיית התספורת. הנה כבר כתבתי דעתי בזה שאף שע\"פ תורת הנגלה יש להתיר ועוד יותר ע\"פ המבואר בשערי תשובה לאו\"ח סי' תקל\"א. הנה בכ\"ז נשען על מנהג ישראל לעשות במירון תספורת תינוקות בל\"ג בעומר וכמובא בכ\"מ, והרי פשיטא שכל אלו שמסתפרים אז לא כולם נולדו ביום זה במכוון, ובכ\"ז מגלגלין ענין זה ליום זכאי, ויש לבארו ע\"פ המובא בכתבי האריז\"ל ובפע\"ח וכו', על אודות השייכות דנטילת שערות דוקא עם ימי הספירה, שמזה גופא מובן ההידור בתספורת בל\"ג בעומר (וצ\"ע קצת מהמובא באיזהו מקומן שהאריז\"ל לא הי' מסתפר אפילו בל\"ג בעומר) לכן נראה לי שהתספורת תעשה בל\"ג בעומר ויהי' בשעה טובה ומוצלחת.</p>\n<h4><i><b>ב'תרעא</b></i></h4>\n<p><b> מוה\"ר יוסף</b><b>:</b> גולדברג.</p>\n<p><b> כבר כתבתי</b><b>:</b> לעיל ב'תרכד, ובהנסמן בהערות שם.</p>"],[1200830053,"ב'תערב\n\n<p>ב\"ה, כ\"א אייר, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>זה עתה נתקבל מכתבו מג' בהר וכן הקודם לו... וכיון שבידי אנ\"ש להפיץ ספרי חב\"ד בממדים גדולים באה\"ק ת\"ו והדרישה עליהם רבתה ג\"כ והמחיר לפ\"ע אינם גדולים וגם בעיני בשר נראית בזה הצלחה למעלה מדרך הטבע הרי יושבין בחיבוק ידים! וכמעט בכל מכתב ומכתב מסתפק בהודעה אשר העסק חלש והחוב במקומו עומד אף שתומ\"י מסיים שיש על מה שתחול הברכה.</p>\n<p>והרי עתה בעשיריות מקומות באה\"ק ת\"ו נמצאים אנ\"ש או מגזע אנ\"ש או גם מצעירי אגו\"ח או עכ\"פ כאלו שעמהם עומדים בקישור בזמן האחרון ופשיטא שע\"י טובת הנאה היינו באופן של סרסרות וכיו\"ב היו מפרסמים וגם משמשים ממוצעים למכירת הספרים והקונטרסים לחוגים היותר רחבים ובלבד שלא יעלו המחירים יותר מכפי ההכרח ויעבדו בהנ\"ל במרץ הדרוש ובסדר מסודר, והרי יש בזה גם ענין רוחני גדול במאד שיגיעו הספרים והקונט' לכאלו שעד עתה לא היתה מציאות שיגיעו אליהם או שיעיינו בהם.</p>\n<p>מובן שכיון שהוא המו\"ס צריך לקחת חלק בראש כל עבודה הנ\"ל אבל לאידך גיסא מובטחני שאנ\"ש הצעירים והזקנים יסייעו בכל זה, והרי הפצה היא אחד מהסניפים העיקרים בעבודת אנ\"ש בכל מקום ומקום והאריכות אך למותר. מבלי רצוני לכפול את כל זה הרי טוב וכדאי שיפרסם דברי או גם יציעם באסיפה הקרובה של אגו\"ח וצעירי אגו\"ח ותשועה ברוב יועץ.</p>\n<p>בברכה לבריאות הנכונה לו ולכל ב\"ב שיחיו המחכה לבשו\"ט בכל הנ\"ל.</p>\n<h4><i><b>ב'תערב</b></i></h4>\n<p><b> ספרי חב\"ד... באה\"ק:</b> ראה גם לעיל אגרת ב'תרמז.</p>"],[1200830054,"ב'תרעג\n\n<p>ב\"ה, כ\"א אייר, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מג' אייר. בו כותב אודות מצבו והקישויים השונים בהשגת משרה.</p>\n<p>הנה מה שתולה זה בדתיותו שעי\"ז החפשים רודפים אותו. הנה כבר ידוע ברכות המזון שהוא מן התורה אשר דוקא הקב\"ה הוא זן ומפרנס את הכל ובמילא גם הוא בכלל ומה יעשה לו אדם כשהקב\"ה רוצה לפרנסו, ובמילא מובן שאם ישנם קישויים בפרנסה הרי זה תלוי במעשיו ולא ברצונו של בן אדם שאין לו תשועה, וכשמוסיפין בלימוד התורה וקיום המצות אזי מוסיף הקב\"ה ברכותיו הן בגשמיות והן ברוחניות וכמרז\"ל כל המוסיף מוסיפין לו, ואף שכל הנ\"ל פשוט הוא בכל זה העליתי זה על הכתב כיון שכנראה ממכתבו לפעמים יש אצלו מחשבה שאחרים שליטה להם עליו בנוגע לפרנסתו.</p>\n<p>בהנוגע ל... תחי' הנה צריך הי' לברר בהקדם הנהגתה בדיני טהרת המשפחה והעיקר בנוגע למקוה שתהי' מקוה כשרה בהידור ע\"י מי גשמים או מי מעיין, אבל לא ממימי העיר ח\"ו, הם העוברים דרך כמה כלים מודדי מים וכו' וכשתזהר בהנ\"ל כדבעי בטח יוטב ג\"כ מצבם המשפחתי והשי\"ת יזכהו ויצליחו לבשר טוב בכל הנ\"ל.</p>\n<p>לפלא שאינו מזכיר ע\"ד שיעוריו בלימוד תורת החסידות נוסף על לימודו בנגלה דתורה.</p>\n<p>בברכה המחכה לבשו\"ט.</p>"],[1200830055,"ב'תרדע\n\n<p>ב\"ה, כ\"א אייר, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מט\"ז אייר.</p>\n<p>א) בהנוגע לעסקנותו בעניני הרישום הפצת וכו', הנה מובן שצ\"ל זה בהסכמת הנהלת הישיבה ובודאי יש למצוא אופן לסדר את הנ\"ל שלא יבלבלו ויפריעו מלימודו בתורת הנגלה ומלימודו בתורת החסידות, ואף אם לפעמים רחוקים לא יתאימו הזמנים הרי בטח ימלא בשעות הפנויות מה שחיסר באקראי בלימודו בנגלה ובחסידות.</p>\n<p>ב) מ\"ש אודות נסיעה לארצוה\"ב ללמוד כאן, הרי עוד רבות יש לעשות ולהשתלם בישיבתו באה\"ק ת\"ו, וילמוד במסירה ונתינה ושקידה המתאימה ומבלי לבלבל את עצמו במחשבת נסיעה וכו' וכו' לעת עתה.</p>\n<p>ג) במ\"ש אודות אי התמדתו בלימודו בתורת הנגלה כו' הרי ידוע עד כמה הקפידו רבותינו נשיאנו הק' על השקידה בלימוד הנגלה וכבר ארז\"ל יגעת ולא מצאת אל תאמין ובמילא בידו הדבר שאם רק ירצה באמת ילמוד בשקידה וגם יצליח, מובן אשר לאחרי ההפסק בזה כל התחלות קשות אבל מזמן לזמן יהי' לו זה בנקל יותר ובלבד שישתדל בזה אליבא דנפשי', וה\"ה גם בנוגע ללימוד החסידות שבטח גם לימוד זה יכול להשתפר יותר, ובהסכם הר\"מ והמשפיע שלו הנה יש לחלק זמני חזרתו על הלימודים באופן שלא יוצרך ללמוד משך שעות בענין אחד כי אם בסרוגין אשר עכ\"פ בזמן הראשון יגרה זה את החשק ללמוד וכבר ידוע מרז\"ל לעולם ילמוד אדם במקום שלבו חפץ.</p>\n<p>בודאי שומר שלשת השיעורים השוים לכל נפש מתקנת כ\"ק מו\"ח אדמו\"ר</p>\n<p>זצוקללה\"ה נבג\"מ זי\"ע בחומש תהלים ותניא הידועים, ולקח ג\"כ מסכת בחלוקת הש\"ס ומזמן לזמן נותן לצדקה איזה פרוטות והשי\"ת יצליחו.</p>\n<p>בברכה,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>"],[1200830056,"ב'תרעה\n\n<p>ב\"ה, כ\"א אייר, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מיום ד'... הנה מצורף בזה הערותי, ומובן שאין זה בתור הסכמה שאין מדרכי בזה, ומובן ג\"כ שאם לא יושמטו מהדפוס מה שלפי דעתי יכול להביא למכשול הרי אין רשות גם להזכיר שראיתי את הכתב יד בכדי שלא יתפרש הדבר שגם לי חלק בהמכשול.</p>\n<p>בברכה.</p>\n<p><b> הערות</b><b>:</b></p>\n<p>ובהקדמה, א) בספרים הנכתבים בשפה המדוברת, היינו שהם נועדים גם בשביל האיש הפשוט, שיש להשמיט כל הענינים שלפי הבנת איש הפשוט יעוררו אצלו רגש של זלזול בענינים דתורה ומצות.</p>\n<p>ב) יש להשמיט כל הענינים הדורשים ביאור רחב או עמוק, שבמילא אי אפשר להביאם בספר זה.</p>\n<p>ג) יש להשמיט כל ענינים שאצל הקוראים הפשוטים מתפרש זה אשר ישנן שתי תורות או כמה תורות אצל בני ישראל, היינו כל עניני מחלוקת וכו'.</p>\n<p>ד) יש לברר התבן מן הבר, היינו שלא לערב ענינים חילוניים לגמרי, כיון שהקורא משוה להם את שאר הענינים שבספר.</p>\n<p>ה) יש להשמיט כל הענינים התלוים במפלגה. היינו שמפלגות השונות בישראל דנים ומחולקים בהם. ובהתאם לכל הנ\"ל הנני בא על סדר העמודים.</p>\n<p><b> עמוד ב':</b> להשמיט השורות המדברות במנהג מבטל הלכה וכו', כי עמא דבר באמריקה יבטלו עשיריות הלכות מהשו\"ע מפני המנהג שנהגו, ופשיטא שלא יעיינו בספרים המבארים מפני מה ומה הם המנהגים שעליהם אמרו מנהג אותיות גהנ\"ם (שד\"ח כללים מע' מנהג).</p>\n<p><b> עמוד ד' ושלאחריו</b><b>:</b> בכל מקום שכתב שם הבורא באידיש וה\"ה באנגלית, יש לכתוב ג-ט, ולא בשלימות, שלפ\"ד כמה מאחרונים חל על זה קדושת השם.</p>\n<p><b> עמוד ז':</b> דריי שטערן. הנה עמא דבר שאין מבחינים בין גדולים לקטנים וכו' ובמילא יש לכתוב \"ווען עס ווערט נאכט\" וכיו\"ב.</p>\n<p><b> עמוד ח':</b> קידוש על חלב, הנה אף שיש למצוא סמיכות לזה, אבל דבר תמוה הוא ביותר, ובברכי יוסף ושערי תשובה - והובאו במשנה ברורה בסימן ער\"ב - פסקו בפירוש שאין לעשות קידוש והבדלה על חלב.</p>\n<p><b> עמוד יו</b><b>\"</b><b>ד</b><b>:</b> עיין בסי' רפ\"ה, שהמצוה היא להעביר הסברה בעש\"ק, ורק באונס עושים זה בשבת.</p>\n<p><b> בעמוד הנ\"ל:</b> הנה יש שבתים בשילהי קייטא שאומרים שני פרקים בשבת אחת.</p>\n<p><b> עמוד</b><b>י</b><b>\"</b><b>א</b><b>:</b> להשמיט ע\"ד הבדלה על חלב, וכן להוסיף בסדר הבדלה שאומרים הנה א-ל ישועתי.</p>\n<p><b> עמוד י\"ג:</b> איסור הוצאה היא גם מכרמלית ולא רק מרשות הרבים. כן מה שהוא מפרש אופן עשיית העירוב יש להשמיט. כי הלכות עירובין מסובכים ביותר ולא כמו שיבין הקורא במה שכתב, וה\"ה בנוגע לערובי תחומין שכיון שאין ענינו כ\"כ בספר הזה יש להשמיטו, כיון שלהעיר מצרפין ג\"כ הבתים שמחוץ לעיר וכו' וכמה פרטים בזה.</p>\n<p><b> עמוד י\"ד:</b> מה שכותב ששמאי הזקן הוא בית שמאי, אינו מובן, כי המדובר הוא בהלל ושמאי עצמם ולא בתלמידיהם.</p>\n<p><b> עמוד ט\"ו:</b> שהשבת הוא לכל בני אדם, הנה זהו היפך הדין דעכו\"ם ששבת חייב מיתה, ולכן יש להשמיטו, וכן את הסיפור דתבלין יש לנו ושבת שמה שאיש הפשוט לא יבינו.</p>\n<p><b> עמוד ט\"ז י\"ז וי\"ח:</b> יש להשמיט כל הענין דסמבטיון, כיון שמקומו תלוי במחלוקת גדולה ולא כמו שכותב בפשיטות שזהו בדרום דמדינת עטיאפי וגם בהספורים דמסעות ר' גרשון, הרבה מערערים עליו, ובפרט במה שמסיים לא תבערו אש ומפרשו כפירוש הקראים.</p>\n<p><b> עמוד כ':</b> למחוק מלת \"גענויע\" כי מולדנו הוא מולד האמצעי ולא האמיתי. מפטיר דשבת ראש חדש מתחילין וביום השבת ולא ובראשי חדשיכם וכן להשמיט התיבה \"פרומע\" כיון שזהו מנהג המובא בשו\"ע.</p>\n<p><b> עמוד</b><b>כ</b><b>\"</b><b>א</b><b>:</b> קידוש הלבנה אין לקרותו בשם מנהג בעלמא, וכן אין לערבו עם מאמר הברייתא דמברכין על החמה לבנה וכוכבים, שאין זה קידוש לבנה דכל חדש לרוב המפרשים. כן מה שכותב בסוף העמוד שם שבכל שלש שנים מוסיפים חדש העבור אינו, וכידוע הסימן: גוחאדז\"ט.</p>\n<p><b> עמוד כ\"ב:</b> מ\"ש בעניני דקידוש החמה שחוזרת למקומה הראשון משם נוטלת אורה וחמימותה, <b>אינו</b>, וכן מ\"ש שהתחלת התקופה או בלילה הרביעי דחדש ניסן, ג\"כ אינו. כי הוא ביום ד' בשבוע ולא ביום ד' לחדש, וכן אין זה המקום שמשם נוטלת אורה וכו' וכמבואר בהלכות קידוש החדש להרמב\"ם ועוד.</p>\n<p><b> עמוד כ\"ב/ב:</b> במה שמפרש ירח <b>בול</b> שהעשבים הם יבשים או שיורדים גשמים חזקים.</p>\n<p>מובן שזהו סתירה מני' ובי'.</p>\n<p><b> עמוד כ\"ג/ג:</b> יש להשמיטו כולו. כיון שפירושו - מחלוקת גדולה בזה.</p>\n<p><b> עמוד</b><b>כ</b><b>\"</b><b>ד</b><b>:</b> בביאור ענין המלאכות האסורות ביום טוב, ה\"ז דורש ביאור ארוך בחילוקי המלאכות וכמבואר במפרשי הש\"ס ונ\"כ מפני מה כמה מלאכות התירו וכמה מלאכות אסורות, ואין מתכלית ספר זה לברר.</p>\n<p><b> עמוד</b><b>כ</b><b>\"</b><b>ה</b><b>:</b> שבארץ ישראל אין יו\"ט שני של גליות וכו'. יבלבל זה את הקורא הפשוט ואתי לזלזולי וכחששת רז\"ל וספר שנדפס באידיש או באנגלית אין להביא כלל את זה, כיון שאין נוגע לכל הארצות ויש להשמיט את כל החילוק דמנהגי ארץ ישראל בזה.</p>\n<p><b> עמוד</b><b>כ</b><b>\"</b><b>ו</b><b>:</b> מ\"ש דעירוב תבשילין הוא תקנת הגאונים. תמי' גדולה. כי נמצא זה במשנה.</p>\n<p>כן יש להשמיט החילוקי מנהגים בהנחת תפילין בחול המועד מפני טעמים הנ\"ל.</p>\n<p><b> עמוד כ\"ז:</b> שבאסרו חג אין אומרים למנצח בנגינות. תמי' גדולה, וכנראה צ\"ל למנצח יענך.</p>\n<p><b> עמוד כ\"ח:</b> הביאור דחמץ שזהו ענין שיש בו דבר חמוצי. הנה מלבד שאינו נכון עלול להביא כמה קלקולים ומכשולים וכן מ\"ש אודות מי פירות ויין צמוקים.</p>\n<p><b> עמוד ל':</b> בסופו שספירת העומר ניתנה בשביל בני ישראל הדרים בארץ ישראל הוא תמוה ובפרט לדעת הפוסקים שגם עתה בחו\"ל הוא דאורייתא.</p>\n<p><b> עמוד ל\"א</b> שבשבת חוה\"מ קורין ששה קרואים בספר הראשון, תמוה.</p>\n<p><b> עמוד</b><b>ל</b><b>\"</b><b>ב</b><b>:</b> ביאורו דל\"ג בעומר שזהו תלוי במלחמת בר כוכבא וכו' הנה זהו היפך הש\"ס, אף שנמצא בספרי המשכילים.</p>\n<p><b> עמוד ל\"ה:</b> להשמיט הסיפור דר' חיים בריסקער וכן הסיפרו דר' לוי\"צ - זצ\"ל בעמוד ל\"ו מפני טעמים הנ\"ל.</p>\n<p><b> עמוד ל\"ט:</b> להשמיט החילוקי מנהגים אודות אילנות בחג השבועות, וכנ\"ל.</p>\n<p><b> עמוד מ\"א:</b> כמדומה שכבר בטלו <b>בכל</b> הקהלות לאמר יציב פתגם <b>בתוך</b> ההפטרה.</p>\n<p><b> עמוד</b><b>מ</b><b>\"</b><b>ב</b><b>:</b> להשמיט כל הענין דמואבי ולא מואבית (בהנוגע לדוד).</p>\n<p><b> עמוד</b><b>מ</b><b>\"</b><b>ה</b><b>:</b> להשמיטו, כי אין מתפקיד ספר זה להחליש ענין אמירת תיקון ליל שבועות.</p>\n<p><b> עמוד נו\"ן:</b> במה שהעתיק <b>מספרים שקדמוהו</b> שר' אמנון פסק דינו במה שיענישוהו הנה צריך עיון אם אמיתי הוא, כי אסור לחבור בעצמו. וידוע שכמה ענינים בשלשלת הקבלה מפוקפקים ולא אמיתים, וכמובא בכמה מקומות.</p>\n<p>עמוד נ\"א ונ\"ב: שגדלי' נהרג ע\"י בני משפחת צדקי' הכהן וכן שברש\"י שבת מובא מנהג כפרות <b>שלאגין</b>, תמיהה. ובעמ' נ\"ב יש להשמיט דעת אלו שחוששין לדרכי האמורי במנהג דכפרות, וכנ\"ל בהקדמה.</p>\n<p><b> עמוד נ\"ג:</b> להתפלל מנחה באלד נאך 12. הנה יש אומרים שתפלה בטלה היא. ועל כל פנים צריך להיות חצי שעה לאחר זה. כן יש להשמיט בעמוד זה דעת אלו שהם נגד אמירת כל נדרי, כיון שעתה נתקבל מכל בני ישראל אשכנזים. כן מה שכותב לאמר בליל יום הכפורים לשנה טובה, תמיהה גדולה.</p>\n<p><b> עמוד נ\"ה:</b> יש להשמיט הסיפור מר' דוד לעלעווער, דכיון שבכל ארצוה\"ב, נתקבל הענין לילך לבית הכנסת ביום הכפורים, אין להורות היתר על ידי סיפורים כמו אלו. ומטעם זה יש להשמיט גם הסיפור שקדם לזה.</p>\n<p><b> עמוד</b><b>נ</b><b>\"</b><b>ט</b><b>:</b> הנענועים צ\"ל גם למעלה ולמטה ולא רק לד' רוחות.</p>\n<p><b> עמוד</b><b>ס</b><b>\"</b><b>א</b><b>:</b> להשמיט פירוש רש\"י דרגל בפ\"ע שאין יושבין בסוכה - שזהו בעיקר לארץ ישראל שאין שם ספיקא דיומא.</p>\n<p><b> עמוד ס\"ד:</b> מ\"ש שחנוכה הוא תמיד עד יום השני בטבת, אינו מתאים, כי כסלו לפעמים כ\"ט ולפעמים ל' יום.</p>\n<p><b> עמוד ס\"ו:</b> אין לערב הפירוש בנגה\"ש המובא בספרי גדולי ישראל דדורות הקודמים עם הר\"ת, דאידיש ואנגלית.</p>\n<p><b> עמוד ע':</b> בענין נטיעת עצים בט\"ו בשבט, הנה אין לערב את זה במנהגי שו\"ע וכו' ויש להשמיטו מספר שצ\"ל שוה לכל.</p>\n<p><b> עמוד ע\"ג:</b> מחצית השקל צריך לתת לכתחלה עכ\"פ בתענית אסתר ולא בפורים. כן יש להשמיט בעמוד הנ\"ל העתקת מרז\"ל דחייב אינש לבסומי' וכו'.</p>\n<p><b> עמוד ע\"ד:</b> בענין שושן פורים. הנה בכמה מקומות באה\"ק ת\"ו חל דין זה גם עתה ולא רק בירושלים.</p>\n<p>נ.ב.</p>\n<p>בכדי להקל למצוא מקום הערותי נעשה בסימן בעפרון בהעתקת כתבו שיש להסירו בקל.</p>\n<h4><i><b>ב'תרעה</b></i></h4>\n<p><b> בנגה</b><b>\"</b><b>ש</b><b>:</b> בנס גדול היה שם.</p>"],[1200830057,"ב'תרעו\n\n<p>ב\"ה, כ\"א אייר, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמוה\"ר חיים הלל שי'</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מיום הבהיר ל\"ג בעומר ות\"ח ת\"ח על הבשו\"ט ע\"ד התועדות שעשו בשביל התלמידים בקשר עם יום בהיר זה ובודאי גם על להבא ישתדלו בענינים כמו אלו וכבר ידוע פסק רז\"ל גדולה לגימה שמקרבת ובפרט בהנוגע לילדים ולילדות שאמרו בזה לעולם תהא ימין מקרבת וכו'.</p>\n<p>בודאי משתדל ביתר שאל וביתר עז בקשר עם ימי החפש הממשמשים ובאים אשר אז כמה ילדים פנוים מהלימוד בבתי ספר המלוכה ובמילא רוצים ההורים שיהיו ילדיהם עסוקים עכ\"פ איזה שעות ביום. ולכן זהו שעת הכושר להודיעם ע\"ד פעולות תו\"ת והת\"ת ולשדלם בדברים שילמדו באחד המוסדות הנ\"ל המתאימים וכשהיחס אליהם כשיהיו בהמוסדות באופן המתאים יש לקוות שמספר נכון מהם ישארו בד' אמות של חב\"ד.</p>\n<p>כבקשתו אזכירו ואת כל ב\"ב שיחיו בהיותי על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע לבריאות הנכונה והשי\"ת יצליחם בכל הנ\"ל.</p>\n<p>בברכת הצלחה.</p>\n<h4><i><b>ב'תרעו</b></i></h4>\n<p><b> מוה\"ר חיים הלל</b><b>:</b> אזימוב. אגרות נוספות אליו - לעיל ח\"ח ב'תנג, ובהנסמן בהערות שם.</p>"],[1200830058,"ב'תרעז\n\n<p>ב\"ה, כ\"ג אייר, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו, בו מתאר מצבו ושואל חוות דעתי אם ילמוד בישיבת תומכי תמימים בלוד או בבית ספר למלאכה והוא כבן ארבע עשרה וחצי שנה.</p>\n<p>הנה בכלל כדי להצליח בלימוד צריך להיות הענין דקבלת עול ומשמעת וכסיפור רז\"ל שדוקא עי\"ז שישראל הקדימו נעשה לנשמע זכו לקבלת התורה שמזה לומדים אנו לסדר קבלת לימוד איזה שיהי'. ולכן ילמוד בישיבת תומכי תמימים בלוד במסירה ונתינה בשקידה ובהתמדה ואז בודאי יצליח וכפסק רז\"ל יגעת ומצאת הן בלימוד תורת הנגלה והן בלימוד תורת החסידות וקיום המצות בהידור ובמשך הזמן כשיראה שיכול להתגבר על יצרו בלימוד תורת ה' הרי יוכלו לחשוב גם ע\"ד סידורו בבי\"ס למלאכה, אבל לא קודם שיראה עצמו וגם יראה לאחרים שהמוח שליט על הלב בהנ\"ל.</p>\n<p>בטח אומר בכל יום אחר תפלת שחרית השיעור תהלים כפי שנחלק התהלים לימי החדש ומזמן לזמן פרוטה לצדקה והשי\"ת יצליחו.</p>\n<p>בברכה,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>"],[1200830059,"ב'תרעח\n\n<p>ב\"ה, כ\"ד אייר, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מכ' אייר. ומה ששואל מה כוונתי לפעולות הטובות שעליו לעשות.</p>\n<p>הנה פשוט הדבר בכמה מקומות בספרנו הק' ולכל לראש בפסק דין דר\"ע אשר ואהבת לרעך כמוך הוא כלל גדול בתורה, ובמילא כמו שמחויב להשתדל בעצמו בלימוד התורה ובקיום המצות הנה צריך לעשות בזה להשפיע גם על זולתו בכיוון זה, והוא בקביעות שיעורי לימוד ברבים (מובן שהלימוד צריך להיות בדבר המובן לרבים, היינו קיצור שו\"ע עין יעקב חומש וכה\"ג) וסידור שיעור תהלים לאמרו לאחרי התפלה בבית הכנסת ולעורר ע\"ד קיום מצות מעשיות וכו' וכו'. מובן שבכל מקום ומקום משתנים אופני התעמולה בזה אבל השינוי הוא רק בהאופנים אבל לא במטרת התעמולה שהוא קירוב לבם של בני ישראל לאבינו שבשמים ע\"י זירוזם בלימוד התורה וקיום המצות, ויגעת - ומצאת.</p>\n<p>כבקשתו אזכירו ואת כל ב\"ב שיחיו בהיותי על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע והשי\"ת יצליחו בכל הנ\"ל.</p>"],[1200830060,"ב'תרעט\n\n<p>ב\"ה, כ\"ד אייר, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>נתקבל פ\"נ שלו ע\"ד בתו... תחי' וכבקשתו אזכירה לרפו\"ק ולרפו\"ש ואחכה לבשו\"ט.</p>\n<p>ישתדל להמציא לה ושתאכלם עכ\"פ ד' זיתים של מיכאל דאסוותא (שהוא ג\"כ) מיכלא דמהימנותא - אמונה (שהיא בחי' רגל בחי' בת) בהוי' ובמשה עבדו ובאתפשטותא דבכל דרא שבדורנו הוא כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה זי\"ע - הנאפה על ידי לשכתו דוקא.</p>\n<p>ויה\"ר שמכאן ולהבא יראו השגחה פרטית רק בענינים של טוב הנראה והנגלה.</p>\n<p>בברכה.</p>\n<h4><i><b>ב'תרעט</b></i></h4>\n<p><b> על ידי לשכתו:</b> ראה לעיל אגרת ב'תרמא. לקמן ב'תשעד.</p>"],[1200830061,"ב'תרפ\n\n<p>ב\"ה, כ\"ה אייר, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>נתקבל מכתבו מט' אייר וכן המברק, ובודאי קבל המענה שלי במברק, רפואה קרובה המחכה לבשו\"ט, ויה\"ר שימלא בקשתי בהקדם האפשרי.</p>\n<p>נבהלתי לקרות במכתבו אשר תולה הענינים בקפידא ח\"ו שלי, כי אין זה מעניני להקפיד כו' וכו' והלואי שיתלו בי כל המאורעות הטובים בגשמיות וברוחניות, והשי\"ת יצליחו שגם הוא יהי' בין אלו...</p>\n<p>המחכה לבשו\"ט בכל הנ\"ל ובברכה לקבלת התורה בשמחה ובפנימיות.</p>"],[1200830062,"ב'תרפא\n\n<p>ב\"ה, כ\"ח אייר, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמוה\"ר יהושע [שניאור זלמן] שי'</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מי\"ט אייר, ולפלא עליו שלאחר שראה, הוא וכן כללות אנ\"ש, הצלחה מופלגה בענין הישיבה במציאות הבנין וקנינו כו', הנה על כל צעד ושעל עדיין מלאים הם ספיקות, וכלשונו במכתבו, אין להם שום ציור ובאיזה אופן לגשת אל העבודה - וזה לאחרי שמתעסקים בזה איזה שנים, ונתקרבו בע\"ב, כאלו שמראש לא פללו לזה, נוסף על הענין שגם ילדי ה... נצטרפו עליהם כו' וכו'. וכ\"ש וק\"ו - ומה במדינתם לפנים, שהי' הדבר קשור במס\"נ, הרי התעסקו בחינוך ולא התנו תנאים עם הבורא ית' שיראה נסים על כל צעד וצעד ובא\"ל א\"א להמשיך בעבודה, עאכו\"כ במדינתם עתה, שאפילו בדרך הטבע ישנה אפשריות להמשיך בהדבר, ועאכו\"כ שאין מקמצים בנסים - אלא שצריך להתבוננות קלה ופקיחת עינים במקצת עכ\"פ...</p>\n<p>נהניתי ממ\"ש אשר במשך ביקורו בסידני נפגש עם כמה אברכים מי שהיו תלמידי אהלי\"י מלפנים, ובודאי גם להבא יעמוד עמהם בקשר מכתבים ולהשתדל ג\"כ שיחזרו להישיבה לכה\"פ על משך איזה זמן.</p>\n<p>מ\"ש אשר משפחת פייגלין שיחיו השאירו ההמחאות ששלחו מכאן בשביל הישיבה אצלם לזכרון, והכניסו להבאנק ע\"ח הישיבה חילופם ובאיזה תוספת. הנה אם הנהלת הישיבה נתנה הסכמתה על כך הרי יישר חילם. המחכה לבשו\"ט בכל הנ\"ל ובברכת הצלחה בעבודתו בקדש ובעניניו הפרטים, הוא וכל ב\"ב שיחיו ולקבלת התורה בשמחה ובפנימיות.</p>\n<p><b>מ. שניאורסאהן</b></p><p>נ.ב.</p>\n<p>בטח התועדו במשך ימי חג הפסח ול\"ג בעומר ויעשו כן גם בחג השבועות. ות\"ח אם יודיע פרטים בזה.</p>\n<h4><i><b>ב'תרפא</b></i></h4>\n<p>נדפסה בלקו\"ש חכ\"ג ע' 477, והושלמה ע\"פ צילום האגרת.</p>\n<p><b> מוה\"ר יהושע שניאור זלמן שי':</b> סרברנסקי. אגרות נוספות אליו - לעיל ח\"ח ב'שכח, ובהנסמן בהערות שם. לקמן ב'תשכז. ב'תשעב. ב'תתקכ. ב'תתקנו.</p>\n<p><b> הישיבה:</b> במלבורן. ראה לעיל אגרת ב'תרנ, ובהנסמן בהערות שם.</p>"],[1200830063,"ב'תרפב\n\n<p>ב\"ה, כ\"ח אייר, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על שאלתו מאז שאינו רוצה ללמוד ושואל אם ללכת לנח\"ל של פא\"י וכו'.</p>\n<p>הנה לדעתי ילמוד עוד שנה בישיבת תומכי תמימים בלוד במסירה ונתינה המתאימה, ומה שכותב שאינו רוצה, הנה הוא די מבוגר להבין אשר השכל צריך להיות שליט על הרצון ולא הרצון על השכל, אשר בגישה כזו יצליח בלימודו וכעבור השנה וירצה לעבוד בחקלאות או להסתדר באופן אחר יכתוב לי עוד הפעם. מובן שבכתבי שנה אין כוונתי ארבעה חדשים עד תום שנת תשי\"ד אלא לשנה כפשוטה היינו לערך י\"ב חדש.</p>\n<p>בטח אומר אחר התפלה בכל יום בקר איזה קאפיטלעך תהלים אשר גם זה אחת הסגולות שינחהו השי\"ת בדרך הטובה לפניו בגשמיות וברוחניות גם יחד.</p>\n<p>בברכה,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>"],[1200830064,"ב'תרפג\n\n<p>ב\"ה, כ\"ח אייר, תשי\"ד</p><p>ברוקלין.</p><p>אין ענטפער אויף אייער בריף פון ל\"ח לעומר און אויך די ידיעה דורכן טעלעפאן.</p>\n<p>עס איז מיר א וואונדער אויף אים, אז חאטש איר האט געזעהען אין אייער פערזענליכען לעבען און על אחת כמה וכמה אין דעם לעבען פון אנדערע נפלאות השי\"ת, און צייטענווייז אפילו ווען עס האט זיך ניט געזעהען קיין עצה איז דאך דער מצב געענדערט געווארען צום גוטען אויף אזויפיל אז מען האט זיך געוואונדערט און מצטער געווען פארוואס מען איז געווען פריער אין א מרה שחורה. און עס איז ידוע דער פתגם החכם, אשר העבר הוא מלמד העתיד, ובמילא דארף מען זיין שטארק אין בטחון אז כל מה דעביד רחמנא לטב עביד, און במשך הזמן איז מען זוכה צו א העכערע דרגה אז גם זו לטובה (אז דאס אליין איז א טובה און ניט נאר א סיבה לטב, ווי עס איז ידוע דער הפרש צווישן דעם סיפור דכל מה דעביד רחמנא לטב עביד (ברכות ס, ע\"ב) און דעם סיפור פון גם זו לטובה (תענית כא, ע\"א))...</p>\n<p>המחכה לבשו\"ט וחותם בברכה לקבלת התורה בשמחה ובפנימיות.</p>\n<h4><i><b>ב'תרפג</b></i></h4>\n<p><b> ידוע דער הפרש</b><b>:</b> ראה גם לעיל ח\"ו אגרת א'תשדמ, ובהנסמן בהערות שם.</p>"],[1200830065,"ב'תרפד\n\n<p>ב\"ה, כ\"ט אייר, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מה' במדבר, בו כותב שרוצה להיות חסיד ליובאוויטש וכן גם חבר שלו רוצה בכזה, ורוצים לדעת התנאים ומה יש לעשות.</p>\n<p>הנה התנאים הם ללמוד תורת החסידות וע\"פ מרז\"ל לא המדרש עיקר אלא המעשה להתנהג בהדרכותי' ומנהגי'. וכמובן שכמו שבקבלת התורה שזכו לזה דוקא ע\"י הקדמת נעשה לנשמע, הרי כן הוא ג\"כ באיזה חלק מפרד\"ס שבתורה שגם בזה צ\"ל הקדמת נעשה לנשמע וכבר ידוע פסק רז\"ל לא יגעת ומצאת אל תאמין יגעת ומצאת, ואם רוצים באמת הנה הבא לטהר מסייעין אותו.</p>\n<p>בטח לומד תניא גם עתה וכן אומר בכל יום אחר תפלת שחרית שיעור</p>\n<p>תהלים - כפי שנחלק התהלים לימי החדש - והשי\"ת יצליחו.</p>\n<p>בברכה לתלמוד תורה ביראת שמים,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>"],[1200830066,"ב'תרפה\n\n<p>ב\"ה, כ\"ט אייר, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>עס איז ערהאלטען געווארען אייער בריף פון ט\"ז אייר אין וועלכען איר שרייבט אז עס איז שווער צו אויפשטעלען א בית ספר אדער א חדר פון חרדים און דעריבער לערנען די קינדער אין די ערטער וועלכע זיינען נגד דת ישראל.</p>\n<p>הנה נבהלתי צו לייענען אזא ידיעה, אין דער צייט ווען עס איז אלעמען באוואוסט די מסירת נפש וואס אידען האבען געהאט אויף דעם אז זייערע קינדער זאלען האבען א חינוך אזא וועלכער זאל זיין, ניט נאר ניט קעגען דת ישראל, וואס דאס קען מיינען אז מען קען זיך באנוגענען מיט א נייטראלען חינוך, נאר האבען געלייגט כחות ביז מסירת נפש אז דער חינוך זאל זיין דוקא אין רוח דת ישראל, און בפרט לויט ווי איר שרייבט אז איר זייט דער רב פון דעם כפר, וואס די פאראנטווארליכקייט פון א רב איז דאך ניט נאר אויף צו פסק'נן שאלות ווען מען קומט פרעגען, נאר דער עיקר איז דאך צו משפיע זיין אויף דער קהלה אז זיי זאלען וויסען אז מען דארף פרעגען שאלות. אין אנדערע ווערטער, אז זיי זאלען וויסען אז די נשמה פון יעדער אידען איז געשטאנען באם בארג סיני און האבען אנגענומען די תורה בהקדמת נעשה לנשמע, און האבען מקבל געווען מפי הגבורה דעם ציווי פון אנכי הוי' אלקיך וועלכער איז כולל אלע רמ\"ח מצות עשה, און דעם ציווי לא יהי' לך אלקים אחרים וועלכער איז כולל אלע שס\"ה מצות לא תעשה. און השי\"ת זאל אייך מצליח זיין אין דער ארבעט, און בפרט אין די טעג פון הכנה צו מתן תורה וואס די אלע ענינים וועלכע זיינען געווען בא מתן תורה ווערען נתעורר יעדער יאר אין די טעג.</p>\n<p>בברכה.</p>"],[1200830067,"ב'תרפו\n\n<p>ב\"ה, כ\"טאייר, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ מוה\"ר<br>\nשלמה שי'</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מכ' וכ\"ז אייר. כן נתקבלה הס\"ת. ובטח יודיע אם צריך לכתוב מכתב תודה בזה. וכמדומה שהזכיר עד\"ז באחד ממכתביו הקודמים, ובכ\"ז כיון שעתה נוגע לפועל - הנה יודיע עוד הפעם <b>בפרטיות</b>, היינו מהותה איש או האנשים שצריך לכתוב עליהם, בהצעת תואר המתאים, היינו אם הוא עסקן צבורי או רב וכו', וכן אם יש מקום במכתב זה ג\"כ לאיזה דבר תורה, ואם בפרטות או גם ענין הדורש הבנה יותר וכו'.</p>\n<p>ב) בהנוגע למה שיש רוצים לשלוח נערות ללמוד בבית רבקה אשר בפאריז. הנה צריך לברר המצב - הן אודות המשפיע הן אודות המקבל: אם המועמדות הן בעלי משמעת וכו' וכו'. מובן אשר ההשגחה בבית רבקה בפאריז אינה במילואה כ\"כ כמו בהישיבה דתו\"ת, ולאידך גיסא - בהנוגע נערות גדולה יותר האחריות מאשר בנוגע לבחורים. ובכל אופן זהו מענין - כשיש תועלת בנסיעה לצרפת דוקא, כי אי אפשר להמציא בשבילה חינוך המתאים במקומה עתה. ולכן בנערה כבת י\"ב או פחות מזה, אינו רואה הנחיצות שצריכה ללמוד דוקא בצרפת. ובהנוגע להמשפיע - כוונתי - שצריך לדעת המצב בבי\"ר בצרפת ולתאר לפניהם מהות ודרישת התלמידות ואופן השגחה שהם זקוקים לזה, ולשאלם אם ביכולתם לסדר את כל הדרוש, ובטח קודם ההחלטה - יודע גם לכאן מהשקו\"ט בזה.</p>\n<p>ג) בהנוגע למשאלות לבבו לטובה להתראות באחד מזמנים המתאימים - הנה בכלל נכון הוא. ומובן שלכל לראש צריך להיות בטוח בשתי נקודות: א) שיהי' זה בהסכמתה המלאה - ומבלי כפי' - מצד זוגתו תחי'. ב) שלא יסבלו מזה הענינים במרוקה, אשר מפני נקודה הב' בודאי מוגבל הזמן דוקא לזמנים מיוחדים, ויודיע איזה הם.</p>\n<p>בברכת הצלחה בעבודתו בקדש ובעניניו הפרטים - שלו ושל כב\"ב שיחיו.</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ב'תרפו</b></i></h4>\n<p><b> מוה\"ר שלמה שי</b><b>':</b> מטוסוב. אגרות נוספות אליו - לעיל ב'תרמ, ובהנסמן בהערות שם.</p>"],[1200830068,"ב'תרפז\n\n<p>ב\"ה, כ\"ט אייר, תשי\"ד</p><p>ברוקלין.</p><p>מחות' הרה\"ג והרה\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמוה\"ר גרשון שי'</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מתפארת שביסוד בצירוף הפ\"נ שיקרא בעת רצון על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקלל\"ה נבג\"מ זי\"ע והשי\"ת יצליח לכת\"ר לבשר טוב אודותו.</p>\n<p>מ\"ש אודות המאמר להבין מ\"ש בתניא פכ\"ג. הנה יש איזה מאמרים בהתחלה זו וכנראה שאחד מהם לאדמו\"ר הצ\"צ, אחד להרה\"צ ר\"ה מפאריטש וגם לבני או נכדי הצ\"צ וקשה לקבוע למי מהם, כי בכללות כולם מיוסדים על מאמר הצ\"צ.</p>\n<p>מ\"ש בענין הלימוד במס' סוטה בימי הספירה, י\"ל הטעם ע\"פ המבואר בזח\"ג צז, א השייכות שביניהם ומובא ג\"כ בדא\"ח בביאור הענין דהעומר הוא מאכל שעורים וכמו מנחת סוטה.</p>\n<p>מה שהעיר במספר הדפים שגם מס' שבועות יש לה מספר דפים מתאים למס' סוטה, הנה נמצא בספרים המנהג דלימוד מס' שבועות בימי הספירה - בספר זכרון יהודא מובא בלקוטי מהרי\"ח סדר מנהגי ימי העומר בתור מנהג בעהמ\"ס אמרי אש - אבל מה ששמעתי מכ\"ק מו\"ח אדמו\"ר הוא שלומדים מס' סוטה.</p>\n<p>בברכה לבריאות הנכונה וכפתגם כ\"ק מו\"ח אדמו\"ר לקבלת התורה בשמחה ובפנימיות.</p>\n<h4><i><b>ב'תרפז</b></i></h4>\n<p><b> מוה\"ר גרשון:</b> חן. אגרות נוספות אליו -לעיל ח\"ז ב'ק, ובהנסמן בהערות שם. לקמן ב'תשפט,</p>\n<p><b> איזה מאמרים:</b> נדפסו בלקו\"א עם מ\"מ ליקוט פירושים וכו', קה\"ת תשל\"ח, ע' תלו ואילך.</p>"],[1200830069,"ב'תרפח\n\n<p>ב\"ה, כ\"ט אייר, תשי\"ד</p><p>ברוקלין.</p><p>הנהלת צעירי אגודת חב\"ד באה\"ק ת\"ו תל<br>\nאביג<br>\nד' עליהם יחיו.</p>\n<p> שלום וברכה!</p>\n<p>בנועם ובענג קבלתי מכתבם מט\"ז אייר בצירוף העתק הנאומים שנאמו בכינוס צעירי אגו\"ח בכפר חב\"ד, והתענגתי הן מתוכנם וגם מה שלאט לאט מסתדרים בהעבודה, ובודאי ילכו גם בהסדר מעלה מעלה שבד\"מ יוסיף גם זה בהצלחת העבודה והשלישית והיא העיקר שכיון שהנואמים הדגישו נחיצות הרחבת הפעולה תקותי חזקה שיגשימו את זה בפועל להגדיל עבודתם בכל הסניפים הן בכמות והן באיכות ויה\"ר שגם בזה יקויים שפתיחה כחודו של מחט מלמטה (שיש לפרש בזה שגם בערך הלמטה הוא כחודה של מחט) תפתח עי\"ז מלמעלה כפתחו של אולם (שי\"ל בזה שגם בערך של מעלה הוא פתחו של אולם) וכבר באה העת שלא להסתפק בחרישה וזריעה לחוד אלא גם לעשות ככל האפשרי שיבואו גם כן לקצירה ולאוסף הפירות. וכוונתי בזה שאף שבתחלת התעמולה במקום או סביבה חדשה צריכה להיות הכנה כללית לקבלת הענין החדש והוא ע\"ד צחצוח האור מקיף, הנה התכלית היא שיחדרו הדברים לפנימיותם. ובהנוגע לתעמולתם היינו קב\"ע לשיעור בתורה בכלל ובתורת החסידות בפרט ובאופן שידעו בין ביקור לביקור מהנעשה במקום או בסביבה כו' וכו' ומובן ג\"כ שאין להזניח בשביל זה את העבודה בשלב הראשון, כי הרי כמה מקומות ישנם וכמה סביבות שעדיין לא נכנסו בתוכם וזקוקים הם לעבודה דאור מקיף שיצחצח הכלי מבחוץ עכ\"פ.</p>\n<p>ב) לפלא שאין מזכירים במכתבם אודות השתתפותם בהרישום ובפרט שבהמברק שלי הדגשתי שמם בהכתבת.</p>\n<p>ג) מוסג\"פ העתק מכתבי מענה לאחד על שאלתו אשר כדאי פרסמו בהבטאון הבא כיון שע\"פ השאלות המתקבלות לכאן כנראה עורר מכתב זה תמהון וקושיות בחוגים שונים.</p>\n<p>ד) כן אם יופיע הבטאון לפני חג השבועות כדאי לפרסם הקטע דשבת מברכין סיון דאשתקד כיון שהוא מענינא דיומא.</p>\n<p>המחכה לבשו\"ט מפעולותיהם ביום הבהיר הוא ל\"ג בעומר וע\"ד הכנתם לפעולות טובות בזמן מתן תורתנו וחותם בברכת הצלחה מופלגה בעבודתם בקדש.</p>\n<h4><i><b>ב'תרפח</b></i></h4>\n<p><b> בכינוס</b><b>:</b> בחוה\"מ פסח. דלעיל ח\"ח אגרת ב'תקצו. וראה גם לעיל אגרות ב'תרכז. ב'תרמז.</p>\n<p><b> בהרישום</b><b>:</b> תלמידים ברשת אהלי יוסף יצחק.</p>\n<p><b> מכתבי מענה לאחד</b><b>:</b> דלעיל ב'תרכה. וראה גם לקמן אגרת ב'תשסב.</p>"],[1200830070,"ב'תרפט\n\n<p>ב\"ה, כ\"ט אייר, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ג והרה\"ח אי\"א נו\"נ צמ\"ס<br>\nמוה\"ר אברהם יעקב שי'</p>\n<p> שלום וברכה!</p>\n<p>בנועם קבלתי הפ\"ש ע\"י הרה\"ח נו\"נ כו' מוה\"ר ליב שי' זלמנוב וכן תשורתו ספרו אשל אברהם ע\"ס נשים חלק ב'. והשי\"ת יצליח את כת\"ר להגדיל תורה ולהאדירה.</p>\n<p>ונפלא הדבר אשר מובא זה בנודע ללימוד תשב\"ר שאף שהוא הבל שאין בו חטא הרי בכ\"ז הוא תחלת הלימוד ממדריגות התחתונות שבלימוד (רמב\"ם ת\"ת ב, ז. יד מלאכי כללים ד') ולאידך גיסא בהנוגע ללימוד שאינו משנה בדין ורק מוסיף הידור ויופי בהלימוד (חולין סו, ב) היינו מדריגה עליונה שבלימוד. והוא מתאים ג\"כ להידוע שלכאו\"א מישראל יש חלק בתורה. ומובן מזה שאפי' עם הארץ מחויב במצות תלמוד תורה ולו יהא באמירת פסוק אחד שבזה יוצא ידי חובתו ולאידך גיסא אפי' הגדול שבגדולים אם היתה שעה קלה שאפשר לו לעסוק בתורה ולא עסק עליו הכתוב אומר וכדרז\"ל בסנהדרין (צט, א). והנקודה פנימית שבזה כי באמת התורה היא חכמתו ורצונו של הקב\"ה אלא שבחסד חנם נתנה במתנה למטה כי לולא זאת הרי גם משה רבנו הי' משכחה אף שלמדה מפי הקב\"ה בהר שלא הי' שייך לחומריות ואפילו לגשמיות כי לחם לא אכל ומים לא שתה, ובמילא היותר גדול והיותר קטן שוים בזה. והוא ע\"ד המבואר בכ\"מ שלגבי בלי גבול הנה אחד ואלף אלפין וריבו רבבן בשוה ממש.</p>\n<p>בברכת הצלחה לכת\"ר בכל הנ\"ל ולאריכות</p>\n<p>ימים ושנים טובות.</p>\n<p>נ.ב.</p>\n<p>כדרכי ולחביבותא דמילתא אבוא עכ\"פ באיזה הערות בספרו זה, והם:</p>\n<p>בתחלת הספר ונשנה בע' שנח במה דשקיל וטרי בש\"ס קדושין ט\"ז ע\"א יש להעיר:</p>\n<p>א) בספר העיטור הועתק ג\"כ באוצר הגאונים על אתר, דמביא לשון הש\"ס משמע דלא גריס התיבות אי נמי באפי בי דינא זיל.</p>\n<p>ב) במה דמסיים בהשקו\"ט דילי'. יש להעיר מנדרים מ\"ה ע\"א, כדי שיהי' אחד זוכה ושניים מעידין, שבנדון דידן הוא אמירה באפי תרי, ומגיטין לג. מ' סע\"ב.</p>\n<p>ג) בהנוגע לדעת הנו\"ב, אי גט בעי בי\"ד, ראה שו\"ת הצ\"צ סי' קס\"ב.</p>\n<p>ד) שם בתוס' למס' סוטה דף ע\"ח ע\"א, ד\"ה במתניתין ובעשור שבחומש הפקודים במש\"כ דברי התוס' ישנים. הנה י\"ל בהענין דקריאת התורה דשני סוגים בזה א) חובת הצבור ולא חובת היחיד וכסברת המלחמות מגילה פ\"א ד\"ה ועוד אמר, וראה ג\"כ צפנת פענח להגאון הרגצובי על הרמב\"ם הלכות תפלה פי\"ב הלכה ה'. וכיון שזהו חובת הצבור ה\"ה בדוגמא דנתינת התורה שניתנה לכלל ישראל, ולכן דברים שנתנו בכתב אי אתה רשאי לאומרם בע\"פ וכו' כי צריך להיות כנתינתה, עיין שו\"ת הרדב\"ז חלק רביעי סי' א'רה. סוג ב) שזהו חלק מהתפלה וע\"ד ונשלמה פרים שפתינו או הוספה להקרבת הקרבן, וזהו כוונת התוס' ישנים דצורך עבודתו הוא, והוא מהירושלמי ובמילא אין זה בדוגמת נתינת התורה לכלל ישראל ולכן לא חל ע\"ז הדין דדברים שבכתב אי אתה רשאי לאומרם בע\"פ, וה\"ה בכל קריאת הקרבנות ביום טוב ר\"ה ויוהכ\"פ דמחולקים משאר קריאת התורה, וראה תוס' מגילה ל, ע\"ב וכן ברמב\"ם הל' תפלה דחילק ענין קריאת התורה בשני הלכות ולדכוותי' יספיק הקיצור.</p>\n<p>בסוף הספר בפי' מרז\"ל האידנא דדשו בה רבים ושואל בצדק באיזה אופן בא המצב דדשו בה רבים, ורוצה לבאר שהי' זה בזמן הגזירה על מצות מילה ולא הי' בידם להמתין ליום בהיר כי דוקא אז השגיחו עליהם יותר ולכן עשו זה דוקא ביומא דעיבא היינו בזמן שלא הורגלו לעשות ברית מילה. אבל קשה לקבל את זה דכיון שסכנה יש בדבר איך מלו את בניהם ומגופא דעובדא ג\"כ ראי' להיפך שהרי בהענין דדור המדבר הרי לאחר שידעו מהגזירה דארבעים שנה יהיו במדבר ובמילא יהיו ענני הכבוד מ' שנה ולא תנשב רוח צפונית - ובכ\"ז לא מלו את הבנים ועאכו\"כ בגזירה דגזירה עבידא דבטלה שלא הי' להם למול את בניהם ולסכנם. ומה שנראה לי לומר בזה שהוא ע\"ד פירוש התוספת שבזה מבוארת קושיא כעין זו ואולי עוד יותר אי מובנת דאותיות מנצפ\"ך שכחום (מגילה ב\"ב) שהי' זה לאחר ששרף אמון את התורה ועד\"ז יש לפרש בנדון דידן אשר דשו בה רבים הי' זה בבבל אשר בקעה היתה בכמה ענינים וכשירד רב לשם וכן שאר האמוראים מצא המצב דדשו בה וה\"ה בהנוגע להקזת דם ביום ששי (שבת קכט, ע\"ב) ועיין ג\"כ באגרת רב שרירא גאון בהמצב בבבל קודם ירידת רב לשם.</p>\n<h4><i><b>ב'תרפט</b></i></h4>\n<p><b> מוה\"ר אברהם יעקב:</b> ניימארק. אגרות נוספות אליו - לעיל ח\"ז ב'קצ, ובהנסמן בהערות שם. לקמן ב'תתו.</p>\n<p><b> ונפלא הדבר:</b> ראה גם לקמן אגרת ב'תשסט.</p>\n<p><b> דף עח</b><b>:</b> בספרו, בהערותיו למס' סוטה מ, ב.</p>\n<p><b> דקריאת התורה... בע</b><b>\"</b><b>פ</b><b>:</b> ראה גם לעיל ח\"ח אגרת ב'תקב.</p>"],[1200830071,"ב'תרצ\n\n<p>ב\"ה, כ\"ט אייר, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ מוה\"ר<br>\nמנחם זאב<br>\nשי' הלוי</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מכ\"ג אייר, בו שואל אודות נתינת רשות לתלמידים כו'.</p>\n<p>הנה כנראה ממכתבו כדאי לתת רשות אלא שיש לקבוע וכן לקבל מהנ\"ל נגד זה תוספת בענינים דשלשת העמודים שעליהם העולם עומד, ומפני קוצר הזמן הנה התחלה בהתוספת תהי' קודם הנסיעה לכאן וסיומם אפשר גם לאחרי זה, ואל בינתו אשען לסדר הנ\"ל באופן המתאים.</p>\n<p>מכתבי בטח קבל.</p>\n<p>הלימוד בחה\"ש הבע\"ל - הצעתי מאמר חה\"ש ה'תש\"ד. ומטובו לפרסם ות\"ח.</p>\n<p>בברכת הצלחה בעבודתו בקדש ולבשו\"ט בקרוב גם בעניניו הפרטים.</p>\n<h4><i><b>ב'תרצ</b></i></h4>\n<p><b> מוה\"ר מנחם זאב שי</b><b>:</b> גרינגלס, אגרות נוספות עליו -לעיל ח\"ח ב'תח, ובהנסמן בהערות שם. לקמן ב'תשצד. ב'תתכב. ב'תתנד.</p>\n<p><b> רשות:</b> לנסוע להתוועדות כ\"ק אדמו\"ר שליט\"א בנ.י.</p>\n<p><b> לתלמידים</b><b>:</b> מישיבת תו\"ת מונטריאל.</p>\n<p><b> לקבל... תוספת</b><b>:</b> ראה גם לעיל ח\"ח אגרת ב' רפז.</p>"],[1200830072,"ב'תרצא\n\n<p>ב\"ה, כ\"ט אייר, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ג והרה\"ח אי\"א נו\"נ כו' מוה\"ר שלמה<br>\nשי'</p>\n<p> שלום וברכה!</p>\n<p>קבלתי מכתבו מיום הבהיר ל\"ג בעומר הילולא דרשב\"י אשר פתח הצנור דפנימיות התורה עד שגם ינוקא דבימיו למדו ולימדו בזה (עיין ג\"כ הקדמת הקונטרס ל\"ג בעומר תש\"י קונט' ע\"ח).</p>\n<p>ונהניתי לקרות במכתבו אשר לומד הוא לימודי קדש עם התלמידים בבית ספר למלאכה, ומובן שבזה צריך להיות השתדלות יתירה כיון שאיזה שעות ביום ילמדו לימודים אחרים, ובמילא בשעות העיקרים בלימוד הקדש צריך להחדירם רוח יראת שמים טהורה ותורה תמימה באופן שיספיק גם על שאר היום, אבל לאידך גיסא הרי לפום גמלא שיחנא וע\"פ מרז\"ל שהקב\"ה אינו מבקש אלא לפי כחם, בודאי ישפיעו לו תוספת כח להצליחו בכל הנ\"ל וגדול זכות ענין היותר נעלה זה להמשיך לו ברכה והצלחה בזה גופא וכמרז\"ל שכר מצוה מצוה וכן תוספת ברכה והצלחה בעניניו הפרטים.</p>\n<p>המחכה לבשו\"ט מהצלחתו בכל הנ\"ל והתקדמות בכל הענינים.</p>\n<h4><i><b>ב'תרצא</b></i></h4>\n<p><b> מוה\"ר שלמה:</b> גרינוואלד. אגרת נוספת אליו- לעיל ח\"ה א'שסג.</p>"],[1200830073,"ב'תרצב\n\n<p>ב\"ה, כ\"ט אייר, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>... מ\"ש שבעת התועדות ישנה התעוררות אבל אח\"כ כשאין רואים הצלחה הנה נופל מעט ברוחו וחסר בענין השמחה. הנה אין להנהגה כזו יסוד כלל וכלל כי חזקה להתועדות חסידותי שפועלת, אלא שלפעמים ניכרת התועלת על אתר ולפעמים מתאחרים הדברים, אבל דבר <b>בטוח</b> הוא שסוכ\"ס פועל זה הן בעצמו והן בסביבה.</p>\n<p>והשי\"ת יצליחו לעבדו מתוך שמחה ולהיות חזק במדת הבטחון כפשוטו ממש שיצליח בפרנסתו נוסף על עסקנות בצרכי צבור והוא וזוגתו שיחיו ירוו רוב נחת חסידותי מכל ילידי' שיחיו.</p>\n<p>בברכת הצלחה.</p>"],[1200830074,"ב'תרצג\n\n<p>ב\"ה, כ\"ט אייר, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>נתקבל מכתבו משבוע העבר ונעם לי לקרות בו אשר בהישיבה בה מדריך נמצא \"כל מה שצריכים באש\"ל ובחינוך רוחני\" אשר בודאי הודעה אחראית כזו נעשית לאחרי התבוננות בהמצב בהישיבה ובהנדרש והעיקר בחינוך אברכים בזמננו זה ובפרט שכותב שהוא המדריך הרוחני והאחראי על שקידת הבחורים בתורתנו הק', ואם כמרז\"ל (שבת לא, סוף ע\"א) הרי בכל הזמנים אם יראת ה' היא אוצרו כו' ואם לאו מוטב שלא העלית, הרי בדורנו יתום זה ראו ורואים גם בעיני בשר ולאלתר אמיתית פסק דינם,</p>\n<p>ולכן לפלא הי' בעינני סיום מכתבו בו כותב שהאברכים לומדים גמרא חומש דינים ואינו מזכיר דבר ע\"ד חובות הלבבות.</p>\n<p>ותקותי שאולי אין זה אלא השמטה בכתיבה אבל לא חסרון בפועל וכידוע שבעניני חינוך חסרון אפילו במשך זמן קצר יכול להעשות מעוות לא יוכל לתקן וחסרון לא יוכל להמנות, ובודאי ראה ג\"כ במוחש אשר אם בשנים מלפנים הי' קס\"ד לומר שיש להסתפק בלימוד המוסר, הוכיחו החיים והפועל ממש אשר אברכים בעלי שכל והבנה מוכרח שיהי' הלימוד שלהם גם הלימוד דחובות הלבבות באופן שכלי ומה טוב בהדרך דריבוי האור ולא בהתבוננות דחשכת החשך אשר זוהי דרכה של תורת החסידות וכיון שכותב שלמד חסידות אקוה אשר גם שורותי אלה המעטים בכמות מבהירים את הענין די צרכו והשי\"ת יצליחו להעמיד תלמידיו יראי אלקים באמת אשר אז חכמתו מתקיימת.</p>\n<p>בברכה לקבלת התורה בשמחה ובפנימיות.</p>"],[1200830075,"ב'תרצד\n\n<p>ב\"ה, א' סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>... איך בין געווען צופרידען צו לייענען אין אייער בריף אז איר לערנט א שיעור תניא יעדער טאג, און עס איז באוואוסט דער ווארט פון די נשיאי חב\"ד וועגען דעם תניא, אז אפילו דער גדול שבגדולים קען זיך ניט דערגרונטעווען צו די גאנצע טיפקייט פון תניא, און דאגעגען קען יעדער איד עפעס נעמען פון תניא, ווארום די כוונה פון בעל התניא איז געווען אז דאס זאל זיין א ספר פאר אלע אידען צו לערנען, וצדיק גוזר והקב\"ה מקיים, און עס איז דא[ך] ידוע אז יגעת ומצאת, אז וואס מער מען איז זיך מייגע אין דעם אלץ מער נעמט מען אויף און מען פארשטייט די ענינים וועלכע ווערען דארט אין תניא גערעט.</p>\n<p>בברכה לקבלת התורה בשמחה ובפנימיות מתוך בריאות הנכונה.</p>"],[1200830076,"ב'תרצה\n\n<p>ב\"ה, א' סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על המברק שנתקבל זה עתה, ותוכנו תמוה במאד... ויתבונן בעצמו כשהי' כאן ונדבר ע\"ד הכנות להחתונה בין שאר הדברים הי' ג\"כ הענין שביחד עם הוצאות החתונה של כלי זמר ענינים של אכו\"ש וכו' יכנס בזה ג\"כ הדפסת ספרו של רבנו הזקן מייסד חסידות חב\"ד ונשיא כל חסידי חב\"ד לדורותיהם, ותיכף כשבא לכת\"ר קס\"ד לאחר התשלומין וכמה הסברות בזה, הרי רואה שהתחילו ענינים מוזרים וענין הנ\"ל בכלל. ולפלא שגם עתה מפרשו בענינים שהם לא בדרי דאונא ואינו רוצה לבארו בענין שהי' צ\"ל מושכל ראשון שלו.</p>\n<p>והשי\"ת יורהו ויוליכו בדרך הישרה והמאושרה בשבילו ובשביל כל ב\"ב שיחיו.</p>\n<p>בברכה לקבלת התורה בשמחה ובפנימיות.</p>"],[1200830077,"ב'תרצו\n\n<p>ב\"ה, א' סיון, תשי\"ד</p><p>ברוקלין.</p><p>ליידיס אוקזילערי אוו בראנזויל ענד איסט נויארק,<br>\nובראשה הפרעזד. מרת דבורה תחי'<br>\nגרינבערג.</p>\n<p> ברכה ושלום!</p>\n<p>איך בין געווען צופרידען צו באקומען א גרוס פון אייך און אויך פון דעם לעצטען צושטאנד געקומענעם יערליכען דינער פון דער אוקזילערי, און איך האף אז עס איז געווען בהצלחה סיי בגשמיות און סיי ברוחניות.</p>\n<p>און אין די טעג פון פאר שבועות דער זמן מתן תורתנו וואס דענסטמאל האט השי\"ת געזאגט צו משה רבנו, כה תאמר לבית יעקב - וואס דאס מיינט - די פרויען, און ערשט דערנאך - ותגד לבני ישראל - וואס עס מיינט - די מענער, איז אט דער זמן פון מתן תורה ווערט ווידערהאלט יעדער יאר, זאל השי\"ת מצליח זיין יעדערע פון אייך צו אנוויזען דעם וועג אין איר פאמיליע און צו פריינד און באקאקנטע ווי מען דארף זיך אויפפירען אין דעם טאג טעגליכען לעבען לויט דער אנוויזונג פון אונזער הייליקער תורה, וואס בתוך כלל ישראל גייען מיר מקבל זיין די תורה הק' אין דעם קומענדען יום טוב שבועות הבא עלינו ועל כל ישראל לטובה.</p>\n<p>בברכה לכל אחת ואחת מהן וב\"ב שיחיו.</p>"],[1200830078,"ב'תרצז\n\n<p>ב\"ה, א' סיון, תשי\"ד</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ עוסק בצ\"צ מוה\"ר יעקב<br>\nאליעזר שי'</p>\n<p> שלום וברכה!</p>\n<p>... איך בין געווען צופרידען צו באקומען די דיעה פריער פון די איינטיילנעמער און יעצט אויך פון אייער שרייבען אז איר לערנט א שיעור פאר א גרופע פרויען, און האפענטליך וועט איר זיך משתדל זיין צו פארגרעסערען די צאל צוהערער פון דעם שיעור און אויך אז א טייל פון די לימודים זאל זיין אין די ענינים וועלכע זיינען פארבונדען מיט דינים ומנהגי ישראל אין דעם טאג טעגליכען לעבען, און עס איז דאך באוואוסט דער מאמר רז\"ל לא המדרש עיקר אלא המעשה עיקר.</p>\n<p>און צוגעפאסט צו דעם צושטאנד פון די צוהערער וואלט אפשר געווען ראטזאם געבען זיי די מעגליכקייט צו שטעלען פראגעס בכדי אויף אזא אופן צו פאראינטערעסירען זיי מער און צוציהען זיי מער צו דער גאנצער זאך והבא לטהר מסייעין בידו...</p>\n<p>בברכה לקבלת התורה בשמחה ובפנימיות ובברכת מז\"ט.</p>\n<h4><i><b>ב'תרצז</b></i></h4>\n<p><b> מוה\"ר יעקב אליעזר</b><b>:</b> פרידריך, אנטווערפן.</p>"],[1200830079,"ב'תרחצ\n\n<p>ב\"ה, א' סיון, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ מוהרנ\"ן<br>\nשי'</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבל מכתבו מכ\"ה אייר, וחבל על אשר מאחרים כ\"כ כשיש בשו\"ט ואין טוב אלא תורה והתועדות חסידית שזהו טוב כפול לבריות ולשמים כמבואר בקדושין דף מ, ע\"א ועיין ג\"כ מכתב כ\"ק אדמו\"ר (מוהרש\"ב) נ\"ע הנדפס בקונטרס ס\"א. ומובן שכוונתי בזה להתועדות דל\"ג בעומר שכותב אודותה. ואם בכל הזמנים היו משתוקקים לקבל בשו\"ט הן בגשמיות והן ברוחניות, עאכו\"כ בדורנו עקבת[א] דמשיחא שאין לך יום וכו'.</p>\n<p>בודאי יוסיפו אומץ בהתעמולה אודות זמן הוואקאנס, וכל המרבה ומתאמץ בזה ה\"ז משובח, וכבר ידוע דיוק כ\"ק מו\"ח אדמו\"ר נדפס בהיום יום י\"ז ניסן.</p>\n<p>בברכה לקבלת התורה בשמחה ובפנימיות.</p>\n<p>נ.ב.</p>\n<p>מטובו לפרסם בין אנ\"ש בהנוגע ללימוד בימי חג השבועות הבע\"ל במאמרים של כ\"ק מו\"ח אדמו\"ר שהצעתי בזה הוא ללמוד מאמרי חג השבועות תש\"ד שיצאו לאור זה מזמן בקופיר ונדפסים ג\"כ עתה.</p>\n<h4><i><b>ב'תרחצ</b></i></h4>\n<p><b> מוהרנ\"ן:</b> מוה\"ר ניסן נמנוב. אגרות נוספות אליו - לעיל ב'תרמא, ובהנסמן בהערות שם, <b> מכתב כ\"ק אדמו\"ר (מוהרש</b><b>\"</b><b>ב</b><b>) </b><b>נ</b><b>\"</b><b>ע</b><b>:</b> אג\"ק שלו ח\"א אגרת מח (ע' קלט)</p>"],[1200830080,"ב'תרצט\n\n<p>ב\"ה, א' סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מכ\"ח אייר, וכבקשתו אזכירו על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, בכלל ובהנוגע לחלישות שמזכיר במכתבו בפרט.</p>\n<p>וימים אלו ימי הכנה למתן תורה וקבלתה שנעשו אז כל ישראל בריאים גם בפשטות בגשמיות כמסופר בשמו\"ר הרי ידוע המבואר בחסידות שכל ההמשכות חוזרים ונעורים בכל שנה ושנה, וכמ\"ש והימים האלה נזכרים (ואז הם גם) ונעשים, הנה יצליחו השי\"ת לבשר טוב בכל הנ\"ל.</p>\n<p>בברכה לקבלת התורה בשמחה ובפנימיות.</p>\n<p>נ.ב.</p>\n<p>בבקשה לפרסם בהנוגע ללימוד במאמרי כ\"ק מו\"ח אדמו\"ר בימי חג השבועות הבע\"ל, שהצעתי בזה הוא מאמרי חג השבועות תש\"ד שנמצאים בקופיר והולכים עתה ונדפסים.</p>"],[1200830081,"ב'תש\n\n<p>ב\"ה, א' סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> ברכה ושלום!</p>\n<p>עס איז מיר אנגעקומען אייער בריף פון כ\"ב אייר, אין וועלכען איר שרייבט וועגען אייער זון... שי', אז איר וואלט וועלען זעהען א תכלית פאר עם סיי בגשמיות און סיי ועגען הייראטען, וועלכע זיינען פארבונדען איינס מיט דאס אנדערע, און דערפאר פרעגט איר מיין מיינונג צי זאל ער גלייך אנהויבען לערנען זיך א פאך.</p>\n<p>אייער זון שי' לערנט צווישען פילע בחורים פון זיין עלטער אדער נאך מיט א פאר יאר עלטער, דעריבער איז מיין מיינונג אז ער דארף זיך פירען אויך אין דעם ווי די אנדערע חברים זיינע, און בכלל איז דא דער סדר אז אין זיין עלטער איז נאך צו פריה צו אוועקגעבען זיך אויף תכליתים. און דעם ביישפיל וואס איר שרייבט אין אייער בריף, איז אויסער דעם וואס יענער איז פיל עלטער פון עם, זיינען פראן אנדערע ספעציעלע טעמים בא עם, אבער בנוגע אייער זון איז א שאד צו אפרייסען עם יעצט פון לערנען אין וועלכעס ער איז מצליח און האט חשק אין דעם.</p>\n<p>יעצט בפרט איז די זאך פון שלייפען דימענטען זייער שוואך, און לערנען זיך דעם פאך נעמט א צוויי דריי חדשים ווען מען האט באקאטנשאפט וואו צו לערנען דאס, דעריבער איז נאך פראן גענוג צייט, און עס איז זיכער אז זיינער צייט וועט השי\"ת מצליח זיין עם מיט א גוטע איינארדנונג סיי בנוגע צו פרנסה און סיי בנוגע א גוטען שידוך, אבער דערוויילע דארף ער בעסער די צייט אויסניצען צו איינשאפען זיך מער וויסען אין לערנען וואס דאס וועט עם צוניץ קומען אויף דעם גאנצען לעבען סיי בגשמיות און סיי ברוחניות.</p>\n<p>און אין איינקלאנג מיט דאס אויבענדערמאנטע דארפמען עם יעצט ניט שטערן מיט מחשבות פון תכלית און שידוכים וועלכעס איז נוגע ערשט א פאר יאר ארום, און זאל ער יעצט פארטזעצען זיין לערנען להצלחה.</p>\n<p>לויט אייער בקשה וועט מען מזכיר זיין אייך אויף דעם ציון הק' פון כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע צום בעסערונג פון אטייער געזונט און אויך צו פרנסה,</p>\n<p>און דער זכות וואס איר האט אויפגעהאדעוועט א זון וועלכער לערנט מיט התמדה די תורה פון השי\"ת און פירט זיך אויף לויט אירע - תורה- אנווייזונגען, זאל אייך ביישטיין אין דעם אלעס וואס איר נויטיגט זיך.</p>\n<p>בברכה.</p>"],[1200830082,"ב'תשא\n\n<p>ב\"ה, ב' סיון, תשי\"ד</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ עוסק בצ\"צ מוה\"ר אלחנן<br>\nשי' הכהן</p>\n<p> שלום וברכה!</p>\n<p>איך בין געווען צופרידען צו באקומען א גרוס פון אייך דורך מר ניסן שי' מינדעל וועלכער האט מיר אויך דערציילט וועגען אייער איינווירקונג אויף א בחור אז ער זאל ווידער אנהויבען לייגען תפילין, נאכדעם ווי ער האט דאס א צייט ניט געטאן,</p>\n<p>און די גרויסקייט פון דער זאך איז דאך ניט צו משער זיין, און ווי עס ווערט ערקלערט אויך אין אייער תפילין העפט אז דאס גלייכט אויס די קאפ מטיט דער הארץ, און ווי דער לשון פון שולחן ערוך וועלכעס ווערט אויך אראפגעבראכט אין תניא פרק מ\"א - זייט 2 - ליבטל וליכלל בחי' חכמתו ובינתו וכו' וכן ליבטל וליכלל בחי' הדעת שבנפשו וכו' לשעבד הלב והמוח וכו'.</p>\n<p>און די טעג וואס פאר מתן תורה זיינע ספעציעל הצלחה טעג וואס מען נעמט אויף זיך דעם ענין פון אהבת ישראל צו מקרב זיין זיי תצו תורה ומצות, זאל דאס אראפקומען לפועל און אין א גוטען פרייליכען אופן.</p>\n<p>בברכה בנוסח כ\"ק מו\"ח אדמו\"ר, לקבלת התורה בשמחה ובפנימיות, און מיט בעסטע גרוסען למרת כהן תחי' און אייערע קינדער און איינגקלעך שיחיו.</p>\n<h4><i><b>ב'תשא</b></i></h4>\n<p><b> מוה\"ר אלחנן</b><b>:</b> קאווען. אגרות נוספות אליו - לעיל ח\"ז ב'רלא, ובהנסמן בהערות שם.</p>\n<p><b> תפילין העפט</b><b>:</b> חוברת תפילין באנגלית שערך ונדפס ע\"י המל\"ח.</p>"],[1200830083,"ב'תשב\n\n<p>ב\"ה, ב' סיון, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ח והרה\"צ נו\"נ בנש\"ק ענף עץ אבות<br>\nכו' וכו'<br>\nמוה\"ר חיים שמעון זאב שליט\"א</p>\n<p> שלום וברכה!</p>\n<p>לאחרי הפסק הארוך נעם לי לקבל מכתבו ל\"ח למספר בנ\"י מבשר טוב אשר השלום אתם, כן יזכה השי\"ת את כאו\"א מאתנו לבשר איש לרעהו אך טוב ואין טוב אלא תורה הנקראת תורת חיים היינו שהיא קשורה ומאוחדה עם החיים כפשוטו וכמשמעו דפשיטא שגם חיי עוה\"ז בכלל זה, ובפרט ע\"פ המבואר בתניא פרק ל\"ו, ומוכרח מפסק רז\"ל אשר התורה לא בשמים היא כ\"א דוקא בעוה\"ז הגשמי.</p>\n<p>נהניתי ממ\"ש אודות לימודו שיעור יום יום בספר תניא קדישא (נוסח הסכמת דתניא הוצאת זולקווא אף שנמצאה בריחוק מקום ממושב רבנו הזקן וע\"י רבנים שלא ראו המחבר), וכבר ידוע מה שכתבו המסכימים הראשונים דספר התניא הם גדולי תלמידי הרב המגיד ממעזריטש שנדפסו בראש התניא והמפורסמות אין צריכים ביאור, ובודאי ראה ג\"כ כת\"ר רשימת כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע שנדפסה בסוף ספר קיצורים והערות לתניא...</p>\n<p>ת\"ח ת\"ח על מה שהזכירני על מקומות הק' ובודאי לדכוותי' למותר להעיר מה שנתבאר בענינים אלו במאמרו של אדמו\"ר האמצעי בנו של רבנו הזקן בעל התניא ד\"ה להבין ענין ההשתטחות ותוספת ביאור בזה ג\"כ במאמרי השתטחות להרה\"ח ר' הלל מפאריטש זצ\"ל.</p>\n<p>כבקשתו אזכירו ואת כל ב\"ב שיחיו בהיותי על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע.</p>\n<p>ואחרון אחרון חביב בבשורתו הטובה אשר נולדה לו בת למזל טוב וקרא שמה בישראל סימא לאה, הנה יה\"ר שיגדלה לתורה ולחופה ולמעשים טובים והוא וזוגתו שיחיו ירוו ממנה ומכל יו\"ח שיחיו רוב נחת חסידותי לאריכות ימים ושנים טובות.</p>\n<p>בברכה בנוסח כ\"ק מו\"ח אדמו\"ר לקבלת התורה בשמחה ובפנימיות.</p>\n<h4><i><b>ב'תשב</b></i></h4>\n<p><b> מוה\"ר חיים שמעון זאב:</b> רובין. אגרת נוספת אליו -לעיל ח\"ח ב'תמד.</p>\n<p><b> תניא קדישא</b><b>:</b> ראה גם לעיל שם.</p>"],[1200830084,"ב'תשג\n\n<p>ב\"ה, ג' סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>.. במ\"ש אודות הלימודים בהכפר, הנה לפלא שאינו מזכיר ע\"ד לימוד הלכות במצות התלויות בארץ, ותקותי שאין זה אלא השמטה בכתיבה אבל לא בפועל, והרי ידוע פסק רז\"ל שלא המדרש עיקר אלא המעשה...</p>\n<p>מ\"ש אודות החלישות ברכוז המחשבה, הרי ידוע[ה]אחת העצות בזה</p>\n<p>שכשמתעייפים מחליפים הלימוד ללימוד אחר ג\"כ במקום שלבו חפץ ולא לכוף על כח המחשבה להמשיך דוקא בהענין שנתייגע בו.</p>\n<p>ולהודעתו מיום הולדתו... הבע\"ל, הנה יה\"ר מהשי\"ת שלאריכות ימים ושנים טובות, טובות עם כל הפירושים, יוסיף אומץ בתורה ובמצותי' ולהחדיר גם בסביבתו התורה והמצוה והמאור שבה היא תורת החסידות ובימיו ובימינו ימולא היעוד וכל קרני רשעים אגדע תרוממנה קרנות צדיק שכפירוש רש\"י על אתר מדבר בזה בגאולה האמיתית והשלימה במחיית עמלק ורוממות קרנות צדיקו של עולם, ולהעיר ג\"כ מאור התורה לרבנו הצ\"צ דרושי חנוכה (ע' תר).</p>\n<p>בברכה בנוסח כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע לקבלת התורה בשמחה ובפנימיות.</p>\n<h4><i><b>ב'תשג</b></i></h4>\n<p><b> מחליפים הלימוד:</b> ראה גם לעיל אגרת ב'תרדע. לקמן ב'תשעט. ב'תתפד.</p>"],[1200830085,"ב'תשד\n\n<p>ב\"ה, ג' סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מי\"ז אייר, בו כותב אודות בתו תחי'.</p>\n<p>והנה אצל איש הישראלי שעמנו נקרא גוי אחד בארץ וכדיוק רבנו הזקן (אגרת הקדש ט') שגם בעניני ארץ לא יפרידו מאחד האמת, הרי ביחד עם עשי' ופעולה בדרך הטבע צריך לעשות מה בענינים רוחנים המתאימים שבכלל זהו תוספת בתורה ומצותי'.</p>\n<p>אינו כותב במכתבו מה עושים הרופאים לבתו תחי' לבד העצה דהחלפת האקלים והתרופות שישתמשו בהם כאן למצב בריאותה ע\"ד שמזכיר במכתבו (אף שכמובן אי אפשר לדעת ברור המצב על פי שתי מלות שמזכיר במכתבו) ההשתמשו cortisoneב ?</p>\n<p>וכוונתי למ\"ש לעשות מה בענינים רוחנים היא ראשונה לברר אם נולדה בתם בטהרה היינו ששמרו אז דיני טהרת המשפחה במקוה, ותקותי שלא יקפיד על הערתי זו, כי כיון שאיני מכירו ובענין הנוגע לבריאות נפש מישראל אין מקום לבושה שלא במקומה היינו בהידיעה בהנ\"ל אם ח\"ו לא הי' הענין כך אז עליו ועל זוגתו שיחיו נוסף על הדיוק בשמירת מצות טהרה הנ\"ל מכאן ולהבא להוסיף אומץ בתעמולה בענין זה בפרט שזה תיקון במקצת עכ\"פ בהנ\"ל.</p>\n<p>ובכל אופן נכון שזוגתו תפריש לצדקה איזה פרוטות קודם הדלקת הנרות בכל ערב שבת וערב יום טוב וכן ביום שני וחמישי בבקר, והוא ינהג ככה לפני התפלה בכל בקר דיום שני וחמישי, ולאחר התפלה של שחרית יאמר שיעור תהלים כפי שנחלק לימי החדש, וכן לבדוק את המזוזות בביתם שיהיו כולן כשרות.</p>\n<p>והשי\"ת יזכהו לבשר טוב בכל הנ\"ל וביחוד מהטבת מצב בריאות בתם תחי'.</p>\n<p>בברכה לנצל השפעתו בתור פקיד במועצה דתית להרמת קרן ישראל סבא</p>\n<p>בסביבתו ומקומו בלי פשרות, וכל המויסף בזה מוסיפין לו מלמעלה בהמצטרך לו ולב\"ב שיחיו.</p>\n<p>ובברכה לבשו\"ט.</p>"],[1200830086,"ב'תשה\n\n<p>ב\"ה, ג' סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מכ\"ב אייר, בו כותב אודות הכאב ברגלו הימנית. הנה נוסף על מה שעושה בדרך הטבע למלאות הוראת הרופאים במקצוע זה, הרי ע\"פ המבואר בכ\"מ אשר צדקה היא בחי' רגל בקומה הרוחנית של האדם וענין הצדקה כוללת צדקה בממונו וצדקה בגופו היינו טרחת הגוף בענינים דאהבת ישראל, עליו להוסיף אומץ בשני ענינים אלו, והשי\"ת יוסיף ברכתו בהנוגע לבריאותו ברוחניות ובפרט בגשמיות.</p>\n<p>המחכה לבשו\"ט ובברכה לקבלת התורה בשמחה ובפנימיות.</p>\n<p>נ.ב.</p>\n<p>לפלא שאינו מזכיר דבר ע\"ד השיעורים שלו בנגלה ובחסידות.</p>\n<h4><i><b>ב'תשה</b></i></h4>\n<p><b> צדקה היא בחי' רגל:</b> ראה גם לעיל ח\"ו אגרת א'תרפח, ובהנסמן בהערות שם. ח\"ז ב'קפא.</p>"],[1200830087,"ב'תשו\n\n<p>ב\"ה, ה' סיון, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ג והרה\"ח אי\"א נו\"נ מוה\"ר אברהם<br>\nחיים שי'</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מכ\"ז אייר, הנה כבקשתו נשלח לו קונטרס י\"ט כסלו בחבילה בפ\"ע.</p>\n<p>במ\"ש אודות אמירת לזמן בחיריק, הנה כן נוהגים כל אנ\"ש, וכמדומה <b>ברור</b> שכן שמעתי אומר כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, ושאלתי היתה אם ידוע לכהדר\"ג איזה מקור או מסורה בזה. ומה שמקשים מכללי הדקדוק וכותבם ג\"כ במכתבו, הנה בד\"א שצריך להיות בפת\"ח כשמקצר הה\"א הידיעה, אבל אם תיבת זמן היא מלכתחילה בלא ה\"א הידיעה הרי הלמ\"ד יכול להיות בחיריק גם ע\"פ דקדוק, אלא שבכ\"ז, הנני מחפש מקור על זה אף שלע\"ע לא מצאתיו.</p>\n<p>ולקראת חג השבועות זמן מתן תורתנו וקבלתה, הבע\"ל, הנני בזה להביע ברכתי בנוסח כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע לקבלת התורה בשמחה ובפנימיות.</p>\n<h4><i><b>ב'תשו</b></i></h4>\n<p><b> מוה\"ר אברהם חיים</b><b>:</b> נאה. אגרות נוספות אליו - לעיל ח\"ו א'תקפב. ובהנסמן בהערות שם.</p>\n<p><b> לזמן בחיריק:</b> ראה גם לעיל ח\"ח אגרת ב'תקפח.</p>"],[1200830088,"ב'תשז\n\n<p>ב\"ה, ה' סיון, תשי\"ד</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ עוסק בצ\"צ באמונה<br>\nמר א. שקלובסקי שי'</p>\n<p> שלום וברכה!</p>\n<p>זיינער צייט האב איך באקומען אייער בריף - אן דעם דאטום פון שרייבען, אין וועלכער איר באשרייבט דעם מצב אין דעם בית הכנסת חב\"ד בפתח תקוה, און איך בין געווען צופרידען צו באקומען צוגאב ידיעות, אז דער מצב בעסערט זיך, און איך האף אז עס וועט גיין מחיל אל חיל.</p>\n<p>זעלבסט פארשטענדליך אז צו יעדער זאך מאנט הקב\"ה אז עס זאל געטאן ווערען אויך בדרך הטבע, וואס אין די ענינים פון בית הכנסת ובית המדרש ווענדעט זיך דאס אן די גבאים, און ווען מען טוט איז מען דענסטמאל זיכער, אז עס וועט זיין די ברכה פון השם יתברך, ווי עס איז זיין הבטחה, וברכך ה' אלקיך בכל אשר תעשה,</p>\n<p>און בפרט ווען עס האנדעלט זיך וועגען לזכות את הרבים, און בפרטי פרטיות, ווען עס רעט זיך וועגען א בית הכנסת חב\"ד, וואס נשיאינו הק' האבען זיך מוסר נפש געווען אויף אנ\"ש, אז די בתי כנסיות חב\"ד זאלן האלטען אין וואקסען און גרעסער ווערען, און זאלען דינען לויטן מאמר רז\"ל, אלעס א מקדש מעט, פון וועלכען עס זאל זיך אויך אויסשפרייטען ליכטיקייט און ווארימקייט אין די הייזער פון די בית הכנסת באזוכער.</p>\n<p>און עס איז גרויס דער זכות פון דעם וואס מן שמיא קא ממנו לי' צו זיין א גבאי אין אזא בית הכנסת, צו קענען מלא זיין דעם רצון פון נשיאנו הק' אין דאס אויבענדערמאנטע, און איך האף צו הערען פון אייך גוטע בשורות אין דעם.</p>\n<p>און אין די טעג פון פאר מתן תורה, וואס דער מדרש זאגט אז עס האבען געמוזט זיין אלע ששים רבוא אידען, און ווען עס וואלט געפעלט אפילו נאר איינער, וואלט דאס געווען א אפהאלט צו געבען די תורה הק', זאלט איר זיך שטארקען אין אלע מינים פון השתדלות, צו מקרב זיין וועמען עס לאזט זיך נאר צו מקרב זיין צו תורה ומצות, וואס דורך דעם נעמט מען די תורה און אויך דעם נותן התורה, און לויט דעם מאמר רז\"ל אז די <b>התחלה</b> פון מתן תורה איז דאך דער ציווי אנכי, וועלכע זיינען די ראשי תיבות: אנא נפשי כתבית יהבית (שבת ק\"ה ע\"א, תניא פרק מ\"ז).</p>\n<p>בברכה - בנוסח כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע - לקבלת התורה בשמחה ובפנימיות, לו ולכל מתפללי בית הכנסת חב\"ד. המחכה לבשו\"ט.</p>\n<h4><i><b>ב'תשז</b></i></h4>\n<p>נדפסה בלקו\"ש חט\"ז ע' 713, והושלמה ע\"פ העתק המזכירות.</p>"],[1200830089,"ב'תשח\n\n<p>ב\"ה, ה' סיון, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ מוה\"ר<br>\nחיים שי'</p>\n<p> שלום וברכה!</p>\n<p>זה מזמן קבלתי מכתבו בו מאשר קבלת הספרים שנשלחו מכאן, ולפלא שאין מזכיר אם משתמשים בספרים הנ\"ל להחזקת והפצת היהדות התורה והמצוה,</p>\n<p>ומובן אשר אף שצודק במש\"כ שאם הי' מנהיג רוחני מבני התושבים עצמם הרבה נקל יותר להשפיע עליהם ולהנהיגם, אבל אין לחכות עד אז כי הרי הזמן הוא אבדה שאינה חוזרת וגם הנוער ההולך וגדל וכמרז\"ל (קדושין ל\"ד רע\"א). ובמילא עליו ועל חבריו לעשות בזה כפי יכולתם, ואין לך דבר העומד בפני הרצון.</p>\n<p>ובודאי ידוע לו שכאשר באו פליטי רוסיא ופולין לפאריז החלו להתעסק בשדה חינוך הכשר דבני היהודים דצרפת שלא היתה להם בתחלה כל שפה משותפת וצריכים היו להעזר ברמיזה בידים וכו' וכן במלות האחדות דלשון הקדש שבחומש וכו' שידועים היו גם להנ\"ל על ידי זה ששמעום בבית הכנסת וכיו\"ב, ולאט לאט פרחה עבודתם והצליחה בממדים רחבים יותר ויותר ועשיריות נערים ונערות לומדים כבר ומבינים בטוב, ולא עוד אלא שגם השפיעו בבית הוריהם לקרבם ליהדות לתורה ומצותי'.</p>\n<p>וכשילכו בדרך זה במקומם עתה בודאי יצליחו, ולא רק ע\"פ מרז\"ל שהמקיים נפש אחת מישראל כאילו קיים עולם מלא אלא שבודאי יקיימו כמה וכמה נפשות.</p>\n<p>ולקראת חג השבועות זמן מתן תורתנו וקבלתה, הבע\"ל, הנני בזה להביע ברכתי בנוסח כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, לקבלת התורה בשמחה ובפנימיות.</p>\n<h4><i><b>ב'תשח</b></i></h4>\n<p><b> מוה\"ר חיים:</b> הערמאן, אסמארא.</p>"],[1200830090,"ב'תשט\n\n<p>ב\"ה, ה' סיון, תשי\"ד</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ עוסק בצ\"צ מוה\"ר שמואל<br>\nמנחם מענדל שי'</p>\n<p> שלום וברכה!</p>\n<p>נהניתי לקבל מכתבו מר\"ח סיון, בו כותב אודות פעולותיו בין השו\"בים אשר מתקדמים הם לאט לאט לתורת החסידות הדרכותי' ומנהגי' ובודאי כשימשיך בזה בדרכי נועם ובדרכי שלום שהם הם דרכי התורה יצליח בזה עוד יותר.</p>\n<p>וה\"ה למה שכותב אודות התועדות ומהנכון לקרות בהשיחות באסיפת אגודת נשי ובנות חב\"ד. והנה אף שקריאת ספרים החיצונים מקלקלת ומזקת כו' וכו' אבל ידוע שבכלל צריך ללכת מן הקל אל הכבד ובפרט בהנוגע לתעמולה בין הנשים וכמשארז\"ל בזה ג\"כ בנוגע למתן תורה והובא בפירוש רש\"י במקומו כה תאמר לבית יעקב, אשר להנשים צריכה להיות אמירה רכה, וכן בהנוגע להנ\"ל צריכה להיות ההדגשה יותר בההוספה בועשה טוב היינו קריאת שיחות כו' וכו' שאז במשך הזמן יקויים הפסק דין דמעט אור דוחה הרבה חשך ממילא ועאכו\"כ הרבה אור. מובן שאין כוונתי בזה שיתן הסכם ע\"ז שיקראו הנ\"ל בספרים החיצונים אלא שלע\"ע תהי' ההדגשה בהענין דועשה טוב.</p>\n<p>בעת רצון הנה אזכיר את כל אלו שכותב שמותיהם בהיותי על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע והשי\"ת יצליחם שילכו מחיל אל חיל.</p>\n<p>כותב שלומד תניא לפני בחורים צעירים, ובטח בהזדמנות הבאה יודיע אם הם מבני הישיבה או שמבחוץ עדיין והשי\"ת יצליחו בכל הנ\"ל.</p>\n<p>ולקראת חג השבועות זמן מתן תורתנו וקבלתה, הבע\"ל הנני בזה להביע ברכתי בנוסח כ\"ק מו\"ח אדמו\"ר, לקבלת התורה בשמחה ובפנימיות.</p>\n<p>בברכה.</p>\n<h4><i><b>ב'תשט</b></i></h4>\n<p>נדפסה בלקו\"ש ח\"כ ע' 625, והושלמה ע\"פ העתק המזכירות.</p>\n<p><b> מוה\"ר שמואל מנחם מענדל שי':</b> ליברוב. אגרת נוספת אליו - לעיל ח\"ד א'י.</p>"],[1200830091,"ב'תשי\n\n<p>ב\"ה, ה' סיון, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ג והרה\"ח הוו\"ח אי\"א נו\"מ עוסק בצ\"צ<br>\nוכו'<br>\nמוה\"ר אפרים אליעזר שי' הכהן</p>\n<p> שלום וברכה!</p>\n<p>מכתבי כת\"ר נתקבלו.</p>\n<p>ובמה דשאילנא קדמיכון בפרש\"י (סוטה לט, ב) ד\"ה מן דכשכלה אמן אחרון כהנים מחזירין פניהם וש\"ץ מתחיל ש\"ש והכהנים מתפללים רבש\"ע כו' - והרי בש\"ס אמרו דאין הכהנים מחזירין פניהם עד שיתחיל ש\"צ ש\"ש (חו\"י על הרי\"ף סוף מגילה), ולא נמצא בראשונים חבר לרש\"י בזה.</p>\n<p>יל\"פ פירש\"י שהוא מוכרח מסברא (עיין תוד\"ה איבעית - שבועות כב, סע\"ב. שד\"ח כללים מע' סברא) ומש\"ס.</p>\n<p>מש\"ס - דאמר לפ\"ז דאין הכהנים רשאין להתחיל בברכה אחרת עד שיכלה אמן, משמע דתיכף אח\"כ רשאין, וי\"ל דלרש\"י קאי בברכת רבש\"ע, וע\"ד מש\"כ והכריח בב\"י וראה שו\"ע או\"ח סקכ\"ח סוסי\"ח.</p>\n<p>מסברא:</p>\n<p>א) תפלת הכהנים רבש\"ע כו' הוא בהמשך לב\"כ, וא\"כ צ\"ל סמוכה לה (והוא נוסף על הענין שנת' בסק\"י ס\"ז), ומקודם לזה צריכים להחזיר פניהם כדי שיתפללו לרוח שהשכינה שם,</p>\n<p>ב) אף שיש לקשר אמירת רבש\"ע עם ש\"ש - דחד עניניא הוא, אבל מה טעם לפא\"פ דכהנים והעם - לאחר סיום אמן אחרון, <b>שנגמר</b> ענין דב\"כ?</p>\n<p>ומה אומר וכל הפוסקים - וגם אדה\"ז - פסקו אחרת.</p>\n<p>ומ\"ש בש\"ס דאין רשאין להחזיר עד שיתחיל הש\"ץ ש\"ש - יפרש רש\"י דעכצ\"ל כפי' הרש\"ל שמביא כת\"ר במכתבו. ויש להמתיק, דנקט ר\"ח ל' זה דאינו מדויק כ\"כ אגב סיפא <b> עד שיגמור</b> - שזהו עיקר חידושו.</p>\n<p>* * *</p>\n<p>כיון דבתוד\"ה וכי (סוטה לט, סע\"א) מביא פרש\"י מבלי להעיר ע\"ז משמע דס\"ל כותי'.</p>\n<p>מש\"כ בלבוש סקכ\"ח סט\"ו דמחזירים פניהם, כשאומר וטוב בעיניך כו' - כבר הקשה ע\"ז בס' כה תברכו מע' תפלה. גם צ\"ע מל' הלבוש עצמו שם סט\"ז. ואין הזמ\"ג להאריך.</p>\n<p>ולקראת חג השבועות, זמן מתן תורתנו וקבלתה, הבע\"ל, הנני בזה להביע ברכתי, בנוסח כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע:</p>\n<p>לקבלת התורה בשמחה ובפנימיות.</p>\n<p>בברכה.</p>\n<h4><i><b>ב'תשי</b></i></h4>\n<p><b> מוה\"ר אפרים אליעזר שי</b><b>':</b> יאלעס. אגרות נוספות אליו - לעיל ח\"ח ב'שלא. ובהנסמן בהערות שם. לקמן ב'תשנז. ב'תתמה.</p>\n<p><b> הרש\"ל:</b> ל\"ד, אלא כלומר שראוי להתחיל שים שלום אחר אמן וכן מוכח מפרש\"י.</p>"],[1200830092,"ב'תשיא\n\n<p>ב\"ה, ערב חג השבועות ה'תשי\"ד</p><p>ברוקלין, נ.י.</p><p>הרה\"ג הנכבד והנעלה איש המעלה גזע<br>\nתרשישים גדול<br>\nבאישים וו\"ח אי\"א משכיל על דבר טוב וכו'<br>\nמוהר\"ר<br>\nסלימאן דוד ני\"ו ששון</p>\n<p> שלום וברכה!</p>\n<p>נעם לי לקבל פ\"ש מכת\"ר על ידי הרה\"ג והרה\"ח וו\"ח אי\"א נו\"מ עוסק בצרכי ציבור באמונה וכו' וכו' מוהר\"ר בן ציון שי' שם טוב שד\"ר שכתב לי שיש לכת\"ר קביעות עתים ללימוד דברי אלקים חיים היא תורת החסידות, פנימיות התורה.</p>\n<p>ומכיון אשר פנימיות התורה, כלשון הזהר הקדוש, היא נשמתא דאורייתא, הנני בטוח אשר לימוד החסידות יביא וימשיך חיות גם בגופא דאורייתא הוא נגלה דאורייתא, ושניהם יחדיו יביאו חיות גם בגשמיות בבריות גופא, כיון שאצל בני ישראל הגשמיות והרוחניות יחד יהלכון.</p>\n<p>ולקראת חג השבועות, זמן מתן תורתנו וקבלתה, הבע\"ל, הנני להביע ברכתי, בנוסח כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, לקבלת התורה בשמחה ובפנימיות.</p>\n<p>בברכה.</p>\n<p>מוסג\"פ העתק רשימת דברים מענינא דיומא.</p>\n<h4><i><b>ב'תשיא</b></i></h4>\n<p><b> הרה\"ג...ששון:</b> אגרת נוספת אליו - לעיל ח\"ו א'תרסח.</p>"],[1200830093,"ב'תשיב\n\n<p>ב\"ה, ח' סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>... מה שמעורר ע\"ד עסקנותו של הרה\"ח אי\"א נו\"נ עוסק בצ\"צ כו' מוה\"ר...</p>\n<p>שבמילא אפשר זה מפריעו משקידה בתורה כדבעי. הנה ידוע פסק רבנו הזקן (בתורה אור בתחלתו) אשר ע\"י עשיית הצדקה (וצדקה דרבים עאכו\"כ) נעשים מוחו ולבו זכים אלף פעמים ככה, ומהגהות אדמו\"ר הצמח צדק לדרוש זה שנדפס בלקו\"ת לג' פרשיות, מובן שהמספר אלף הוא בדיוק ולא בדרך גוזמא, ובמילא עסקנות דצרכי צבור אי אפשר שתפריע ואדרבא מסייעתו.</p>\n<p>בברכה,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א.</p>\n<h4><i><b>ב'תשיב</b></i></h4>\n<p>נדפסה בלקו\"ש חכ\"ג ע' 531, והוגהה ע\"פ העתק המזכירות.</p>"],[1200830094,"ב'תשיג\n\n<p>ב\"ה, ח' סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> ברכה ושלום!</p>\n<p>במענה על מכתבי' מר\"ח ומיום ה' סיון, הנה נצטערתי לראות במכתבי' שכנראה עדיין לא הוטבו היחסים בביתם, וידוע הכלל ששלום אפילו גרוע טוב יותר ממריבה אפילו קלה וטובה, והרי מובן ששלום אינו גרוע טוב עוד יותר. ולאחרי כל מה שכותבת במכתבי' אינני רואה דבר של ממש שישמש סיבה לפירוד הלבבות בביתם. ובמילא עומד אני בדעתי מאז מה שאמרתי לה כשביקרה אצלי.</p>\n<p>אבל כיון, ואם המצב העכשוי קשה לסבול, אולי אפשר שכפי הצעת בעלה הרב שי', אף כי בשינוי קצת, שיציעו שניהם טענותיהם לפני אחד או שנים מבין אלו שהם ידידים שלה ושל בעלה הרב שיחיו, ולפעמים הרי העומד מן הצד מבהיר את המצב ומראה מוצא איך ליישר העקמומיות שבלב אף שאלו הנוגעים בדבר אינם רואים אותו מפני ההתרגזות והנגיעה בדבר.</p>\n<p>והשי\"ת ימשיך בביתם הברכה בריבוי השלום בריבוי, ותודיע בשורות טובות בזה בהקדם.</p>\n<p>בברכה.</p>"],[1200830095,"ב'תשיד\n\n<p>ב\"ה, ח' סיון, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ג והרה\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמוה\"ר זלמן שמעון שי'</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מג' סיון, הנה ת\"ח על הבשו\"ט אשר נעשו התיקונים הנחוצים בבית הטבילה,</p>\n<p>והשי\"ת יזכנו בתוך כאחב\"י למילוי היעוד המקווה וזרקתי עליכם מים טהורים וטהרתים בגאולה האמיתית והשלימה, שכל פעולה בטהרת בני ובנות ישראל מקרבת אותה...</p>\n<p>המחכה לבשו\"ט מעניניו הפרטים ובפעולותיו הטובות בענינים הכללים.</p>\n<p>נ.ב.</p>\n<p>בודאי דנים ע\"ד הענין של דעי קעמפ שהזמן קצר ובטח צריך להתחיל תיכף בהכנות לזה.</p>\n<h4><i><b>ב'תשיד</b></i></h4>\n<p><b> מוה\"ר זלמן שמעון</b><b>:</b> דווארקין, פיטסבורג. אגרות נוספות אליו -לעיל ח\"ה א'רנט, ובהנסמן בהערות שם.</p>"],[1200830096,"ב'תשטו\n\n<p>ב\"ה, ח' סיון, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ מוה\"ר דן שי'</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מכ\"ח אייר וכן ההגדה עם הספר תולדות יוסף, ות\"ח ת\"ח.</p>\n<p>ומה שכותב מענין קביעות לימוד בתורת החסידות, הנה תורה זו כבר נדפסה בכמה ספרים וקונטרסים, ויפנה בזה להרה\"ח אי\"א נו\"נ עוסק בצ\"צ מוה\"ר שלמה שי' מתוסוף כפי הכתבת דלמטה, אשר תחת ידו נמצאים גם כן ספרים וקונטרסים בחלק תורתנו הק' זה,</p>\n<p>וכבר ידוע פירוש של\"ה הקדוש, חטאתי כי לא ידעתי, אשר גם העדר הידיעה לחטא נחשב, ובפרט בדורנו זה שפסק האר\"י החי הקדוש שמצוה לגלות זו החכמה.</p>\n<p>ומובן שאין יוצאים ידי חובתם באמירה בעלמא אשר אף גם אמירה זו סגולה היא לכמה וכמה ענינים, הנה לימוד התורה צריך להיות גם כן בהבנה והשגה. והאריכות בזה אך למותר.</p>\n<p>בברכת הצלחה בכל הנ\"ל.</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א,</p>\n<p>מזכיר</p>\n<p>נ.ב.</p>\n<p>בודאי אם יש להשיג כתבי יד או ספרים בחכמת האמת הנה יודיעני עד\"ז, ואם אינם אצלי בטח אפשר יהי' להחליפם בספרים מהוצאתנו, ומהנכון שגם בזה יתדבר עם הרה\"ח כו' הר\"ש שי' מתוסוף, כיון שהוא ידוע ע\"ד הספרים הנמצאים כבר בכאן.</p>\n<h4><i><b>ב'תשטו</b></i></h4>\n<p><b> מוה\"ר דן:</b> בנגרדן. אגרת נוספת אליו - לעיל ב'תרנח.</p>"],[1200830097,"ב'תשטז\n\n<p>ב\"ה, ח' סיון, תשי\"ד</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ כו' מוה\"ר שלמה שי'</p>\n<p> שלום וברכה!</p>\n<p>... נהניתי ממ\"ש בסיום מכתבו אשר הכניס ס\"ת לבית הכנסת בשירה וזמרה כראוי, ובטח ראה מכתב כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע בזה (נדפס בקובץ מכתבים שלישי).</p>\n<p>ובימים האלו דתשלומי זמן מתן תורתנו המביאה רפואה לעולם ואשר ע\"י העמל בה זוכים לגשמים בעתם ואשר הארץ נותנת יבולה גו' וגו' הרי יהי רצון שגם בעניניו הנ\"ל ילך מחיל אל חיל הן בגשמיות והן ברוחניות.</p>\n<p>בברכה לבריאות הנכונה. המחכה לבשו\"ט.</p>\n<h4><i><b>ב'תשטז</b></i></h4>\n<p><b> מוה\"ר שלמה:</b> אפלבוים.</p>\n<p><b> מכתב כ\"ק מו\"ח אדמו</b><b>\"</b><b>ר</b><b>:</b> אג\"ק שלו ח\"ו א'תריב.</p>"],[1200830098,"ב'תשיז\n\n<p>ב\"ה, ח' סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>... עס וואונדערט מיר וואס איר טראכט איבער וועגען אייער געזונט, ווען דער בורא ברוך הוא זאגט, שאו מרום עיניכם וראו מי ברא אלה, אז ווען מען זעהט וואס עס טוט זיך ארום זיך מיט אפענע אויגען, זעהט מען אז השם יתברך פירט די גאנצע וועלט, איז יעדער מענש מיט שכל מוז קומען צו דעם באשלוס, אז וויבאלד השם יתברך איז דער אמת'ר אוןן איינציגער בעל הבית פון דער גאנצער וועלט, און ער איז דער עצם הטוב, וועט זיך זיכער אלעס פירען צום גוטען, און ווען מען האט אזא גוטען בעל הבית דארפמען גארניט איבערקלערן וויילע עס איז דאך קיין ספק אז ער - ברוך הוא - ווייס וואס עס איז גוט און וואס עס איז נאך בעסער.</p>\n<p>עס איז אויך פארשטענדליך אז צייטענווייז מישט זיך אריין דער יצר הרע און צומישט די מחשבות פון דעם מענשן, אבער וואס איז דא נתפעל צו ווערען און וואס איז דא צו גלויבען דעם מלך זקן וכסיל,</p>\n<p>און השם יתברך זאל אייך העלפען אז איר זאלט מקיים זיין דעם אנזאג עבדו את ה' בשמחה, און ווען מען טוט דאס אויף א אמת, זעהט [מען] אפילו מיט די פליישיגע אויגען אז עס איז דא פון וואס צו זיין צופרידען און פרייליך.</p>\n<p>און השי\"ת זאל אייך מצליח זיין אז געזונטערהייט און פרייליכערהייט זאלט איר קענען טאן אין ענינים פון תורה ומצות מתוך הרחבת הדעת.</p>\n<p>בברכה,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א.</p>"],[1200830099,"ב'תשיח\n\n<p>ב\"ה, ח' סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מכ\"ט אייר, הנה ירבה באותיות התורה והתפלה וישתדל שיהיו חקוקים במוחו לכל הפחות איזה פרקים משניות ואיזה פרקים תניא, והדרוש ד\"ה והדרת פני זקן בלקוטי תורה סוף פ' קדושים. כן יפריש בכל יום שני וחמישי קודם התפלה בבקר פרוטה או שתים לצדקה, וישתדל כפי האפשרי בהשפעה על הנוער לקרב את לבם לאבינו שבשמים. נוסף על כל זה, והוא העיקר, שיסיח דעתו מהעון ואפילו מתיקונו, אשר כל הנ\"ל הוא סגולה ותיקון לכשיעבוד את השי\"ת בשמחה הרי לאט לאט ירגיש בהטבת מצבו. ויהי רצון שההתחלה בזה תהי' בקרוב.</p>\n<p>ובודאי למותר להעירו על שמירת שלשת השיעורים השוים לכל נפש מתקנת כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע והם בחומש תהלים ותניא הידועים.</p>\n<p>בברכת הצ' בעניניו.</p>"],[1200830100,"ב'תשיט\n\n<p>ב\"ה, ח' סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>עס איז ערהאלטען געווארען אייער בריף פון /5;2amp&amp; אין וועלכען איר שרייבט אין די ערטער וואו איר זייט געווען ביז יעצט און אז דאס האט מיטגעבראכט ניט צו היטען כו'.</p>\n<p>עס איז דורכאויס נויטיג אז פון איצטער אן און ווייטער זאלען די דינים פון טהרת המשפחה אפגעהיט ווערען לויט דער פאדערונג פון תורתנו הק' וועלכע איז אויך א תורת <b>חיים</b>, וועלכע בריינגט אריין לעבען און פרייד בא אידען אין זייערע הייזער,</p>\n<p>און לפחות אין א געוויסער מאס צו פאריכטען דאס וואס עס איז געווען ניט ווי עס באדארף צו זיין, זאלט איר אמווייניגסטען אמאל אין וואך געבען עטליכע פרוטות וועלכע זאלען פארנוצט ווערען אויף צו אויפהאלטען א מקוה אין איינע פון די שטעט בארצנו הק' תבנה ותכונן, און אויך צו איינווירקען אויף אנדערע פרויען אז זיי זאלען אפהיטען דעם הייליגען געבאט פון הקדוש ברוך הוא, פון אפהיטען טהרת המשפחה, וועלכעס בריינגט געזונט און הצלחה.</p>\n<p>און השי\"ת זאל אייך העלפען אנזאגען גוטע בשורות אין דאס אלעס אויבען דערמאנטע.</p>\n<p>בברכה,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א.</p>"],[1200830101,"ב'תשכ\n\n<p>ב\"ה, ט' סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>איך בין געווען צופרידען צו באקומען א גרוס פון אייך דורך הרה\"ח אי\"א נו\"נ עוסק בצ\"צ מוה\"ר מנחם שמואל דוד הלוי שי' רייטשיק שד\"ר, וועלכער האט מיר אויך איבערגעגעבען אז איר האט געקויפט א לאט און דיינקט צו בויען דארט. און השם יתברך זאל העלפען עס זאל זיין בהצלחה, און לויט דעם אויסדרוק פון רבנו הזקן, זאל השם יתברך געבען אייך פילע גשמיות (מאטעריעלע מעגליכקייטען) און איר זאלט מאכען פון די גשמיות רוחניות (פארוואנדלען דאס אין באטייליגונג און שטיצע פון ענינים פון תורה און מצות) און איר זאלט דאס טאן געזונטערהייט און פרייליכערהייט.</p>\n<p>הרב רייטשיק שי' האט מיר אויך איבערגעגעבען אז איר זייט א דאקטאר. בין איך זיכער אז עס [איז] איבעריג צו אנדייטען אייך, אז בא א מענטשן איז דער געזונט פון קערפער - גוף - פארבונדען מיט דעם געזונט פון דער נשמה, און דעריבער איז פאר אייך ניט נויטיג קיין באזונדערע ערקלערונגען אויף וויפיל עס איז וויכטיג אויך בא א אידען אז זאל זיין נשמה באקומען דאס וואס זי נויטיגט זיך, וואס דאס זיינען די ענינים פון תורה ומצות, וואס נאר דענסטמאל קען זיין קערפער זיין געזונט. וואס דאס איז אויך איינע פון די רמזים - אנדייטונגען - פון דער מצוה פון לייגען תפילין, וועלכעס מען טוט אן אויפן קאפ וואו עס געפינט זיך דער מוח (ברעין) און אויפן האנד געגענאיבער דער הארץ, וואס מיטן מוח (ברעין) זיינען פארבונדען אלע ניערווען פון גאנצען קערפער, און פון דער הארץ ווערט פאנאנדערגעשיקט דאס בלוט אין גאנצען קערפער, און אין תפילין איז דא פיר פרשיות פון תורה, און דער אנהויב פון זיי איז דער פסוק,] שמע ישראל הוי' אלקינו הוי' אחד, וואס דאס איז דער רוף צו יעדער אידען אז ער זאל הערען און געדיינקען אז השם יתברך איז דער איינציגער בעל הבית אין אלעס און אויף אלעס און בדרך ממילא אויך אין <b>זיין</b> פריוואט לעבען, און אז אט דער וויסען נעמט דורך און דרינגט אריין אין זיין מוח און הארץ, זיינען דענסטמאל דער גאנצער קערפער - גוף - זיינער און זיין גאנצע נשמה בא עם געזונטע.</p>\n<p>איך האף אז אט די אייניגע שורות גיבען איבער אין קורצע שטריכען איינע פון די וויכטיקע אנדייטונגען - רמזים - פון דער מצוה פון תפילין, אין איר פארבינדונג מיט די טאג טעגליכע ענינים.</p>\n<p>איך וועל זיין צופרידען צו הערען פון אייך פון צייט צו צייט און ווינש אייך הצלחה אין דאס אלעס אויבען דערמאנטע.</p>"],[1200830102,"ב'תשכא\n\n<p>ב\"ה, ט' סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>לאחרי הפסק נעם לי לקבל מכתבו מג' סיון והעיקר לקרות בו אשר מציעים נכבדות בשביל בתם... ומה שכותב שהורי האברך אינם דורשים נדן ורוצים לקחת על עצמם כל הסידור של דירה רהיטים ושאר הוצאות וכו'. הנה אף שמחד גיסא נהניתי מזה בתור הוכחה למעלת בתם תחי' אבל לאידך גיסא הנה איש ואשה הישראלים בכלל והורים בפרט דארפען וועלען אז זייערע קינדער זאלן זיי קאסטען טרחה בגופם בנשמתם ואפילו בממונם, וידוע מאמר הזהר הק' (ח\"ב קכח, א) אשר בענינים של קדושה אין צריך להיות הענין דחנם; ועאכו\"כ בהנוגע לנשואי בת, שלא רק שצריך להיות קשור בהוצאות אלא שגם אין לקמץ בהם ובודאי נכנס זה בהענינים של אדם שנקצבו לו בעשרה ימים שבין ראש השנה ליום הכפורים, און אז מען שטעלט זיך ברייט גיט השי\"ת אויך מיט א ברייטקייט...</p>\n<p>בברכה המחכה לבשו\"ט,</p>\n<p>נ.ב.</p>\n<p>בכלל צריך להיות הסדר שחתן יביט על חותנו מלמטה למעלה ואם החתן יש לו שיעורים קבועים בתניא, הרי עאכו\"כ שלהחותן צ\"ל שיעורים קבועים לא רק בתניא או גם בלקו\"ת מאמרים וכו' והשי\"ת יזכהו לבשר טוב גם בזה.</p>"],[1200830103,"ב'תשכב\n\n<p>ב\"ה, ט' סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> ברכה ושלום!</p>\n<p>... צווישען אנדערע זאכען האט מיר אייער מאן שי' אויך דערציילט וועגען דעם געזעץ פון אייער לאנד, אז נאכן עלטער פון זיבעציג יאר באקומט יעדער בירגער א געוויסע פענסיע פון דער מלוכה, און אז איר טראכט איבער צי זאלט איר דאס נעמען אדער ניט.</p>\n<p>יעדער זאך וואס ווערט געטאן אין דער וועלט און בפרט בא אידען איז דאס בהשגחה פרטית און עס איז פאראן אין דעם א ספעציעלער מיין און אינהאלט, און ווען א איד האט די מעגליכקייט צו פארגרעסערען זיין איינטיל אין די זאכען פון תורה ומצות, און ווער רעט נאך אויב אט די מעגליכקייט קומט אן איבעריגע אנשטריינגונג פון דעם מענטשענס זייט, דארף דאס אנגענומען ווערען ווי א רמז - אנדייט - פון אויבען, אז זיכער קען מען דאס אויסניצען אין א גוטען אופן, ד.ה. לויט דער אנווייזונג פון תורתנו הקדושה, און אויב דער מענטש איז אזוי איינגעארדענט אז פאר זיינע לעבענס באדערפעניש דארף ער ניט די געלט, איז דאך זיכער אז דורך די געלט קען ער פארגרעסערען זיין חלק אין געבען צדקה אדער ריכטיגער אוועקגעבען די גאנצע געלט אויף צדקה און בפרט אזא צדקה וועלכע איז פארבונדען מיט מאכען נעהענטער אידישע הערצער צו אונזער פאטער אין הימעל.</p>\n<p>און דעריבער רעכין איך אז אויך אין אייער פאל וויבאלד אז דער אלגעמיינער געזעץ בארעכטיקט אייך צו א געוויסע סומע יעדער חדש וואלט געווען ניט מער ווי רעכט און אויך א זכות פאר אייך אז איר זאלט אויסניצען די רעכט געזונטערהייט און דורך דעם פארגרעסערען אין א חשוב'ער מאס די באטייליגונג פון אייך און אייער מאן שיחיו אין דער צדקה וועלכע פארנעמט זיך צו ערציהען אידישע קינדער אויף צו מאכען זיי נאך מער אידיש און צו זיין אידען ווי עס פאדערט אונזער תורה הקדושה, און השם יתברך זאל העלפען אייך אז צוזאמען מיט אייער מאן אויף לאנגע גוטע יארען זאלט איר געבען צדקה מיט א ברייטער פולער האנט געזונטערהייט און פרייליכערהייט.</p>\n<p>בברכה.</p>"],[1200830104,"ב'תשכג\n\n<p>ב\"ה, ט' סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מי\"ז אייר והקודם לו, הנה מ\"ש אודות גיסתו אחות</p>\n<p>אשתו - תחינה - והשידוך שלה עם האברך... הנה גם בעצמו מונה וסופר כל המעלות שבדבר ואעפ\"כ נראית דאגה מבין השיטים ממה שלפי דעתו אין להם האמצעים הדרושים לשכור דירה כו' וכו' ויתאר הענין לעצמו אשר אמרז\"ל שקשה לזווגם כקרי\"ס ובכ\"ז מצא את שידוכה המתאים בשבילה הן בגשמיות והן ברוחניות ואם נס כזה נעשה הרי דואג הוא מה יהי' עם מטבח רהיטים וכו'?! בה בשעה שבתור קרובה צריך הי' להודות ולהלל להשי\"ת שהמציא לה אברך ירא אלקים לומד תורה כו' (וכמו שכותב במכתבו) ושלמרות שאיננו בעל הון נתנה הסכמתה על זה בלבב שלם, והלואי שמכאן ולהבא יודיע אך טובות כיוצא בזה.</p>\n<p>בנוגע לענינו ולהסתדרותו הפרטית. הנה מכבר מלתי אמורה על יסוד הידוע מרבותנו הק' מתחיל מבעש\"ט והנשיאים אחריו עד ועד בכלל כ\"ק מו\"ח</p>\n<p>אדמו\"ר - זצוקללה\"ה נבג\"מ זי\"ע שמרה שחורה ועצבות צריך לגרשם כלה ממחנה ישראל יהי' מה שיהי' ואיננה מביאה תועלת ואדרבה הרי היא סיבה ומקום לכל עניני הירוס, וה\"ה בענינו שחבל על מחשבותיו ממין זה וימסור עצמו לעבודה בחינוך הכשר למרות הטענות השונות שמציע שלא להתעסק בזה ואז הרי סו\"ס ימצא סיפוק נפשי ויווכח אשר לא הי' יסוד לפקפוקים וספיקות והשי\"ת יצליחו שיהי' זה בהקדם.</p>\n<p>בברכת הצלחה בכל הנ\"ל המחכה לבשו\"ט בהנ\"ל וכן בהנוגע לבריאות בנם שי'.</p>"],[1200830105,"ב'תשכד\n\n<p>ב\"ה, ט' סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>בתמהון נודעתי שאינו נזהר בשמירת בריאותו, שזה בהיפך מהמבואר בתורת החסידות בכמה מקומות ונעתק ג\"כ במאמר יו\"ד שבט תשי\"ג איך שצריך להזהר בזה, וכבר ידוע פסק הרמב\"ם שזה מדרכי השם,</p>\n<p>ומובן שאין בזה סתירה לשמירת סדרי הישיבה וקביעות עתים נוספות בתורה ותפלה כו' וכו', כי הרי אי אפשר שמצוה אחת תהי' בסתירה למצוה אחרת, ובפרט בתלמיד ישיבת תומכי תמימים שנתיסדה ומתנהגת ע\"י כ\"ק נשיאנו רבוה\"ק זצוקללה\"ה נבג\"מ זי\"ע שעליו לשמור את סדרי הישיבה ולשמור את גופו ונשמתו שיהיו בריאים ושלמים ויוכל לעבוד את השם מבלי בלבולים,</p>\n<p>ובמילא על כל פנים מכאן ולהבא ישמור סדרי אכילה ושתי' ושינה כפי הנצרך והדרוש למבנה גופו כי אין הכל שוים בזה, ועל ידי שמירה וזהירות זו יתוסף לו גם כן בהבנה והקליטה בלימודו ובקיום המצות, וכבר ידוע פסק רז\"ל יגעת ומצאת.</p>\n<p>המחכה לבשו\"ט בכל הנ\"ל,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א.</p>"],[1200830106,"ב'תשכה\n\n<p>ב\"ה, יו\"ד סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו (שנתקבל באיחור זמן) בו כותב אודות בנו האברך הנעלה עוסק בצ\"צ בעל מדות ורב פעלים בקירוב לבם של בני ישראל לאבינו שבשמים וכו' מו\"ה... שי' ובנוגע להסברות שישנם במקום בו יחפש זיווגו הנכון וחושש כת\"ר למה שיאמרו הבריות וכו' שאינו שומע ח\"ו בקול אביו הרוצה שיסע בדוקא למדינה פלונית בענין הנ\"ל ויבואו לקס\"ד שהשפעת החסידות על בנו הוא להניאו מלקיים מצות כבוד אב וכו'.</p>\n<p>ובאמת אינני יודע אם הנ\"ל צריך תירוץ, כי הכל יודעים אשר תורת החסידות הדרכותי' מקרבים את לב האדם לעבודת הבורא ובמילא לקיום מצותיו ולא ח\"ו להיפך.</p>\n<p>ונבהלתי בקראי המכתב כת\"ר חשש כזה. והלימוד זכות שלי הוא שאין אדם נתפס על צערו, וכיון שנדמה לכת\"ר שטוב יותר לפניו הנסיעה... הרי הוא ע\"ד האמור במשה רבנו שכשבא לכלל כעס שכח הלכה. ובפרט שידוע פסק תוה\"ק והוא בשו\"ע יו\"ד הלכות כבוד אב סוף סי' ר\"מ שתלמיד הרוצה ללכת למקום שהוא בטוח שיראה סימן ברכה בתלמודו ואביו מוחה בו לפי שדואג ששמע שמעלילים שזהו ענין פקוח נפשות אינו צריך לשמוע לאביו בזה, וכן אם הוא מוחה בבן לישא אשה זו שחפץ בה הבן אין צריך לשמוע אל האב. ועיין שם בנ\"כ השו\"ע.</p>\n<p>והנה פסק דין זה גם אם האב יש בידו ראי' ברורה וטעם ברור, וכנ\"ל שהא\"י מעלילים או שכבר ראה האב את האשה שחפץ בה הבן או בני משפחתה ומוחה בנשואין אלו אבל בנדון דידן שאין ראיות והוכחות אלו כלל וכלל עאכו\"כ שפס\"ד הנ\"ל בתקפו הוא.</p>\n<p>ועוד זאת והוא העיקר שאינו מובן כלל מפני מה צריך כת\"ר להעמיד את בנו הנעלה שי' בנסיון כזה ובידו הוא שלא לצוות עליו לנסוע דוקא למקום פלוני, ובמילא סר כל הענין דכבוד אב בנדון דידן, וידוע פס\"ד התורה בזה והוא ג\"כ שם בשו\"ע סעיף י\"ט וכ'...</p>\n<p>תקותי חזקה שכת\"ר יעודד את רוח בנו שי' ויחזק את ידו במלאכתו מלאכת הקדש וירים את רוחו להמשיך בה בתוספת אומץ, ובטוח הקב\"ה לשלם שכר מצוה גדולה זו מידו המלאה והרחבה. ויה\"ר מהשי\"ת שכת\"ר ישבע רוב ענג חסידותי מכל יו\"ח שיחיו.</p>\n<p>בת\"ח מראש אם יודיעני שנסתדרו כל הענינים הנ\"ל באופן הכי טוב.</p>\n<p>ובברכה.</p>"],[1200830107,"ב'תשכו\n\n<p>ב\"ה, יו\"ד סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> ברכה ושלום!</p>\n<p>קבלתי מכתבה בו כותבת מה שנמסר לה בשמי ועונה על זה אשר יש פרטים שמסכמת עליהם ויש פרטים שאינה רוצה בהם ובמילא יהי' זה רק בתור כפי' כו' וכו'.</p>\n<p>והנה כל גישה זו אינה נכונה ומתאמת, כשנגשים להתחיל סדר חיים, והרי ברור שכל אחד רוצה שיהיו חיים מאושרים, והאושר בחיים תלוי באיכות ובכמות <b>דוקא</b> במלך מלכי המלכים הקב\"ה, הרי אין השאלה במה <b>האדם</b> רוצה ובמה אינו רוצה, כי אם הגישה היא במה תלוי ובמי תלוי אושר האדם ובאיזה תנאים יש לקוות שיבוא האושר בפועל.</p>\n<p>ואמרתי ל... שי' כשהי' כאן שאשת האדם יכולה להיות עזר לו או כנגדו, ואף שקשה לשער מראש ולדעת מראש בבטחון גמור בכל המאה אחוז איך שיהיו היחסים במשך עשיריות בשנים, הנה בחינה ידועה וחשובה בזה הוא היחס שבין הצעירים וההתחשבות בהשקפתם - של האדם עם השני קודם החתונה, ועליו לברר את זה (וכן על כל אחד ואחת שרוצה לבוא בברית הנשואין), עד כמה שאפשר.</p>\n<p>ובהנוגע אליו הוא שלא יעלים ממנה דבר אודות השקפתו עתה על החיים, וישאלה לאמר לו החלטתה ברור מה היא יחסה אל השקפתו. ואם תתנהג היא כנ\"ל במכתבה שתסדר את חייה מתאים לרצונותי' מבלי התחשב עם דעתו של הקב\"ה והוראותיו אשר נתן לכל אחד ואחת מעם ישראל, צריך להתבונן היטב הדק בשאלת הנשואין והשידוך בכללותם,</p>\n<p>וכיון ש... רצה לדעת דעתי בזה וגם הסכמתי, וכמו שהתבטא גם ברכתי, הרי אני מצדי יכול להסכים בלבב שלם כשרואה אני המקסימום האפשרי לתקוה שחייהם יהיו מאושרים, וזהו תלוי בזה שיסדרו את חייהם על יסודי התורה והמצוה כפי שהם אמורים בשולחן ערוך ולא כפי פירושו של כל אחד ואחת שלפרט פלוני מסכים הוא ולפרטים אחרים אין מסכים, כי הקב\"ה אומר שהליכה בדרכיו אשר הורה מבטיחה חיים בברכה והצלחה, מה שאין כן הליכה בדרכים אחרים, ואינני יכול לקבל על עצמי אחריות דהשתתפות בענין כזה כשאחד מהצדדים נגש לכל הדבר שאינו רוצה ואינו מבטיח וכופים אותו היפך דעתו כו' וכו',</p>\n<p>ואם מי שהוא אומר שאי אפשר לוותר וללכת דוקא בכיסוי הראש במטפחת או בפאה נכרית ואין נפקא מינה לו אם על ידי זה מסכן את אשרו ואושר הצד השני בחיים המשותפים עשיריות בשנים, הרי אין לאיש כזה כל רגש אחריות ולא הערכה מתאימה וידיעה מה הם חיים משותפים ועד כמה כדאי לוותר אפילו על ענינים יותר חשובים ובלבד שיהיו חיים מאוחדים ומאושרים, וכנ\"ל, אי אפשר זה בחיי איש ואשה הישראלים כי אם על ידי תורה ומצוה.</p>\n<p>והשי\"ת יזכהה להכיר את דרכה בחיים ולהחליט לטוב לה בטוב האמיתי שהוא הטוב הן בגשמיות והן ברוחניות, ושבאמת אי אפשר זה בלא זה.</p>\n<p>בברכה,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א,</p>\n<p>מזכיר</p>"],[1200830108,"ב'תשכז\n\n<p>ב\"ה, יו\"ד סיון, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמוה\"ר יהושע שניאור זלמן שי'</p>\n<p> שלום וברכה!</p>\n<p>... ועוד הפעם אכפול ואשלש מה שכתבתי כ\"פ שמוכרח הדבר שיגדילו את הישיבה ככל האפשרי הן בכמות והן באיכות, ואין הקב\"ה בא בטרוניא עם בריותיו ובודאי שהנ\"ל ביכולתם הוא אלא שלא יגעת - לפום גמלא - ומצאת אל תאמין, ולהסיר ענין העלמות והסתרים על כל עבודה איזה שתהי' ובפרט בעבודה בשדה החינוך הכשר ובמדינה שזהו בגדר התחלה, ובכ\"ז מצטער הוא במאד מאד שזה כמה חדשים שהם היחידים הפועלים בזה כי... ראו הצלחה מופלגה במוחש בענין הבנין ובהיחס הטוב מצד כמה אנשים שמתחלה לא קוו על זה, ובכ\"ז עדיין חושבים חשבונות כו' וכו',</p>\n<p>וכל [ה]הסברים שכותבים שאין אצלם למדן גדול במאד יודע שפת המדינה כו', הנה המציאות בעבודת חב\"ד במדינות שונות מכחשת את כל תירוצים אלו. ובכלל מה התועלת מהתירוצים שברור הדבר שצריכה להיות ישיבה תו\"ת בפועל ממש גם באוסטראליא, וההוכחה היותר גדולה על זה הוא כי לולא ענין זה אינו מובן כלל וכלל למה הביאם השי\"ת לשם, אי אין נראה לא ריוח גשמי ולא ריוח רוחני. וכמדומה שכבר כתבתי להם פעם פתגם הרז\"א נ\"ע שאמר, אז א ליטוואק גלויבט ניט ביז ער ציילט ניט איבער, אבל לא להאמין גם לאחר שסופר...</p>\n<p>מ\"ש שבהישיבה יהיו אוצר ספרים של נגלה וחסידות, נכון הדבר, וכמדומה שכבר נמצא אצלם ספרי' מספרי הוצאת קה\"ת... וכשישלח רשימת הספרים הנמצאים כבר הנה ישלימו להם את החסר.</p>\n<p>בברכת הצלחה בכל הנ\"ל. המחכה לבשו\"ט.</p>\n<h4><i><b>ב'תשכז</b></i></h4>\n<p><b> מוה\"ר יהושע שניאור זלמן שי':</b> סרברנסקי. אגרות נוספות אליו -לעיל ב'תרפא, ובהנסמן בהערות שם.</p>\n<p><b> את הישיבה:</b> במלבורן. ראה לעיל שם.</p>\n<p><b> פתגם הרז</b><b>\"</b><b>א</b><b>:</b> ראה גם לעיל ח\"ח אגרת ב'תקנ.</p>"],[1200830109,"ב'תשכח\n\n<p>ב\"ה, יו\"ד סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתביו מה סיון ושלאחריו עם הפ\"נ המוסג\"ב אשר אקראם בעת רצון על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, ובודאי יעורר ר\"ר על כל אלו הנזכרים בם כאו\"א להמצטרך בגשמיות וברוחניות.</p>\n<p>מ\"ש אודות הכתה שלו שמפני כמה סיבות התבטלו מלימוד למשך זמן וכו', הנה ידוע פסק רז\"ל יגעת ומצאת, ועאכו\"כ במלאכה זו שהיא מלאכת שמים ובמילא הסיוע בזה מלמעלה היא במדה גדולה ביותר, אלא שכמו בכל עניני תומ\"צ נדרש בענין זה הגישה מתוך שמחה ובטחון בהצלחת העבודה שאז רואים בחוש הן המשפיע והן המקבלים איך שמתגדלת ההצלחה והולכת וגדולה, וזה נוסף על מה שבאופן כזה הפעולה על בריאת המשפיע היא לטוב ולהוספה בבריאות גם כפשוטה.</p>\n<p>מ\"ש אודות האברך... שדוחה הענין של בדיקתו הוא מפני השאלה שיש בדבר, הנה נודעת בזה הוראת כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע אז צוליב אזא זאך כדאי למסור נפשו, אלא שבבחינות אלו גופא ישנם כמה ענינים ואופנים ומובן שכדאי להתחיל בהאופן שהחשש ע\"פ הדין הוא במיעוטו. והשי\"ת יצליחו לבשר טוב בכל הנ\"ל ובקרוב.</p>\n<p>בברכת הצלחה.</p>\n<p>נ.ב.</p>\n<p>לפלא שבכל מכתביו אינו מזכיר דבר ע\"ד השתתפותו בהתועדות חסידותיות וכו'.</p>\n<h4><i><b>ב'תשכח</b></i></h4>\n<p><b> הוראת:</b> ראה גם לעיל ח\"ו אגרת א'תרצז, ובהנסמן בהערות שם.</p>"],[1200830110,"ב'תשכט\n\n<p>ב\"ה, י\"ב סיון, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסקים בצ\"צ,<br>\nמוה\"ר אברהם שי' דרייזין<br>\nומוה\"ר אפרים שי' וואלף</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת שלשת מכתביהם מי\"ד וי\"ז וכ\"ט אייר - בהנוגע לבית ספר למלאכה...</p>\n<p>והנה מובן מעצמו, שאין ביכולתי לשנות דרך ליובאוויטש וגם אין זה ברצוני - אפילו אם תהי' בזה דרישת משרד העבודה ביחד עם הדזשוינט. וברור דברתי עם הרב יאנג שי', כשהי' תחלת הדבור אודות בית ספר למלאכה, שיהי' ברוחה של ליובאוויטש, כי באם לאו - הרי ידי מסולקות וגם לא אתחיל בזה. והוא תמה גם על הקס\"ד בזה שאפשר שיתערבו בענינים כמו אלו. ומובן שהשקפתי בזה לא נשתנתה במשך זמן זה. ובמילא מה שמוכרח ואי אפשר לוותר על זה - שהזמן המוקדש ללימודי קדש יהי' <b>יותר</b> מזמן המוגבל ללימוד המלאכה (מה טוב שיהי' שני שלישים מהזמן לתפלה ולימודי קדש ושליש לימוד המלאכה).</p>\n<p>ב) מוכרח שסדר הלמודי קדש יהי' לפני הסדר של לימוד המלאכה וגם לאחר המלאכה - סדר לימוד בלילה.</p>\n<p>ג) מוכרח ג\"כ שלימוד הדא\"ח יהי' הן בבקר והן בערב.</p>\n<p>ד) הנקודה העיקרית בבי\"ס למלאכה - שלימוד המלאכה הוא טפל ללימודי הקדש, ולא, ח\"ו, להיפך...</p>\n<p>ו) כנראה, אשר בחורף העבר שלחו מכתבי בקשת עזר בעד הבי\"ס למלאכה לארצוה\"ב ואולי גם לשאר מקומות. ואתענין לדעת אם היתה ההכנסה גדולה על ההוצאה, ובכמה לפי ערך.</p>\n<p>ז) אף שזוהי נקודה שנוגעת ביותר לתו\"ת דלוד מאשר לבי\"ס למלאכה, אבל כיון שנוגע גם לבי\"ס למלאכה - מכניס הנני ענין זה במכתבי דנא, והוא: אשר כנראה ממכתבים המתקבלים לכאן, יש תנועה בתלמידי תו\"ת דלוד לברוח לבי\"ס למלאכה.</p>\n<p>וכבר ידוע מרז\"ל לא עכברא גנב אלא חורא כו'. וצריך להלחם בזה בעוד מועד, באופנים המתאימים, ולעשות איזה הגבלות וסדרים בזה - מי הוא המתקבל לבי\"ס למלאכה. ומה טוב שאחד מתנאי הקבלה יהי', שבתחלה צריך ללמוד זמן מסוים באחת מישיבות חב\"ד שבאה\"ק ת\"ו, ורק אח\"כ יתקבל לבי\"ס למלאכה.</p>\n<p>ח) טוב הוא שלע\"ע אינם מקבלים תלמידים נוספים על אלו שישנם כבר, כי עד שיסתדרו הדברים, טוב שבבי\"ס למלאכה יהיו רק תלמידים כאלו שכבר מכירים אותם שכבר בילו משך זמן במוסד חינוך חב\"די.</p>\n<p>ט) בהנוגע להוצאות בי\"ס למלאכה, הנה הי' המדובר שלאחרי שיקימו הבנין - הרי הדזוינט יקח ע\"ע החזקת המורים התלמידים כו' וכו'. מובן שקודם שיצא הדבר לפועל לא יכלו לפרט הפרטים בזה, ולפלא שאין הם מזכירים במכתב אם נאמר להם מה עד\"ז עתה. ובכל אופן, מה שמקשרים את בי\"ס למלאכה עם הועד וכו' אין הדבר כן, וכמש\"כ בתחלת הדבור ע\"ד בי\"ס למלאכה - כי זהו ענין נפרד בפ\"ע וכו' וכו'.</p>\n<p>י) על שאר הענינים אבוא בפעם אחרת, כי אין ברצוני לעכב מכתבי זה בכדי לקבוע מסמרות בענינים עיקרים דבי\"ס למלאכה. ועיקר העיקרים - שזהו בית ספר לחינוך נוער ישראל ברוח ישראל סבא, אלא שלומדים שם ג\"כ מלאכה, שבזה מבוארות כמה מנקודות הנ\"ל.</p>\n<p>בברכה,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ב'תשכט</b></i></h4>\n<p><b> מוה\"ר אפרים שי' וואלף:</b> אגרות נוספות אליו - לעיל ח\"ה א'שלו, ובהנסמן בהערות שם.</p>\n<p><b> ללימודי קודש:</b> ראה גם לעיל ח\"ח אגרת ב'שעו סי\"ד. לקמן ב'תתי.</p>\n<p><b> ממכתבים המתקבלים</b><b>:</b> ראה גם לעיל אגרות ב'תרס. ב'תרעז.</p>"],[1200830111,"ב'תשל\n\n<p>ב\"ה, ט\"ו סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבם מיו\"ד סיון בו שואלים חוות דעתי אם יסעו למרוקה על משך שלשה או ארבעה חדשים כדי שיהי' באפשריותם להשלים כסף נסיעה לארצוה\"ב וכו'.</p>\n<p>והנה כבר ידוע, הן בנגלה דאורייתא והן בנסתר דאורייתא, גודל ענין תלמוד תורה, אשר אפילו חפצי שמים לא ישוו בה, אלא שע\"פ פסק רז\"ל (שבת ל\"א סוף ע\"א) צריך להיות לימוד התורה ביראת שמים דוקא אשר אז יראת ד' היא אוצרו ויש קיום ללימוד התורה הנרמזת בכתוב והי' אמונת עתך גו' חכמה ודעת,</p>\n<p>וכיון אשר הצליחם השי\"ת והעמידם בקרן אורה, היא ישיבת \"תומכי תמימים\" שנתיסדה ומתנהלת על ידי צדיקים יס\"ע כ\"ק אדמו\"ר - מהורש\"ב ובנו הוא מו\"ח - זצוקללה\"ה נבג\"מ זי\"ע, הרי עליהם לייקר כל רגע, ועאכו\"כ ימים שבועות וחדשים, להיות בד' אמות שלה, ולשקוד בלימוד תורת הנגלה ותורת הנסתר במסירה ונתינה אמיתית.</p>\n<p>ובמילא - כל רעיון המבלבל אפשריות זו, אף שנדמה לכאורה שבא מצד היצר טוב, הרי אין זה אלא מדרכי היצר הרע, אשר אמרו עליו שהוא אומן (שבת ק\"ח ע\"ב) בעבודתו, ובא לכל אחד ואחד בפיתויים כאלו שמקוה שישמעו להסתה שלו ולהשתדלותו להסיר את האדם מהמסלה העולה בית א-ל,</p>\n<p>וה\"ה בנדון שלהם: יחליטו בעצמם בהחלטה אמיתית, אשר ילמדו במסירה ונתינה במקום שם נמצאים עתה, ואל ישמעו לטענות הבאות מצד שמאל, שמסיתם לאמר לכשאפנה אשנה, והרי ידוע דבר משנה (אבות פ\"ב מ\"ד) אל תאמר לכשאפנה אשנה שמא לא תפנה.</p>\n<p>ובפרט שכל אחד ואחד מבני ישראל הרי מאמין הוא ומקוה לביאת משיח צדקנו במהרה בימינו, אשר ההקדמה וההכנה לזה - אומר מלך המשיח למורנו הבעל שם טוב זצוקללה\"ה נבג\"מ זי\"ע - שיבוא לכשיפוצו מעינותיו של הבעש\"ט - חוצה, ובמילא עליהם לנצל כל אפשריות בזמן לקלוט תורת הבעש\"ט, שנתבאר הדק היטיב בתורת חסידות ח'כמה ב'ינה ד'עת למען יוכלו לעמוד בראש אלו שיזכו לקבל פני משיח צדקנו בקרוב.</p>\n<p>ולא המדרש עיקר אלא המעשה היינו הלימוד <b>בפועל</b> בשקידה מסירה ונתינה מתוך יראת שמים טהורה, שזה בה ע\"י עבודת התפלה, וניכר ג\"כ בקיום המצות בהידור.</p>\n<p>ואחכה לקבל בשו\"ט מהם שמתמידים בלימודם בנגלה ובחסידות ביותר וביותר ומעלין בקדש מזמן לזמן וכל המחשבות אודות נסיעה לכאן ברצוא ושוב וכו', הרי לע\"ע יסיחו דעתם מהם.</p>\n<p>בברכת הצלחה בלימוד התורה, בעבודת התפלה ובקיום המצות בהידור.</p>\n<p>נ.ב.</p>\n<p>מובן אשר כל הנ\"ל שייך גם לחבריהם, והנני ממלא את ידם לפרסם תוכן מכתבי זה בהכתות בם לומדים, ובודאי המשפיע הרה\"ח אי\"א נו\"נ מלאכתו מלאכת שמים בעל מדות ובעל מרץ מוה\"ר ניסן שי' נעמאנאוו יוכל להוסיף להם ביאור והסברה בכל הנ\"ל, כי אי אפשר לבאר פרטית הדברים בכתב.</p>\n<h4><i><b>ב'תשל</b></i></h4>\n<p>נדפסה בלקו\"ש ח\"י ע' 227, והושלמה ע\"פ העתק המזכירות.</p>\n<p><b> יסעו למרוקה:</b> תלמידים ממרוקו שלמדו בתו\"ת בצרפת ורצו לבוא ללמוד בישיבת תו\"ת בנ.י.</p>"],[1200830112,"ב'תשלא\n\n<p>ב\"ה, ט\"ז סיון, תשי\"ד</p><p>ברוקלין.</p><p>הנהלת ישיבת תומכי תמימים אשר בלוד, ד'<br>\nעליהם יחיו</p>\n<p> שלום וברכה!</p>\n<p>מעת כתבי מכתבי האחרון נתקבלו מכתביהם מיום כ' כ\"ד כ\"ו ניסן י\"ז כ\"ט אייר, ה' סיון והמצורפים אליהם, והנני לענות על ראשון וכו'.</p>\n<p>א) בטח במשך הזמן נתברר עוד יותר, עד כמה נחוץ להבטיח שלא יחסרו תלמידים בהישיבה בעתיד, ובפרט שעליית הנוער נתקטנה כ\"כ וכו'.</p>\n<p>ובמצב ההוה אפשר להבטיח את זה רק ע\"י קבלת תלמידים - אף כי בכתות נפרדות - מבלי הקפדה <b>יתירה</b>, אף שמובן מעצמו שצריך להזהר שלא יושפל עי\"ז שם הישיבה כו' וכו'.</p>\n<p>ב) מובן ג\"כ, שנוסף על הנ\"ל, וזוהי אחת הכוונות והמטרות דבתי ספר הרשת, שהתלמידים הקשישים בהם יוכלו לעבור ללוד.</p>\n<p>ג) בהמשך לזה, הנה יסוד סניפי תו\"ת בעוד ערים באה\"ק ת\"ו - אינני רואה בזה תועלת נוספת (מלבד שאלת ההוצאות, שהרי אי אפשר לאחוז בשני הקצוות, להודיע בכל מכתב ומכתב שמצב הכספי איום ונורא כו' וכו', ולאידך גיסא להרבות בהוצאות וכנ\"ל מבלי תועלת וצורך), ואם יש אפשריות לפתוח ישיבה בתור מכינה לישיבת תו\"ת בלוד, הרי יש להכניס זה בתכנית הרשת, <b>ומכמה</b> טעמים...</p>\n<p>ד) ובהמשך לזה, הנה גם בהשאלה ע\"ד קניית בניני הישיבה: אינם כותבים מאין יהי' מוצא לכסף, כיון שגם התקציב הרגיל קשה למלאותו וכו', כן אינם כותבים מהו נוהג שאר הישיבות בנדון זה, שבודאי חלק חשוב מהם לא קנו הבנינים אלא שכרום.</p>\n<p>ועוד, והוא העיקר - מה התועלת במה שיעברו הבנינים ממצב של שכירה למצב של קני'.</p>\n<p>ובטח יכתבו עד\"ז בהזדמנות הבאה...</p>"],[1200830113,"ב'תשלב\n\n<p>ב\"ה, י\"ז סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> ברכה ושלום!</p>\n<p>עס וואונדערט מיר וואס איך האב ניט געהערט פון אייך די גאנצע צייט, און איך וויל האפען אז דאס איז א גוטער סימן אז אלעס גייט כשורה, דאך וועל איך זיין צופרידען צו לייענען דאס פירוש אין אייערן א בריף, און השם יתברך זאל העלפען אז דאס זאל זיין אין דער מאקסימאלער מאס.</p>\n<p>זיכער איז איבעריג צו אויפמערקזאם מאכען אייך אז די פיהרונג פון א הויז בכלל און די באציהונג צווישן א מאן און פרוי ווענדעט זיך אין א גרעסער[ע] און מערערע מאס אן דער פרוי איידער אן דעם מאן, וואס דאס איז ווי דער אויסשפראך אין תנ\"ך: חכמת נשים בנתה ביתה, דער געבוי און אויפהאלט פון דער הויז, ווענדעט זיך דאס אן דער קלוגשאפט פון דער פרוי, און בפרט אין דעם אמעריקאנער לעבען וואס די ארבעט פון די מענער איז פארבונדען מיט פיל אנגעשטריינגקייט פון ניערווען און איילעניש, איז די פליכט פון דער פרוי נאך פיל מער צו זעהען אז עס זאל זיין צווישען זיי דער מאקסימום פון שלום דורך דער מאקסימום פארשטענדעניש פון דער פרוי.</p>\n<p>און אפילו ווען עס דוכט זיך און אפשר טיילווייס מיט רעכט אז דער מאן האט געקאנט זיין מער בעל מעלה, אבער נעמענדיק אין אכט אז אט דער שידוך איז שוין פון לאנג באשטימט געווארען פון השם יתברך, איז ווען מען זעהט א חסרון בא <b>זיך</b> איז ניט די עצה צו ווייטאגען זיך נאר מען זוכט וועגען וועלכע זיינען ניט פארבונדען מיט ווייטאג אויף צו פארריכטען דאס.</p>\n<p>אזוי אויך און נאך אין א גרעסער[ער] מאס דארף דאס זיין בנוגע צו מאן און פרוי, ווארום סוף כל סוף איז שווער צו וויסען וואס דער צווייטער לעבט איבער און די שוועריגקייטען וועלכע ער האט געהאט אין די פארגאנגענע יארען, איז ווען ער זעהט פון דער פרוי ווייכקייט און געפיל פון שטארקען בטחון בהשם יתברך, במילא קוקט מען אויף דער גאנצער וועלט אנדערש, און מען זעהט אז השם יתברך איז דער בעל הבית פון דער גאנצער וועלט און בפרט אויף איר אייגענער הויז און דעם ארום, וואס דאס גיט צו נאך מער גוטמוטיגקייט און פרייליכקייט, און מען זעהט דענסטמאל אליין אז עס האט זיך גוט געלויענט <b>פאר זיך אליין,</b> וויילע דאס בריינגט ווארימקייט און רוהיגקייט, פיל מער וויפיל עס האט געקאסט די אנשטריינגונג פון נאכגעבען און פארגעבען.</p>\n<p>האפענטליך אז בנוגע צו אייך און אייער מאן שיחיו דארפמען ניט די גאנצע באטראכטונג, און עס איז ווי עס דארף זיין א חסידישע הויז דורכגענומען מיט אהבת ישראל אויף וועלכעס רבותינו הק' האבען זיך מוסר נפש געווען צו זעהען דאס אין חסידישע הייזער בפרט, נאר אזוי ווי צו גוט איז דאך קיין שיעור ניטא, רעכין איך דעריבער אז די געשריבענע שורות וועלין ווירקען אז בא אייך זאל נאך מער און בעסער זיין די געמיינזאמע גוטע שלום און פארשטענדעניש באציהונג און וועלכער זאל זיך אויסשפרייטען אויך אין דער אומגעבונג אלס מוסטער פון שלום און ליכט. און השם יתברך זאל אייך באגליקען.</p>\n<p>בברכה.</p>"],[1200830114,"ב'תשלג\n\n<p>ב\"ה, י\"ז סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>... ובימים אלו דאחר קבלת התורה הנקראת תורת חיים ותורת עולם, שאחד הפירושים בזה זהו שמכניסה חיים גם בעניני עולם, הנה יה\"ר מהשי\"ת שכל אחד ואחד מאתנו יראה את זה בהד' אמות שלו ושל ב\"ב שיחיו ויראה את זה גם כפשוטו שיהי' להם א לעבעדיקער געזונטער פרייליכער זומער און א געזונטען פרייליכען תמיד.</p>\n<p>בברכה.</p>"],[1200830115,"ב'תשלד\n\n<p>ב\"ה, י\"ז סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>... בהנוגע לפועל, הרי מבואר בכ\"מ בדא\"ח שלאחר חטא עה\"ד כל הדברים והענינים מעורבים טו\"ר והעבודה ע\"פ דרך החסידות היא להתעסק בהגברת צד הטוב והאור, שלכן יכול להיות זה בשמחה רבה (משא\"כ בדרך המוסר שמדגישים הקו דסור מרע בעיקר שמביא לעצבות כו'), וגם ביחס לאנשים הרי צריך לנצל את הענינים הטובים והכשרונות שלהם ככל האפשרי, ואז אם בדרך ממילא או ע\"י השתדלות קלה הענינים הלא טובים מתבטלים.</p>\n<p>וה\"ה בנוגע לכ\"א המשתתף באחת העבודות במוסד כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע שעליו לתת את האפשרית לכל אחד משאר העובדים לנצל את כשרונותיהם לעוררם ולעודדם על זה אשר לאט לאט בטלים הענינים הבלתי רצויים אף אם היו מלפני זה.</p>\n<p>... והרי כבר כתבתי מאז שכר נרחב בכרם חב\"ד ודי להמציא לכ\"א סיפוקו בזה ובמה לנצל את הכשרונות שלו במילואם מבלי לנגוע בכבוד המדומה של חבירו ופשיטא שלא גם בכבוד האמיתי של חבירו, אלא שכלי מחזיק ברכה גם בכל הענינים הנ\"ל הוא השלום וקירוב הלבבות.</p>\n<p>מובן שלא באתי במכתבי זה להטיף מוסר אלא כ\"א לעורר ולעודד עוה\"פ אשר בכל או\"א... ישנם כחות גדולים שעדיין לא נצלו כלל... מפני טעמים של מה בכך, וכאשר כולם יטילו - אריינווארפען - עצמם במסירה ונתינה בעבודה קדושה זו הרי במשך זמן קצר מובטחני שיתמהו על עצמם איך זה לא ראו את הפשוט שעל ידי תוספת כח כולם <b>יחד</b> יכולים היו להגדיל ולהאדיר עבודת... כ\"פ ככה שבד\"מ הי' מתגדל ג\"כ הסיפוק נפשי והתקשרות באילנא דחיי וגם התוספת ברכה בעניני... ועניניהם הפרטים של כאו\"א וב\"ב שיחיו,</p>\n<p>ומובן - מעצמו שמופרך לגמרי להרחיק את מי שהוא מעבודה קדושה זו, כי מלבד הריחוק דבן ישראל מאילנא דחיי, הרי זה יביא היזק בעבודת... והאריכות בזה אך למותר...</p>\n<p>בברכה.</p>"],[1200830116,"ב'תשלה\n\n<p>ב\"ה, י\"ז סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> ברכה ושלום!</p>\n<p>זיינער צייט האב איך באקומען אייער בריף, און האב ביז יעצט ניט געענטפערט, וויסענדיג אז די טעג דארף זיין אין... הרה\"ג כו'... וואס מיט עם וועט איר קענען ריידען וועגען דער פראגע וואס איר שרייבט מיר, און איך האף אז איר וועט קענען צונויפריידין זיך אין א גוטען אופן, און אויך נעמענדיג אין חשבון, אז א ענדערונג אין די ארבעט באדינגונגען וועט ניט זיין קיין סוד, און מען דארף דאס ניט האלטען בסוד, און מען דארף אויך וויסען אז ס'וועט ענדערן אין א געוויסער מאס אויך די ארבעטס באדינגונגען פון די אנדערע מענשן, וואס דאס פארגרעסערט אין א גרויסער מאס די הוצאה.</p>\n<p>מיר איז שווער צו זאגען וואס אין דער פראגע - זייענדיק פון ווייטען, און איך האף און איך בין זיכער, אז אלע צוזאמען וועט איר זיך צוזאמענריידין און האפענטליך וועט דאס זיין גוט פאר אלעמען - און אויך פאר דער ארבעט.</p>\n<p>און זיכער איז איבעריג צו אויפמערקזאם מאכען אייך, אז יעדער ארבעט וועלכע איז פארבונדען מיט א מוסד פון מיין שווער כ\"ק אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע - גיט דאס ברכה והצלחה צו יעדער איינעם וועלכער נעמט איינטייל אין דעם, אויסער די שכירות וואס מען באקומט. און אפשר איז די ברכה והצלחה - נאך מער איידער די געלט וואס מען באקומט פאר דער. ארבעט.</p>\n<p>און השי\"ת זאל העלפען אייך, איר זאלט האבען א געזונטען פרייליכען לעבען צוזאמען מיט אייער מאן הרה\"ג וכו' שיחיו - און מגדל זיין אייערע קינדער שיחיו לתורה ולחופה ולמעשים טובים געזונטערהייט און פרייליכערהייט.</p>\n<p>בברכה,</p>\n<p><b>מ. שניאורסאהן</b></p>"],[1200830117,"ב'תשלו\n\n<p>ב\"ה, י\"ט סיון, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ג והרה\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמוה\"ר יהודא זאב שי'</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת המברק אודות הרה\"ח כו' מוה\"ר... מ\"ש אודות ההיתר להנ\"ל להתפלל וללמוד וכו' ומסיים שאולי יש להתיר ע\"י הרהור, הנה בנוגע ללימוד אפשר יש להסתפק בלימוד ע\"י הרהור כיון שזהו העיקר, משא\"כ בהנוגע לתפלה יש להשתדל למצוא לו היתר להתפלל גם בדבור ולסדר באופן המתאים את הכלים בחדרו וכו'*.</p>\n<p>... בטח יעניין את כת\"ר קטע שיחה המוסג\"פ וינהג בה טוב עין גם בנוגע לאחרים.</p>\n<p>בברכת הצלחה בעבודתו בקדש ובעניניו הפרטים.</p>\n<p>נתקבל המכ' מעש\"ק בהעלתך.</p>\n<h4><i><b>ב'תשלו</b></i></h4>\n<p><b> מוה\"ר יהודא זאב</b><b>:</b> סגל, אגרות נוספות אליו- לעיל ח\"ח ב'שכא, ובהנסמן בהערות שם.</p>\n<p><b> ההיתר להנ\"ל להתפלל</b><b>:</b> כשמ\"ר שותתין אצלו ע\"י כלי. בהמשך לזה - לקמן ב'תתה.</p>\n<p>*) אין מעניני לפס\"ד. ובכ\"ז אציין בזה איזה נקודות: א) יש לצדד שאין לזה דין מ\"ר, כיון שבאים ישר מכיס השתן (ע\"י קאטעטאר) ולא מהאבר, והספק אם <b>תיכף</b> ביצאם מן הכוליא דין מ\"ר להם. ב) גם מ\"ר (ואפילו שותת - מג\"א סו\"ס עו) הוי רק דרבנן ואין דוחה דאורייתא וגם לא תפלה ותפילין (מש\"ז ס\"פ). ג) המניעה מתפלה ות\"ת וכו' ודאי תפעול חלישות הדעת ובמילא גם חלישות הבריאות של החולה וכמה ענינים התירו מטעם זה (עיין חו\"מ סרנ\"ד).</p>"],[1200830118,"ב'תשלז\n\n<p>ב\"ה, כ' סיון, תשי\"ד</p><p>ברוקלין.</p><p>הנהלת הרשת באה\"ק ת\"ו, ד' עליהם יחיו</p>\n<p> שלום וברכה!</p>\n<p>... מובן שצריך לנצל את כל הכחות המתאימים בעבודת הרשת. ומה שכתבתי שיהיו המורים-ות מאנ\"ש הוא רק בהנוגע לדין קדימה וכמרז\"ל עניי עירך קודמין, ובפרט שעבודת הרשת דורשת לפעמים התמסרות יותר ע\"ד הרגיל שזהו בנקל יותר לדרוש ולתבוע ולקוות מאנ\"ש מאשר מאחרים. ומובן ג\"כ, שלאידך גיסא, חבל על כחות מתאימים של אנ\"ש שיעבדו בכרמים אחרים, ובפרט, אם יש מקום להרחבת פעולת הרשת, שהרי בעוד מועד צריך להכין העובדים המתאימים לזה ולא שברגע האחרון יצטרכו לחפשם, ובמילא יוכרחו לקחת מכל הבא לידם.... כנראה שמהסברא דסידור יום עיון למורים הרצאות וכו', לא יצא דבר, ואין צועקין על העבר ועכ\"פ עתה יסדרו כזה, ומה טוב שיהי' בפרסום המתאים וכו', והתועלת שבזה, הן כלפי פנים והן כלפי חוץ, אין צריכה באר...</p>\n<p>המחכה לאישור קבלת מכתבי זה בהקדם, ולפי האפשרי גם למענה עליו בהקדם, בברכת הצלחה בעבודתם בקדש.</p>"],[1200830119,"ב'תשלז*\n\n<p>ב\"ה, כ' סיון, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ כו'<br>\nמוהרנ\"ן שי'</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מט\"ז סיון וכן הקודם לו וע\"פ מרז\"ל אין מזרזין אלא למזורזין כו' הנני לעורר עוה\"פ ע\"ד ההכרח להגדיל הכמות ובמילא גם האיכות בימי הוואקאנס בכל השתדלות האפשרית, כי הרי סו\"ס מוכרח הדבר שיהי' באירופא עכ\"פ ישיבה אחת תו\"ת ואם לא בצרפת אינני רואה מקום לזה כמובן ובמילא צריך לראות שיהי' כמרז\"ל אלף נכנסים למקרא כו' שאז סו\"ס אחד יוצא להוראה וכמבואר הענינים ע\"פ דא\"ח בלקו\"ת לג' פרשיות בתחלתו. ובלי ספק אשר ככל שירבה מספר התלמידים בימי הוואקאנס כך תגדל האפשריות שירבה ג\"כ מספר אלו שישארו ללמוד בתמידיות.</p>\n<p>לפלא שבכל מכתביו אינו מזכיר ע\"ד השתדלות אודות הוויזה שלו.</p>\n<p>המכתב לתלמידי הספרדים בטח יבאר אותו באותיות המתאימות להם ובתוספת נופך משלו והשי\"ת יצליחו.</p>\n<p>גם ע\"ד בריאותו אינו מזכיר דבר ויה\"ר שיהי' זה ראי' והוכחה שהכל שלום.</p>\n<p>בברכת הצלחה בעבודתו בקדש.</p>\n<h4><i><b>ב'תשלז*</b></i></h4>\n<p><b> מוהרנ\"ן:</b> מוה\"ר ניסן נמנוב. אגרות נוספות אליו -לעיל ב'תרמא, ובהנסמן בהערות שם.</p>\n<p><b> להגדיל הכמות</b><b>:</b> ראה גם לעיל שם.</p>\n<p><b> המכתב לתלמידי הספרדים</b><b>:</b> דלעיל ב'תשל.</p>"],[1200830120,"ב'תשלח\n\n<p>ב\"ה, כ\"א סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>... נבהלתי לקרות במכתבו האחרון אשר יש אצלו סברא שתסע זוגתו תחי' באני' ישראלית ושכל המלחים הם בני ישראל וכו' הנוסעת בים ביום הש\"ק, ולכן שלחתי לו מברק בקבלת מכתבו, וז\"ל: תמיהני להסברא לנסוע באני' ישראלית הנוסעת בשבת קדש, ובודאי יתקן, בברכה: חתימתי.</p>\n<p>אינני יודע פרטי ההנהגה בספינות כאלו, אבל לאידך גיסא אינני רואה מקום להיתר, ועד כדי כך שגם על הקס\"ד בזה תמה אני. ואולי יעלה בידו לתקן הדבר בעוד מועד, כי בא\"ל ח\"ו צריך להתייעץ על דבר תיקון בענין כזה הקשור בקדושת השבת וקדושת השם. והשי\"ת יצליחו לבשר טוב בזה...</p>\n<p>בברכת הצלחה בעבודתו בקדש. המחכה לבשו\"ט בכל הנ\"ל.</p>\n<h4><i><b>ב'תשלח</b></i></h4>\n<p><b> באני' ישראלית</b><b>:</b> ראה גם לעיל ח\"ז אגרת ב'רכא, ובהנסמן בהערות שם. לקמן ב'תשנג.</p>"],[1200830121,"ב'תשלט\n\n<p>ב\"ה, כ\"א סיון, תשי\"ד</p><p>ברוקלין.</p><p>הנהלת אגודת חסידי חב\"ד באה\"ק ת\"ו<br>\nד' עליהם יחיו</p>\n<p> שלום וברכה!</p>\n<p>... כתבתי מכבר בשאלת מצב בתי כנסיות חב\"ד באה\"ק ת\"ו ומהנעשה אתם... ועל של עתה באתי, אשר אם כבר יש אצלם ידיעות בזה כדאי להודיע בעוד מועד, כיון שזה נוגע בפרט לי\"ב תמוז הבע\"ל, שזהו היומא דפגרא היחידי במשך השנה ששייך ביחוד לחב\"ד (כי אפי' י\"ט כסלו, הרי ישנם גם מחסידי פולין שחוגגים אותו), ולכן יש לנצלו בכרם חב\"ד ביחוד, ע\"י פרסום הראוי בזמן המתאים מקודם, ומובן שבזה הרי יש לנצל האפשריות דבתכ\"נ חב\"ד. והוא נוסף על השאלה העיקרית, שמוכרח לשמור על צורתם דבתכ\"נ אלו ולפתחם, היינו להוסיף השפעתם על הסביבה וגם על בתי מתפללי בית הכנסת, שבמדה גדולה תלוי זה בהנהלת הבית הכנסת והרב או המגיד שיעור שלהם.</p>\n<p>ולכן עם הידיעה כללית צריך להיות ג\"כ ידיעה במהות אנשים הנ\"ל. ואחכה לידיעות מפורטות, וכן להצעה מצדם אודות הפעולות דאג\"ח האפשריות בבתכ\"נ אלו, בקשר עם הנ\"ל.</p>\n<p>ג) בתמהון נודעתי, אשר זה לא כבר הביאו מאה\"ק ת\"ו ללונדון וכן לכאן כמה ביכלעך דא\"ח למכירה. ולפלא גדול, שאו שלא נודע להם כלל עד\"ז או שנודע ולא שמו לב - כי הרי יש מקום לומר, שעל אתר באה\"ק ת\"ו הי' אפשר לקנות ביכלעך הנ\"ל בזול יותר, והעיקר לשמרם שלא יפלו בידי זרים (בענין זה, ומי יודע אולי גם זרים כפשוטו), ואין צועקין על העבר, ועכ\"פ באתי בהתעוררות על להבא. ותמיהתי גדולה עוד יותר, שלמרות שזה איזה <b>שנים</b> שבקשתי לפרסם ולבקש ולחפש אחרי ביכלעך דא\"ח ולשלחם לכאן, ואם אי אפשר אחרת הרי ע\"מ להחזיר, ובמשך כל <b>השנים</b> האלו, הנה רק מאחד נתקבלו איזה ביכלעך בתור חילוף...</p>\n<p>ד) בהמשך להנ\"ל - הנה נודע לי, אשר אצל נכדי הרה\"צ והרה\"ח וכו' מוהרש\"נ ע\"ה מבאברויסק נמצאים כמה ביכלעך - בדא\"ח, ואולי גם בנגלה - של נשיאינו היינו הצ\"צ ובניו וי\"א אשר גם מאדמוה\"ז ואדמוהאמ\"צ. מאלו שסיפרו לי לא יכולתי לברר אם זהו גוף כתי\"ק או העתקה, אבל בכ\"א נא ונא לבקר את הנ\"ל (אינני יודע ברור אצל מי מהנכדים נמצא הנ\"ל) ולבקשם בשמי, להרשות לאחד האברכים לעשות תוכן מביכלעך אלו ע\"מ לשלחו לי, ואם יהי' בהם ענינים כאלו שאינם נמצאים תחת ידי, ובפרט מהשייכים להענינים ההולכים ונדפסים, שאוכל לקבל הביכלעך הנ\"ל, עכ\"פ בהלואה למשך זמן. ובקשה זו כוללת ג\"כ דא\"ח מהרי\"א עפשטיין מהאמיל ומהר\"ה מפאריטש זצללה\"ה...</p>\n<p>בברכת הצלחה - המחכה לבשו\"ט בכל הנ\"ל.</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ב'תשלט</b></i></h4>\n<p><b> כתבתי מכבר:</b> לעיל ח\"ח ב'תקס.</p>"],[1200830122,"ב'תשמ\n\n<p>ב\"ה, כ\"ב סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על הודעתו מיום הולדת שלו. ולפלא שאינו מזכיר דבר מהקביעות עתים שלו ומשיעוריו בתורת הנגלה ותורת החסידות נוסף על שמירת שלשת השיעורים השוים לכל נפש מתקנת כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע בחומש תהלים ותניא הידועים, ווארום דאס מיינט מען דאך יעדערערן פון אונז ובמילא גם אותו, ואי אפשר לצאת ידי חובתו במה שאחר לומד ושומר את השיעורים. וכבר כמה פעמים אמרתי לו אודות הנ\"ל בהוספה שכפי שרואים גם בעיני בשר הרי בימינו אלה הרי זה נוגע גם בהצלחה בגשמיות ובהסתדרות. ויתן השי\"ת ושנה הבאה תהי' שנת הצלחה בכל הנ\"ל ובהסתדרות לטוב לפניו בגשמיות וברוחניות גם יחד.</p>\n<p>בברכה.</p>"],[1200830123,"ב'תשמא\n\n<p>ב\"ה, כ\"ב סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על הודעתו מיום הולדת שלו. הנה בטח ידוע לו מהנהוג בין האברכים החסידים הנהגות יום זה, והשי\"ת יצליחו שאף ששנה בישיבת כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע ופירש הימנה, יסייעוהו מן השמים לחזור ולהתקשר באילנא דחיי הוא מוסד והנהגה שהוקבעה מנשיאנו עד ועד בכלל הוא כ\"ק מו\"ח אדמו\"ר ויהי' זה בחסד וברחמים ויזכה במשך הזמן למלאות מה שהחסיר בלימוד התורה וביראת שמים, ולבשר טובות בזה.</p>\n<p>בברכה,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>\n<h4><i><b>ב'תשמא</b></i></h4>\n<p><b> הנהגות יום זה</b><b>:</b> ראה גם לעיל אגרת ב'עתר, ובהנסמן בהערות שם.</p>"],[1200830124,"ב'תשמב\n\n<p>ב\"ה, כ\"ד סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>נתקבל מכתבו מכ' סיון וכבקשתו אזכירו על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע לרפו\"ק. ולפלא שמזכיר במכתבו שהוא מרוגז ועצביו מתוחים וכו' בה בשעה שבודאי ידועים לו עיקרי שיטת הבעש\"ט ונשיאי חב\"ד אשר כל פרטי פרטים בעולם ובפרט בחיי האדם הישראלי ה\"ז בהשגחה פרטית מהשי\"ת שהוא עצם הטוב וכבר ידוע פס\"ד בתניא קדישא אגה\"ק פרק כ\"ב שבהתבוננו בזה וכו' הרי אז גם ה' יתן הטוב ויאר פניו אליו בבחי' אהבה מגולה ויתמתקו כו' ויתבטלו כו' והשי\"ת יזכהו לבשר טוב בקרוב.</p>\n<p>בברכה לבריאות.</p>"],[1200830125,"ב'תשמג\n\n<p>ב\"ה, כ\"ד סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>... כפי שאמר לי... הנה אביו למד בליובאוויטש והרי ידוע פס\"ד המשנה שהאב זוכה לבן בחכמה שהיא הסברא הישרה וכמבואר במפרשי המשנה שם, ואין לך סברא ישרה מזו, להכיר בההכרח הגמור בדורותנו אלה ללמוד זאת החכמה (עיין אגרת הקדש לרבנו הזקן דף קמ\"ב ע\"ב) שזה משפיע על כל מעמד ומצב האדם ובפרט של אלו שהוריהם כבר נכנסו בכרם פנימיות התורה שאז ציווי רז\"ל (שבת ל\"א סוף ע\"א) אם יראת ד' אוצרו הן א\"ל כו' הוא בהחלט ובהקדם והשי\"ת יזכהו להיות ג\"כ צנור אשר על ידו יתפשט לימוד זה גם בחביריו וסביבתו.</p>\n<p>בברכת מזל טוב מזל טוב.</p>"],[1200830126,"ב'תשדמ\n\n<p>ב\"ה, כ\"ד סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מי\"ט סיון... כנראה אשר ענין נשי ובנות חב\"ד נשתקע כו', ולפלא אשר לאחר כל אשר ראו בהשגחה פרטית כנראה עדיין לא חדרה ההכרה לפנימיותם אשר אין זהו רק ענין של תעמולה כלפי חוץ אלא <b>שבעיקר</b> נוגע לנשי ובנות חב\"ד ולביתם ולא רק בענינים של הידור לחוד, ואין הדבר דומה להמצב כשהי' במדינתנו לפנים שאז היתה הברירה רק בשתי הקצוות או במס\"נ לצד ימין או הפקירות לצד שמאל לגמרי משא\"כ בהמצב עתה וד\"ל. וכיון שנשים דעתם קלה הרי ביותר יש לתבוע לארגן זה מהאנשים ויה\"ר שיקויים והוא ימשול בך במילי דשמיא שזה יבוא לאחרי שהענין יהי' נוגע להם כמו שצ\"ל נוגע. מובן שכל הנ\"ל כתוב לכל אנ\"ש והרשות בידו וגם הזכות לפרסם באופן המתאים.</p>\n<p>בברכה.</p>\n<p>נ.ב.</p>\n<p>ע\"ד הקבלות בטח יסודר מהמשרדים.</p>"],[1200830127,"ב'תשמה\n\n<p>ב\"ה, כ\"ד סיון, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמוה\"ר אברהם חיים שי'</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מח' סיון ואח\"כ גם הספר תשובות בית הלל. והשי\"ת יצליחו למלאות חלקו ותפקידו בהגדלת תורה והאדרתה התלוים בהחזקת יראת שמים טהורה וכמרז\"ל (שבת ל\"א סוף ע\"א) שכשיראת ד' היא אוצרו הרי אז מתקיים אמונת עתך חוסן ישועות חכמת ודעת, ושבימינו אלה אי אפשר לזה אלא בקיום ציווי האריז\"ל (עיין אגרת הקדש לרבנו הזקן בעל התניא - פוסק בנסתר דתורה - והשו\"ע - פוסק בנגלה דתורה) - שבדורותנו אלה מותר <b>ומצוה</b> לגלות זאת החכמה, ועיין בארוכה בהקדמת תלמידו הרח\"ו משער ההקדמות שהאריך בזה בביטוים נוראים ומבהילים.</p>\n<p>וידוע ג\"כ פסק השו\"ע (או\"ח ריש סי' צ\"ח) שקודם התפלה צריך לחשוב מרוממות הא-ל יתעלה כו' והרי מובן ופשוט שא\"א לחשוב עד\"ז מבלי ידיעה בזה, והאריכות בזה אך למותר, ומה גדול ההעלם וההסתר אשר אף שכל הנ\"ל מובן בפשטות נצרך להסביר הכרח לימוד זה.</p>\n<p>מוסג\"פ סקריפ להוצאות הפרטית והשי\"ת יצליחו.</p>\n<p>בברכה.</p>\n<p>נ.ב.</p>\n<p>מה שהעתיק במכתבו בענין הוי' הוי' וכו'. הנה לא ביאר הענינים כל צרכם. א) בדברי הרא\"ש כיון שמחשבת ע\"ז מצטרפת הרי אין זה <b>קודם</b> שחטא. ב) בהפירוש דה' אחד שמסביר שלא יהיו צריכים רק לשם אחד. הנה איך אפשר לומר שלע\"ל לא יהיו י\"ג תיקוני דיקנא שהן י\"ג מדות הרחמים שלדעת כמה מהראשונים מתחילים משם הוי' הראשון ואדרבה מדויק הוא דוקא מל' רז\"ל אני הוא קודם שיחטא. וההסבר בזה הוא בקיצור. א) עפמ\"ש בתניא פרק ט\"ז בדיוק הלשון מצרפה והול\"ל מעלה עליו כאילו עשאה, ועיין שם בקרבן נתנאל. ב) אין הענין שיבוטל ח\"ו שם הוי' אחד משני שמות הוי' אלא המדובר הוא בהפסיק טעמי שביניהם שלע\"ל יהי' הוי' אחד שני השמות באחדות.</p>\n<p>יעוין זח\"ג קלח, א. לקו\"ת דנט\"א.</p>\n<h4><i><b>ב'תשמה</b></i></h4>\n<p><b> מוה\"ר אברהם חיים</b><b>:</b> לוינזון, ירושת\"ו.</p>\n<p><b> שהעתיק במכתבו</b><b>:</b> בספר של הגה\"ק כחד מקמייא מרן ממונקאטש זי\"ע בשם הגה\"ק רמ\"ל סאסובער זי\"ע כי ארז\"ל במסכת ר\"ה י\"ז בי\"ג מדות ה' ה' אני ה' קדם שיחטא האדם, וה' לאחר שיחטא האדם, והקשה הרא\"ש שם מה צריך למדת הרחמים קדם שיחטא? ותירץ דמיירי במחשבת ע\"ז שהו קדם שחטא האדם עדיין ואף שאין המחשבה רעה מצטרפת למעשה, אבל בע\"ז מצטרפת שנאמר למען תפוש את בנ\"י בלבם, עכ\"ד הרא\"ש ז\"ל, ולפי\"ז צריכין ב' שמות רק בשביל ע\"ז ולעתיד בב\"א יהיה להעביר גלולים מן הארץ והאלילים כרות יכרתון ולא יהי עוד מחשבת ע\"ז כלל על כן באמת לא יהיו צריכין לב' שמות רק לשם אחד - מדת הרחמים בכללותה שא\"א בלעדה - השי\"ת יזכנו בקרוב שיהיה ה' אחד ע\"י משיח ה' מדברנא דאומתי' במהרה דידן כי\"ה.</p>"],[1200830128,"ב'תשמו\n\n<p>ב\"ה, כ\"ד סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>... בודאי עוסק בעניני פרנסתו ככל הצריך כי הרי לפרנס את ב\"ב וגם את עצמו זוהי מצות הבורא ית' ובמילא צריך לעשות בזה באמונה, ניט נאר פון יוצא וועגען אליין, ועאכו\"כ לא לחפוץ לרמות את הציווי וברכך ה\"א בכל אשר <b>תעשה</b> ומובן שצריך להיות זה בלא דאגה ובהלא השתקע בזה אבל לאידך גיסא שלא חסר המעשה בפועל והשי\"ת יצליחו.</p>\n<h4><i><b>ב'תשמו</b></i></h4>\n<p>לתוכנה ראה גם לקמן אגרת ב'תשנ.</p>"],[1200830129,"ב'תשמז\n\n<p>ב\"ה, כ\"ו סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>... מ\"ש שלא ראה לנחוץ לחקור אחרי אופן גירות אחדות שבעיר הנ\"ל הנה באופן דיפלומטי ולאט ולאט ובמניעה מחשש של ביוש ברבים, יש לחקור עד\"ז כיון שאם יודע שצריך איזה תיקון הרי יש לקוות שבקל יוכל לפעול אצל הנשים שיתקנו הענינים כיון שקרוב לודאי שהתיקון אינו כרוך באופנים של מס\"נ ואפי' באופנים של מס\"נ לפי השקפתם הם. וחזקה לתעמולה שאינה חוזרת ריקם, והשי\"ת יצליחו שהשתדלות בכל הנ\"ל תביא פירות לאלתר ויראה פרי טוב בעמלו הן בגשמיות והן ברוחניות. וישתמש בהאוטו החדש אשר קנה להוסיף אומץ בכל הנ\"ל ומובטח השי\"ת לקיים הבטחתו אשר כל המוסיף מוסיפין לו שהפירוש בזה לו ולכל ב\"ב שיחיו.</p>\n<p>בברכת הצלחה.</p>"],[1200830130,"ב'תשמח\n\n<p>ב\"ה, כ\"ו סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מי\"ד סיון, ובו שאלה אודות בנו... שי' שאינו שוקד בלימודו כו' ושואל חוו\"ד בזה.</p>\n<p>הנה אינני רואה מקום לשאלה וכבר ידוע פסק רז\"ל עד דידך על צוורי דבריך כו' שזה מתחיל משנת הששה עשר שזהו גיל בנו שי' שכותב במכתבו ובמילא עליו הדבר מוטל לנקוט בהאמצעים ודרכי נועם שבו ילמוד במסירה ונתינה אליבא דנפשי' ואז יצליח.</p>\n<p>מ\"ש אודות עניני הישיבה, הנה לפלא עליו שכיון שגם הוא מהר\"מ והמשגיחים דהישיבה הרי גם עליו מוטלת האחריות בעד ההנהלה בכללותה וכמו בכל עניני צבור שאין הפירוש בזה דהיחיד פטור מהם וכידוע, וכל אחד מהר\"מ והמשגיחים שעוסק במקצועו במסירה ואליבא דאמת הרי א\"א שלא יפעול זה גם על שאר הנהלת הישיבה ואופן העבודה דשאר הר\"מ והמשגיחים וכל הנ\"ל הוא נוסף על הפס\"ד (קידושין מ, ב והובא ברמב\"ם) דלעולם יראה אדם עצמו שקול כו' ובפעולה אחת שלו מכריע את עצמו ואת כל העולם כולו לכף זכות או כו' ואחכה למכתבו מפורט מאשר מוסיף הוא בהענינים שתחת רשותו ומוסיף ככל האפשרי וכן הצעות מפורטות בהנוגע להטבת המצב בהענינים והמקצועות שתחת הנהלת אחרים, ומובן שכל המפרט יותר ה\"ז משובח.</p>\n<p>בברכה.</p>"],[1200830131,"ב'תשמט\n\n<p>ב\"ה, כ\"ו סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על שאלתו, בו שואל אם יסעו הוריו ממקומם עתה להסתדר בקבוץ חפשי באה\"ק ת\"ו, ופלא בעיני גם על הקס\"ד בזה, ויעיין היטב בלשון הרמב\"ם הלכות דיעות ריש פרק ו', צריך אדם להתחבר ולישב אצל החכמים כו' ויתרחק מן הרשעים כו' ילך למקום שאנשי' צדיקים כו' ואם הם רעים וחטאים כו' יצא למערות ולחוחים ולמדבריות, ועאכו\"כ שהנמצא במקום שמנהגי' הוא ע\"פ התורה והמצוה שאי אפשר לחשוב ע\"ד העתקה לקבוץ חפשי, והשומר את עמו ישראל בכל עת ובכל מקום אשר לא ינום כו' ישמור את הוריו בתוך כל ישראל ודוקא בסביבה של יראת שמים תורה ומצוה אשר שם שכינתא שריא, והוא מצדו יכול להוסיף בזה ע\"י הוספה בשקידה מסירה ונתינה בלימוד התורה הנגלית ותורת החסידות וקיום המצות בהידור מיוסדים כל הנ\"ל על יראת שמים טהורה.</p>\n<p>בברכה,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>"],[1200830132,"ב'תשנ\n\n<p>ב\"ה, כ\"ז סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מא' קרח בו כותב אודות ג' סוגים בהשגת טרף לבית. הרי כבר ידוע הוראת רז\"ל השוה לכל נפש (מלבד יחידי סגולה) שצריך לעשות כלי לקבלת הברכה וכמאמר הכתוב וברכך ה\"א בכל אשר <b>תעשה</b>, וכמבואר ג\"כ טעם הדבר בכ\"מ בתורת החסידות ומהם בלקו\"ת לרבנו הזקן בעל התניא (פוסק בנסתר דתורה) והשו\"ע (פוסק בנגלה דתורה) פרשת תצא דף ל\"ז סוף ע\"ב.</p>\n<p>אף שקשין מזונותיו של אדם כקרי\"ס שזהו אחד <b>הנסים</b> הכי גדולים בכ\"ז בחיצונית צריך לעשות כלי ג\"כ בדרכי הטבע וכמבואר בלקו\"ת שם, אלא שכדי להגדיל ברכות השי\"ת צריך להיות חזק בבטחון ולהוסיף אומץ בלימוד תורת הנגלה ותורת החסידות וקיום המצות בהידור שהן הן הצנור והכלים להמשכת וקבלת ברכות השי\"ת בהמצטרך.</p>\n<p>והשי\"ת יצליחו.</p>\n<p>בברכה,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>\n<h4><i><b>ב'תשנ</b></i></h4>\n<p><b> הוראת רז</b><b>\"</b><b>ל</b><b>:</b> ראה גם לעיל אגרת ב'תשמו.</p>"],[1200830133,"ב'תשנא\n\n<p>ב\"ה, כ\"ז סיון, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמוה\"ר צבי הירש שי'</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מעש\"ק קרח ובו שאלה אם כדאי להעתיק את הענינים השונים גם לשפה אחרת מלבד צרפתית.</p>\n<p>א) הנה אם רק ישנם קוראים מבין בני שיראל בשפה איזה שתהי' כדאי להעתיק עניני דא\"ח בהשפה ההיא כי ה\"ז בכלל הענין דיפוצו מעיינותיך חוצה...</p>\n<p>ג) במ\"ש אודות השתדלות השגת נתינות צרפת, צריך מקודם לברר אולי ישנה אפשרית לקבלת נתינות שווייץ שמכמה טעמים טובה יותר ורק אם יתברר שזה אי אפשר או קשור בקישויים גדולים למדי, אזי יש להשתדל בהנתינות הצרפתית.</p>\n<p>בברכת הצלחה בעבודתו בקדש ובעניניו הפרטים.</p>\n<h4><i><b>ב'תשנא</b></i></h4>\n<p><b> מוה\"ר צבי הירש שי':</b> צאלער, אגרת נוספת אליו -לעיל ח\"ה א'ש.</p>"],[1200830134,"ב'תשנב\n\n<p>ב\"ה, כ\"ז סיון, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמוה\"ר מנחם נחום יצחק אייזיק שי'</p>\n<p> שלום וברכה!</p>\n<p>נעם לי לקבל מכתבו מכ\"א סיון, בו מבשר טוב אשר בתו שטערנא פריידא ילדה בן למזל טוב, ויה\"ר שהוריו שיחיו יכניסוהו לבריתו של אברהם אבינו בשעה טובה ומוצלחת וכשם שיכניסוהו לברית כן יכניסוהו לתורה ולחופה ולמעשים טובים, ועיני כבודו שי' רואות ורוות מהם ומכל יו\"ח שי' רוב נחת חסידותי מתוך בריאות הנכונה והרחבת הדעת ויוכל לבשר טוב גם בשאר הענינים שמזכיר אודותם במכתבו ושאזכיר על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע.</p>\n<p>ומ\"ש שאלת עצה כיצד לקרות שם לילד הנולד שי'.</p>\n<p>הרי ידוע מענה כ\"ק מו\"ח אדמו\"ר בכגון דא שאינו מתערב בענינים אלו והוא מובן ע\"פ מ\"ש בכתבי האר\"י ז\"ל (בשער הגלגולים הק' כג. וראה עמה\"מ ש\"א ספ\"ד) הובא גם באו\"ת ס\"פ בראשית (ובלק\"א להה\"מ) אשר מלמעלה ניתן לההורים הרעיון איך לכוון לשם הבן או בת הנולדים, שם השייך לנשמה זו, וכמבואר בכ\"מ בדא\"ח וראה ג\"כ לקו\"ת בהר (מא, ג) אשר אותיות השם שייכים לחיות הנשמה והגוף.</p>\n<p>בברכת מז\"ט.</p>\n<h4><i><b>ב'תשנב</b></i></h4>\n<p>נדפסה בלקו\"ש חי\"ב ע' 182, והושלמה ע\"פ העתק המזכירות.</p>\n<p><b> מוה\"ר מנחם נחום יצחק אייזיק:</b> חנון.</p>\n<p><b> ידוע מענה</b><b>:</b> ראה גם לעיל ח\"ו אגרת ב'ד, ובהנסמן בהערות שם.</p>"],[1200830135,"ב'תשנג\n\n<p>ב\"ה, כ\"ח סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>מ\"ש אודות האני'. הנה ה\"ז ענין שבעלי' ישראלים במילא גם אם העובדים שם אינם יהודים וכיון שנעשה בפרסום גדול כ\"כ צע\"ג דאפשר הוא איסור דאורייתא או דרבנן עאכו\"כ שהעובדים הם ישראלים, ומ\"ש שאמרו שהכל נעשה אוטאמאטיש הנה בודאי אי אפשר הדבר וכידוע להשייכים למקצוע זה, והאריכות בדבר המכאיב אינה רצוי' ולפלא גם בהביא בחשבון העלמות והסתרים דעקבתא דמשיחא על שגם דבר פשוט כזה הרי כמה מהיראים וחרדים אינם שמים לב וד\"ל.</p>\n<p>בברכת הצלחה בעבודתו בקדש.</p>\n<h4><i><b>ב'תשנג</b></i></h4>\n<p><b> מ\"ש אודות האני</b><b>':</b> ראה לעיל אגרת ב'תשלח, ובהנסמן בהערות שם.</p>"],[1200830136,"ב'תשנד\n\n<p>ב\"ה, כ\"ח סיון, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ בנש\"ק רב פעלים<br>\nמוה\"ר מתתי' יחזקאל שי'</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלתי ספרו ענג שבת בשני טופסים נכרך ביחד עם ספר בכורי יחזקאל על מס' אבות, ובסופו ג\"כ דברי חסידות מלוקטים משיחות כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע (וחבל שלא הורה המקור למען יוכל הקורא לעיין על אתר שע\"פ הרוב נמצא שם גם איזה ביאור נוסף) והשי\"ת יצליחו למלאות חלקו בהפצת אור התורה ומאור שבתורה בסביבתו ובתוך מושפעיו מתוך הרחבת הדעת.</p>\n<p>בברכה.</p>\n<p><i>ב'תשנד</i></p>\n<p><b> מוה\"ר מתתי' יחזקאל:</b> גוטמן. אגרות נוספות אליו - לעיל ח\"ח ב'שטו, ובהנסמן בהערות שם.</p>"],[1200830137,"ב'תשנה\n\n<p>ב\"ה, כ\"ח סיון, תשי\"ד</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ עוסק בצ\"צ מוה\"ר יצחק<br>\nאוחנה שי'</p>\n<p> שלום וברכה!</p>\n<p>נעם לי לקבל פ\"ש ממנו ע\"י הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ מוה\"ר מיכאל שי' ליפסקר והמבאר ג\"כ אשר כבודו משתדל במרץ לקרב את לבם של ילדי בני שראל לאבינו שבשמים, ובודאי למותר לעורר אשר אם המקיים נפש אחת מישראל כאילו קיים עולם מלא ואם בחיי עוה\"ז כן, הרי עאכו\"כ המקיים נפשות כו\"כ מבני ישראל ומביאם לחיי העולם הבא הנצחי ע\"י קירוב לבם להוי' אחד, הרי גודל פעולתו ושכרו אין די באר. והכרה זו עצמה שממלאים שליחות קדושה של הקב\"ה מוסיפה כח ואומץ במילוי תפקיד קדוש זה אשר מציאות האומץ עצמה ממעטה ההתנגדות של הצד שכנגד וכמובן ג\"כ ע\"פ המבואר בספר תניא קדישא מרבנו הזקן בעל התניא (פוסק בנסתר דתורה) והשולחן ערוך (פוסק בנגלה דתורה) סוף פרק כ\"ט ומדתו של הקב\"ה מדה כנגד מדה אבל כ\"פ ככה לתוספת נחת אמיתי מכל יו\"ח שיחיו.</p>\n<p>בברכת הצלחה בעבודה בחינוך על טהרת הקדש.</p>"],[1200830138,"ב'תשנו\n\n<p>ב\"ה, כ\"ט סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מי\"ט סיון, בו כותב אודות העלמות והסתרים השונים שישנם אצלו ומפרטם לסעיפים. הנה כל הסעיפים שחושב - מקור אחד להם, והוא הסתת הצד דלעומת זה, שמפריע את האדם בכל הדרכים, למנוע את האדם מעבודתו את בוראו, וכיון שהסיבה אחת היא, הרי יש לתקן על ידי שינוי עיקרי אחד, והוא - המסירה והנתינה ללימוד תורת הנגלה ותורת החסידות, מבלי כל תירוצים. וכשיחליט באמת אליבא דנפשי' לעשות כזה, ויכיר את האמת שזה נוגע לכל מעמדו ומצבו בחיים, ולא רק בענינים הרוחנים אלא גם בחיים הגשמיים, הרי רואים הצלחת השי\"ת. וכבר ידוע הפס\"ד שאפילו מעט אור דוחה הרבה חשך. אלא שכדי להרבות בסייעתא דשמיא, צריך לשמור שלשת השיעורים השוים לכל נפש מתקנת כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע (בחומש תהלים ותניא) הידועים. ולהוסיף בצדקה עם הזולת, היינו לקרבו לתורת השם ולעבודתו, שצדקה גם ברוחניות - תרומם גוי, וכמבואר בתורה אור לרבנו הזקן בתחלתו.</p>\n<p>המורם מהנ\"ל, ילמוד בשקידה במסירה ונתינה בנגלה דתורה ובתורת החסידות, יוסיף אומץ בעבודת התפלה ובקיום המצות בהידור, ולהשפיע על הזולת לקרבם לאילנא דחיי, שאז יקוים היעוד - לאט לאט אגרשנו. ויוכל לבשר טוב בכל הענינים שנגע במכתבו.</p>\n<p>בברכה,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר: א. קווינט</p>\n<h4><i><b>ב'תשנו</b></i></h4>\n<p>נדפסה בלקו\"ש חט\"ז ע' 568, והוגהה ע\"פ צילום האגרת.</p>"],[1200830139,"ב'תשנז\n\n<p>ב\"ה, כ\"ט סיון, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ג והרה\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמוה\"ר אפרים אליעזר שי' הכהן</p>\n<p> שלום וברכה!</p>\n<p>כיוון כת\"ר את השעה ונתקבל מכתבו כשעה לפני נסעי על אהל כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע ודבר בעתו מה טוב, והזכרתיו ואת כל ב\"ב שיחיו וכפי שכותב במכתבו.</p>\n<p>ובחודש גאולה זה אשר מיוסד על מרז\"ל הידוע לאחר פטירתו כו' בתר רישא גופא אזיל (ערובין מ\"א א) - ולהעיר מסוטה מ\"ה ב. - נדבר בהתועדות דש\"ק מברכין העבר, אשר כשצריכים להוציא אדם מבית השבי, מושכין אותו ועולה תחלה ונגאל הראש ובתר רישא גופא אזיל. וה\"ה בגאולת כ\"ק מו\"ח אדמו\"ר ראש ונשיא ישראל, יה\"ר שבקרוב ממש בתרי' גופא אזיל, שגם העקביים בכלל (יעוין נזיר נ\"א א. ושו\"ת צפנת פענח להגאון מרגצוב ח\"א, לד), בכלל זה בגאולה אמיתית והשלימה.</p>\n<p>בברכה.</p>\n<h4><i><b>ב'תשנז</b></i></h4>\n<p>נדפסה בלקו\"ש ח\"ח ע' 332, והושלמה ע\"פ העתק המזכירות.</p>\n<p>מוה\"ר אפרים אליעזר שי': יאלעס. אגרות נוספות אליו - לעיל ב'תשי, ובהנסמן בהערות שם.</p>\n<p><b> נדבר בהתועדות:</b> ראה גם לקמן אגרות ב'תשעח. ב'תשצב.</p>"],[1200830140,"ב'תשנח\n\n<p>ב\"ה, כ\"ט סיון, תשי\"ד</p><p>ברוקלין.</p><p>מתפללי בית הכנסת בית יוסף</p>\n<p>אשר בירושלים עיה\"ק ת\"ו</p>\n<p>ד' עליהם יחיו</p>\n<p>שלום רב וברכה!</p>\n<p>בנועם קבלתי המכתב בו כותבים אודות חגיגת יום השנה שלהם וכן ההתועדות בהימים שלאחר זה ובהם בחג השבועות זמן מתן תורתנו. וביחוד נהניתי לקרות בהמכתב אודות השיעורים הנלמדים הן בתורת הנגלה והן בתורת החסידות.</p>\n<p>וחפץ ה' בידם יצליח אשר יהי' ביתם בית תפלה ובית לימוד וכדרז\"ל על הכתוב אוהב ה' שערי ציון מכל משכנות יעקב, ושמא מילתא הוא בית יוסף, יוסף ה' לי בן אחר וביארו בתורת דא\"ח אשר מאחר עושים בן כאשר מהפך מחשוכא לנהורא והוא ע\"י התבוננות הנפש השכלית בגדולת ה' כו' עד שגם נה\"ב מסכימה ע\"ז נעשה יתרון האור מן החשך יתרון ממש כשהחשך נהפך לאור כו' שעי\"ז נמשך תוספת אור לאין קץ גם למעלה וכמבואר בארוכה כ\"ז בד\"ה בן פורת יוסף לאדמו\"ר הצ\"צ (נדפס בס' אור התורה שפ\"ו ע\"ב) ומדתו של הקב\"ה מדה כנגד מדה אלא שכ\"פ ככה שמוסיף אור (שזהו שם הכללי להארות והמשכות של מעלה) לאין קץ גם למטה בהמצטרך לכל המתעסקים בהנ\"ל הם ובני ביתם הן בגשמיות והן ברוחניות.</p>\n<p>בברכת חג הגאולה י\"ב וי\"ג תמוז הבע\"ל אשר בודאי יחוגו אותו באופן המתאים בבית הכנסת שלהם ויה\"ר שיהי' בהצלחה מופלגה בהנוגע להבפועל.</p>"],[1200830141,"ב'תשנט\n\n<p>ב\"ה, כ\"ט סיון, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ג והרה\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמוה\"ר נחום שמרי' שי'</p>\n<p> שלום וברכה!</p>\n<p>נתקבלו שני מכתביו מי\"ב סיון, והנ\"ל הוא העתק ממכתבי למתפללי ביהכ\"נ בית יוסף, ונשלח לו כיון שהוא מהמשתתפים בההתועדות שם ובטח ינהג כזה ג\"כ בחג הגאולה הבע\"ל.</p>\n<p>בברכה.</p>\n<h4><i><b>ב'תשנט</b></i></h4>\n<p><b> מוה\"ר נחום שמרי':</b> ששנוקין, אגרות נוספות אליו - לעיל ח\"ג תקצג, ובהנסמן בהערות שם.</p>"],[1200830142,"ב'תשס\n\n<p>ב\"ה, כ\"ט סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>... נראה ממכתבו, שסדר קבוע אצלו <b>להתחיל</b> התפלה בש\"ק בוקר - בחצות היום! ולא נ\"ל כלל סדר כזה (אף שבודאי אומר ק\"ש לפני זה וכן שמע ברכו וכו'). ושאני אם מתחילים במוקדם ומאריכים בתפלה. ומה טוב להתחיל עם הצבור לערך, ומב\"ש ואילך לאחר גמר תפלת הצבור.</p>"],[1200830143,"ב'תשסא\n\n<p>ב\"ה, כ\"ט סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו הודעתו מיום הולדתו שלו. ובודאי ידוע לו הנהגה בעלי' לתורה, לימוד שיעור נוסף הן בתורת הנגלה והן בתורת החסידות נוסף על השיעורים הרגילים ושלשת השיעורים השוים לכל נפש דחת\"ת ומקיימם, הנה יה\"ר מהשי\"ת שתהי' שנה זו שנת הצלחה אצלו בלימוד הנגלה ובלימוד פנימיות התורה וקיום המצות בהידור אשר כל זה תלוי במסירה ונתינה אמיתית לכל הנ\"ל בנוגע לעצמו, ובודאי משפיע ג\"כ על חבריו שיתאמצו במסירה ונתינה זו ובפרט בימינו אלה אשר כפתגם כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע הנה זה עומד אחר כתלנו ואשר עי\"ז יתקיים בהקדם היעוד המקווה שיהפכו ימים אלו לששון ולשמחה.</p>\n<p>בברכה,</p>\n<p>נ.ב.</p>\n<p>בודאי עכ\"פ מכאן ולהבא הנה ילמוד דא\"ח גם בלילה.</p>\n<h4><i><b>ב'תשסא</b></i></h4>\n<p><b> ידוע לו הנהגה:</b> ראה גם לעיל אגרת ב'עתר, ובהנסמן בהערות שם.</p>"],[1200830144,"ב'תשסב\n\n<p>ב\"ה, כ\"ט סיון, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ח אי\"א נו\"נ כו' מוהר\"א חנוך שי'</p>\n<p> שלום וברכה!</p>\n<p>... נכון הדבר במאד שכמו וכדרך שסידר תולדות רבנו הזקן מלוקטים משיחות כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע ביחד עם הידיעות שבס' בית רבי, יעריך כזה גם בנוגע לאדמו\"ר האמצעי וכן בנוגע להצמח צדק, וכמעשהו בראשון כן מעשהו בשני אלו ובמשך הזמן אפשר יהי' לחשוב גם בנוגע לכ\"ק מוהר\"ש בכגון דא מיוסד על הקטעים שבספר תולדות מוהר\"ש והר\"פ דשם בהוספה מה שנדפס מאז ועד עתה. ותקותי שבמשך קיץ זה יופיע לאור ספר שיחות תש\"א ותש\"ב אשר גם בהם חומר בהנוגע לכל הנ\"ל.</p>\n<p>בשאלתו אם להדפיס בבטאון הבע\"ל רשימת כ\"ק מו\"ח אדמו\"ר ע\"ד התקופה שלפני המאסר, הנה בבטאון אין זה מקומו כיון שלהדפיס בהשמטת קטעים מסוימים אין זה דרך ובהבטאון יתבלטו אלו הקטעים ביותר כיון שאין זה אלא חוברת קטנה לפ\"ע, משא\"כ בס' קובץ מכתבים בעל מאות עמודים. ויש ללמוד בזה בנין אב ממה שאירע ע\"י הדפסת מכתב כ\"ק מו\"ח אדמו\"ר בחילוק אופן הלימוד דחסיד ומתנגד וכמו שכתבתי מכבר במכתבי לצעירי אגו\"ח.</p>\n<p>בטח נו\"ל כאן לי\"ב תמוז הבע\"ל המשך רשימת כ\"ק מו\"ח אדמו\"ר ע\"ד המאסר בחוברת בפ\"ע.</p>\n<p>בהנוגע לעיר הולדתי היא ניקאלאייעוו ולא יעקאטרינסלב.</p>\n<h4><i><b>ב'תשסב</b></i></h4>\n<p><b> מוהר\"א חנוך שי':</b> גליצנשטיין. אגרות נוספות אליו - לעיל ח\"ח ב'רנט, ובהנסמן בהערות שם.</p>\n<p><b> וכדרך שסידר:</b> ראה לעיל שם.</p>\n<p><b> רשימת... שלפני המאסר</b><b>:</b> שבאג\"ק ח\"א אגרת שמ.</p>\n<p><b> שכתבתי מכבר</b><b>:</b> ראה לעיל אגרות ב'תרכה. ב'תרפח.</p>"],[1200830145,"ב'תשסג\n\n<p>ב\"ה, כ\"ט סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מיום א' שבוע זה ונהניתי לקרות בו אשר משבחים את בניו בלימודיהם בתורה ויה\"ר מהשי\"ת שיהי' זה בפועל כמרז\"ל לא המדרש עיקר אלא המעשה שהלימוד יביא לידי קיום המצות בהידור ומובןשאשר מוכרח הדבר שילמדו ג\"כ חסידות שאז נתקיים הענין דיראת ד' היא אוצרו שעי\"ז נשמר ג\"כ לימוד התורה כמבואר בדרז\"ל (שבת לא, סע\"א) ובודאי פשיטא בכדי שיתקבלו דרכים אלו אצל בניו שיחיו צריך שיהי' גם לו שיעור קבוע <b>בלימוד</b> החסידות, ומדגיש הנני בלימוד ולא קריאה ועיון מזמן לזמן כי ידוע הפס\"ד יגעת ולא מצאת אל תאמין, והאריכות אך למותר...</p>\n<p>בברכה לבשר טוב בכל הנ\"ל.</p>\n<p>נ.ב.</p>\n<p>מ\"ש אודות משרה טובה ויפה בשבילו, הרי בודאי ידוע לו המצב במשרות כמו אלו בהערים כמו נויארק וכו' שהמחפשים משרות מספרם הרבה יותר מאשר המשרות.</p>\n<p>ולהחליף משרתו עתה למשרה בעיר קטנה לכאורה מה היא התועלת בזה.</p>"],[1200830146,"ב'תשסד\n\n<p>ב\"ה, כ\"ט סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מי\"ד סיון, הנה אף שקודם קבלת התורה הנה עמא פזיזא הי' מעלה וכמבואר ברז\"ל (שבת פט, ע\"א) אבל בכלל לאחר קבלת התורה (והכוונה בזה גם בכל יום ויום וכמבואר בדא\"ח בדיוק בברכת התורה בברכות השחר נותן התורה לשון הווה) ובפרט בעבודה תמידית צ\"ל מסודרה ובלי פזיזות ובמילא עליו להתעסק בעניני פרנסתו עתה בהשתדלות המתאימה מבלי שתבלבל בשעת מעשה הסברא להכנס בעבודת הישיבה, וכשישתפר המצב בהישיבה כמ\"ש במכתבו הרי אז הזמן לחשוב בפרטי ואופני עבודה שם וכן ע\"ד החלטה בכללות והשי\"ת יחזקו בשמירת הקביעות עתים בתורת הנגלה והחסידות שגם זה יוסיף ברכה והצלחה בעניני פרנסתו.</p>\n<p>בברכה.</p>"],[1200830147,"ב'תשסה\n\n<p>ב\"ה, כ\"ט סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> ברכה ושלום!</p>\n<p>איך האב באקומען דיין בריף פון ט\"ו סיון, אין וועלכען דו שרייבסט פון דיין געבורסט טאג.</p>\n<p>השם יתברך זאל דיר העלפען, אז עס זאל זיין א הצלחה יאר בא דיר סיי בגשמיות און סיי ברוחניות, און האפענטליך וועסט דו זעהען צו איינווירקען אויף דיינע חברות און פריינדינעס צו מאכען זיי נעהענטער צו אידישקייט און מקיים זיין מצות בפועל, וואס דער זכות פון דעם איז זייער גרויס און דער וואס טוט אין דעם זאל געהאלפען ווערען אין דעם וואס ער באדארף, זיכער קענסט דו גלייכצייטיג באקענען דיינע חבירות מיט דער מסירת נפש-דיקער אויפפירונג פון חסידישע הייזער, און וואס יעדער איד פארמאגט דעם כח פון מסירת נפש. און ווען מען רעט איינמאל און מערערע מאל ווירקט דאס און מען טוט אויף.</p>\n<p>בברכה ופ\"ש לחבירותך אז זיי זאלן מצליח זיין בכל הנ\"ל און אויך אז יעדערע פון אייך זאל משפיע זיין אין איר סביבה צו תורה און אידישקייט.</p>"],[1200830148,"ב'תשסו\n\n<p>ב\"ה, כ\"ט סיון, תשי\"ד</p><p>ברוקלין.</p><p>האברך הוו\"ח אי\"נ נו\"נ עוסק בצ\"צ<br>\nמוה' יעקב אליעזר שי'</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מט' סיון ות\"ח על הבשו\"ט ע\"ד הישיבה שכותב תודה על העבר ובקשה על להבא להמשיך בכגון דא והשי\"ת יצליחו.</p>\n<p>ב) בהנוגע לשאלתו אם הנהלת הישיבה תלך בתוקף בכל דבר עם התלמידים וההורים שלהם. הנה אין שייך לתת בזה הוראות כלליות כי מובן שהדבר תלוי בהפרט עליו נדונים, שאם הוא ענין עיקרי אין לוותר עליו אבל גם אז צריך ללכת בזה בדרכי נועם ובדרכי שלום שאז בנקל יותר צו אויספירען, ולמותר להוסיף שבמקום שיש חשש דהיזק הרבים הרי זה מבטל סברת תועלת היחיד, וכפי שהראה הנסיון במקומות אחרים הנה כשחברי ההנהלה דמוסד חינוך מתייעצים ביניהם הרי ברובא דרובא מוצאים האותיות המתאימות איך להסביר לההורים והתלמידים נחיצות ציווי או פקודה פרטית איך שזהו תועלת הכלל ותועלת הפרט...</p>\n<p>בברכת הצלחה בענינים הכללים ובעניניו הפרטים.</p>\n<h4><i><b>ב'תשסו</b></i></h4>\n<p><b> מו\"ה יעקב אליעזר</b><b>:</b> הרצוג, מלבורן.</p>\n<p>ב'תשסז</p>\n<p><b> מוה\"ר שלמה חיים:</b> קסלמן. אגרות נוספות אליו -לעיל ח\"ח ב'רנח, ובהנסמן בהערות שם. לקמן ב'תתנה. ב'תתקכד.</p>\n<p><b> וכ\"כ:</b> וכבר כתבתי.</p>"],[1200830149,"ב'תשסז\n\n<p>ב\"ה, כ\"ט סיון, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמוה\"ר שלמה חיים שי'</p>\n<p> שלום וברכה!</p>\n<p>.... נתעכב מכ' זה ובנתיים הגיעו מכתביו מטו\"ב וכ\"ד סיון. וכ\"כ שקשה להתערב מכאן בחילוק המשרות והתפקידים, שזה צריך בחינה על אתר, ועליהם להתדבר בזה ביניהם ולנצל את כחותיו של כאו\"א ככל האפשרי.</p>\n<p>ע\"ד החופש - כבר עניתי. ופשיטא שאין מקום לחופש ב' פעמים.</p>\n<p>בנוגע לתוכן ההתועדויות שלו - יישר חילי' שמדבר ע\"ד עבודת התפלה ולימוד דא\"ח. ותימה גם על הקס\"ד שעתה א\"צ לזה, ח\"ו. אלא, שלאידך גיסא, <b>מוכרח</b> לימוד הנגלה בעיון ובהתמדה. וגם אין אחר מדבר עד\"ז עם הת', הרי ידוע פסק רז\"ל במקום שאין אנשים השתדל כו', ומקום יש בראש כו'. והשי\"ת יצליחו.</p>"],[1200830150,"ב'תשסח\n\n<p>ב\"ה, כ\"ט סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>עס איז ערהאלטען געווארען אייער בריף פון ו' סיון און אויך דער פריערדיקער, און וויבאלד אייך קומט אויס צו זיין א ליינגערע צייט בא דער ארבעט, וואלט איר באדארפט וויסען אויף אויסווייניג עטליכע פרקים משניות און עטליכע פרקים תניא און אויך תהלים און גייענדיק צו דער ארבעט אדער פון דער ארבעט און אויך בא דער ארבעט אליין אין די פרייע צייט אריינחאפן און חזר'ן עפעס אויף אויסווייניג פון די אויבען דערמאנטע. און עס איז ידוע דער ביאור אויף דעם מאמר רז\"ל לעולם יהא אדם זהיר בתפלת המנחה, אז דאס וואס מען לערנט און מען דאווענט אין אזא צייט האט א באזונדער חביבות און א זכות גדול ביותר אויף צו אויפטאן און ממשיך זיין דאס וואס יעדער נויטיגט זיך, סיי בגשמיות און סיי ברוחניות. און השי\"ת זאל ערפילען משאלות לבבו ולבב זוגתו שיחיו לטובה בקרוב בזחו\"ק.</p>\n<p>בברכה.</p>"],[1200830151,"ב'תשסט\n\n<p>ב\"ה, כ\"ט סיון, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ג והרה\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמוה\"ר חיים שאול שי'</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מכ\"ב סיון, ויזכהו השי\"ת לבשר במכתבו הבא, שמטוב הולך לעוד יותר טוב, הן בעניניו הפרטים והן בענינים הכללים - להגדיל תורה ולהאדירה, וכבר כתבתי לאחד שמקרא זה מובא בשני הקצוות דת\"ת, הן בלימוד תשב\"ר (רמב\"ם הל' ת\"ת ס\"פ ב') וכן בלימוד התורה שהיא למעלה לגמרי אפילו מענין המצות (חולין פו, ע\"ב) - היינו שלא רק מן הקצה אל הקצה, שכיון שמוגבל הוא בשני קצוות הרי נקרא קטן, וכמו שנאמר ביעקב - המבריח מן הקצה אל הקצה - כי קטן הוא אלא למעלה מהקצוות ולמעלה מהמדידה והגבלה איזה שתהי', וכמבואר בדא\"ח בכ\"מ.</p>\n<p>בברכת הצלחה בכל הנ\"ל - המחכה לבשו\"ט.</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ב'תשסט</b></i></h4>\n<p><b> מוה\"ר חיים שאול:</b> ברוק. אגרות נוספות אליו - לעיל ח\"ח ב'שדמ, ובהנסמן בהערות שם.</p>\n<p><b> וכבר כתבתי:</b> לעיל אגרת ב'תרפט.</p>"],[1200830152,"ב'תשע\n\n<p>ב\"ה, כ\"ט סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>שמחתי לקבלת מכתבו מכ\"ט <b>אייר</b> שנתקבל רק היום - ואולי יש איזה שגיאה ברשימת הזמן - יה\"ר שגם להבא יבשר בהנוגע לבריאות אז פון גוט זאל ווערן בעסער וכידוע שבכל דבר שבקדושה והרי גם גוף הישראל קנין הקב\"ה (רמב\"ם הל' רוצח פ\"א ה\"ד) הנה צ\"ל מעלין בקדש.</p>\n<p>כבקשתו אזכיר ואת זוגתו שיחיו להטבת הבריאות ולבשו\"ט במקומם עתה ובמקומם החדש.</p>\n<p>בברכה.</p>"],[1200830153,"ב'תשעא\n\n<p>ב\"ה, כ\"ט סיון, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>... ומה שכותב שקשה לו להגביר את כח המחשבה דבור ומעשה שלו כמצוה עלינו בתורתו הק' תורת חיים ותורת עולם ושואל אנה לפנות ואנה לברוח - הנה אין צריך לברוח, כי כלשון התניא קדישא פרק מא: ה' נצב עליו ומלא כל הארץ כבודו ומביט עליו, ובוחן כליות ולב אם עובדו כראוי, אשר זהו גופא הוא נתינת כח לעמוד במלחמת היצר ולנצחה, וגם התבוננות קלה בזה מספיקה, וכדי להגדיל את הסייעתא דשמיא בזה צריך להיות חקוקים במוחו ובזכרונו איזה פרקים משניות ואיזה פרקים תניא והדרוש בלקוטי תורה סוף פ' קדושים ד\"ה והדרת פני זקן, וזהו נוסף על מה שצריך להיות אצלו בכיסו - כמובן במקומות שמותר זה - תניא, ומזמן לזמן בשעות הפנויות ילמוד בו איזה שורות, ואם יעשה ככל הנ\"ל אליבא דנפשי' ויזכיר לעצמו הציווי התמידי דשוויתי ה' לנגדי תמיד, הרי לאט לאט יגרש הרע ויגביר האור בהד' אמות שלו.</p>\n<p>בטח מרציא מזמן לזמן מצבו הרוחני לפני המשפיע שלומד אצלו דא\"ח ועושה כהוראתו ואחכה לבשו\"ט.</p>\n<p>בברכה,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<h4><i><b>ב'תשעא</b></i></h4>\n<p>נדפסה בלקו\"ש חי\"ז ע' 500, והוגהה ע\"פ העתק המזכירות.</p>"],[1200830154,"ב'תשעב\n\n<p>ב\"ה, כ\"ט סיון, תשי\"ד</p><p>ברוקלין.</p><p>[הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמוה\"ר יהושע שניאור זלמן שי'].</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מיו\"ד סיון, ובטח בינתים קבל מכתבי בו ימצא מענה על כמה מהשאלות שלו, ותחלת מכתבי זה היא נקודה כללית רובא דרובא המכתבים שלהם הם מלאים תוכן איך שקשה וכמעט אי אפשר לסדר ישיבה במקומם כו' וכמו שכתב במכתבו הקודם, הנה זה למרות שראו מופתים גלוים איך שבכל הדברים שלא הי' תלוי בחירה מבני ישראל ראו הצלחה מופלגה, ואם היו קישויים ה\"ז רק באותן הנקודות שהיתה יד בני ישראל בכלל ובפרט אנ\"ש שיש להם בחירה חפשית כיון שהם בדוגמא שלמעלה (שרק שם הוא מקום הבחירה האמיתית וכמבואר בלקו\"ת פ' אמור לח: בביאור עה\"כ הן האדם הי' כאחד ממנו), הרי שם נמצאו העלמות והסתרים וכו'...</p>\n<p>בנוגע לשאלתם אם לעשות ת\"ת לקטנים או להסתפק רק בהדעי סקול הנה פשוט שצריך לעשות ת\"ת לקטנים ג\"כ, ובפרט שבספק הדבר אם אפשר שתהי' מספקת כמות המבקרים בהדעי סקול אם לא ע\"י שיקרבו את הנערים בחינוכם מקודם בת\"ת וחדרים...</p>\n<p>בהנוגע לשיתוף פעולה עם אברכים מישיבה אחרת או עם אנשים מחוג אחר שעד עתה הנה נהגו אתם ברצו\"ש, הנה אף שידוע ההנהגה שצריך לקבל את כל אחד בספ\"י וצריך לנצל את כחותיו של כאו\"א בכרם חב\"ד ככל האפשרי אפילו מאלו שאינם מחב\"ד אבל בענין עשיית שותפות גמורה ובמילא יש להשותפים דיעה גמורה ולעתים גם דיעה מכרעת, הנה יש להזהר בזה ביותר וביותר ובפרט במדינה [...] שתלוי בזה גם קידוש ליובאוויטש כו' ומובן שכל הנ\"ל אינו שייך להענין דקליטת תלמידים גם מחוגים הנ\"ל ואין הדבר אמור אלא בכאלו שיחוו דיעה.</p>\n<p>מובן שאין לעשות בבנין הישיבה ענינים של מפלגה איזה שתהי' אף שלאידך גיסא אין מענינם לבדוק את אלו הבאים אליהם להתפלל או ללמוד אם שייכים הם להמפלגה, אבל הבנין וכל הענינים הקשורים בו הם <b>על</b> מפלגתי כמובן.</p>\n<p>וה\"ה בנוגע להנוסח, פשוט שבבנין ישיבה שעל שם כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע נוסח התפלה צ\"ל נוסח שלו, ואין בזה <b>שום</b> פגיעה בכבודו של מי שהוא כי לכל אחד מובן הענין דהגם לכבוש את המלכה עמי בבית, וכיון שנקרא הבנין והישיבה ע\"ש כ\"ק מו\"ח אדמו\"ר צ\"ל מתאים אליו, אבל לאידך גיסא אין הם מחוייבים לבדוק את כאו\"א באיזה נוסח מתפלל כו' ובמילא מובן גם כן שאם בדרך ארעי ירד מי לפני התיבה ויתפלל נוסח אחר הרי אין זה ענין למלחמה.</p>\n<p>כנ\"ל הנני כופל עוד הפעם שיש לקלוט תלמידים להישיבה אף אם חוששים הם שהתלמידים ישארו רק באופן זמני כי נוסף ע\"ז שאם ישפיעו על התלמידים כדבעי ישארו בקביעות עכ\"פ רובם, הנה גם בשביל השפעה ביר\"ש טהורה באופן זמני כדאי הדבר.</p>\n<p>בהנוגע לסיום מכתבו שצער אנ\"ש ביותר גדול מזה שהם רואים שאפשר להצליח והחסרון שאין אנשים המתאימים לזה, הנה כיון שההשגחה העליונה הביאה דוקא אותו ל[אוסטרליא] ולא אחרים והראתה מופתים גלוים... הנה <b>ברור</b> הדבר שיש היכולת ביד אנ\"ש הנמצאים ב[אוסטרליא] לעשות ככל הדרוש, ויה\"ר מהשי\"ת שיוציאו יכולת זו מהכח אל הפועל ושיהי' זה בהקדם ובנקל.</p>\n<p>בברכת הצלחה המחכה לבשו\"ט ופ\"ש כהדו\"ש.</p>\n<h4><i><b>ב'תשעב</b></i></h4>\n<p><b> מוה\"ר יהושע שניאור זלמן שי</b><b>':</b> סרברנסקי. אגרות נוספות אליו - לעיל ב'תרפא, ובהנסמן בהערות שם.</p>\n<p><b> מכתבי:</b> דלעיל ב'תשכז.</p>"],[1200830155,"ב'תשעג\n\n<p>ב\"ה, א' תמוז, תשי\"ד</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ עוסק בצ\"צ מוה\"ר משה שי'<br>\nהכהן</p>\n<p> שלום וברכה!</p>\n<p>בנועם קבלתי מכתבו מכ\"ח סיון, בו כותב אודות הטבת מצב בריאות זוגתו תחי'.</p>\n<p>ויה\"ר אשר בחדש גאולה של נשיאנו כ\"ק מו\"ח אדמו\"ר, הנה נגאל, כאו\"א מאתנו, מכל ענינים המבלבלים ממנוחת הנפש והרחבת הדעת, והרי לב כל ישראל ער הוא להקב\"ה תורתו ומצותיו ולגאולה, וכמבואר במדרש שה\"ש רבה על הפסוק אני ישנה (בגלותא) ולבי ער.</p>\n<p>והשי\"ת יצליחו, שכמו שכותב במכתבו שמוסיף בלימוד החסידות, שכוונתו בזה על עצמו, הנה ישתדל בכל יכולתו שיתוסף בלימוד זה גם בבית הכנסת, בתלמוד תורה דרבים, ויהי' אופן הלימוד בחקיקה, שמבואר מעלתה בכ\"מ, וראה של\"ה פרש[ה] זו, וביאורו בלקו\"ת בפרשתנו וכן בפ' בחקותי.</p>\n<p>ברכת הצלחה בכל הנ\"ל,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ב'תשעג</b></i></h4>\n<p>נדפסה בלקו\"ש חכ\"ג ע' 521, והושלמה ע\"פ צילום האגרת.</p>\n<p><b> מוה\"ר משה:</b> שאייעוויטש. אגרות נוספות אליו - לעיל ח\"ז א'תתקנא, ובהנסמן בהערות שם.</p>"],[1200830156,"ב'תשעד\n\n<p>ב\"ה, א' תמוז, תשי\"ד</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>בעתו קבלתי שני מכתביו מה' סיון. ומ\"ש אודות כשרות השמורה שקנה ומצרף גם תעודת הכשר. הנה לפלא שכנראה תפסו את כל הענין שלא לפי כוונתי <b>כלל וכלל</b> כי לא דברתי דבר ע\"ד כשרות השמורה אלא אודות ענין ההתקשרות שזהו תלוי באופן האמונה בנשיאנו כ\"ק מו\"ח אדמו\"ר.</p>\n<p>וכבר ידוע סיפור כ\"ק מו\"ח אדמו\"ר אשר בעת מאסרו של רבנו הזקן אמר, אז ער האט זיך מוסר נפש געווען בפועל שלא להיות נפרד מהבעש\"ט <b>בתנועה</b> אפילו לשעה קלה ואפילו רק למראית עין (עיין באריכות במכתב הנדפס בחוברת התמים חלק ב' עמוד 56). ואף כי מי הוא זה ואיזהו אשר ערב לבו לגשת להשיג אפילו חלק אחד מני אלף ממדריגת רבנו הזקן, הנה ע\"ד המובא בתניא פרק מ\"ד אפס קצהו ושמץ מנהו מרב טובו ואורו מאיר לכללות החסידים ואנ\"ש.</p>\n<p>ויש לסיים ע\"ד האמור במכתב כ\"ק מו\"ח אדמו\"ר (שם סוף פרק ב) שאם בדברים כמו אלו צריכה להיות הדביקות כ\"כ הנה במיכלא ד[מ]הימנותא ובמיכלא דאסוותא ובליל שמורים שנתגלה על כאו\"א מבני ובנות ישראל בכבודו ובעצמו עאכו\"כ.</p>\n<p>ותקותי שעכ\"פ עתה מובן עד כמה שאינו שייך כלל בכגון דא <b>כל</b> מה שכותב אודות כשרות השמורה וכן אודות תהלוכות הדברים איך שבא השמורה לידו כו' וכו', והאריכות בזה אך למותר.</p>\n<p>בברכה.</p>\n<h4><i><b>ב'תשעד</b></i></h4>\n<p>לתוכנה ראה לעיל אגרת ב'תרעט.</p>"],[1200830157,"ב'תשעה\n\n<p>ב\"ה, א' תמוז, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ח אי\"א נו\"נ עוסק בצ\"צ מוה\"ר יעקב<br>\nשי' הלוי</p>\n<p> שלום וברכה!</p>\n<p>בנועם הגיעני מכתבו מג' חקת עם הפ\"נ המוסגר בו אשר יקרא בעת רצון על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע.</p>\n<p>נהניתי לקרות במכתבו אשר בעוד שני מנינים אומרים תהלים אחר התפלה ע\"פ תקנת כ\"ק מו\"ח אדמו\"ר כפי שנחלק לימי החדש. ויהי רצון שיקויימו בהמקיימים תקנה זו בתוך כלל ישראל כל הענינים הבאים על ידי אמירה זו, וכמבואר במכתבי כ\"ק מו\"ח אדמו\"ר שנדפסו בקובץ תהלים.</p>\n<p>וגדול זכות אלו שהביאו והשתדלו בזה שזכות הרבים תלוי בם להשפיע להם תוספת ברכה והצלחה בהמצטרך להם ולבני ביתם הן בגשמיות והן ברוחניות. ואחכה לבשו\"ט משמחות בכל הנ\"ל.</p>\n<p>בברכה לבריאות הנכונה והצלחה בעסקנותו בהרמת קרן ישראל סבא מתוך בריאות הנכונה והרחבת הדעת.</p>\n<h4><i><b>ב'תשעה</b></i></h4>\n<p><b> מוה\"ר יעקב שי</b><b>':</b> פרידמן.</p>"],[1200830158,"ב'תשעו\n\n<p>ב\"ה, א' תמוז, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ג והרה\"ח אי\"א נו\"נ כו' מוה\"ר שמואל<br>\nשי'</p>\n<p> שלום וברכה!</p>\n<p>בנועם נמסרה לי הידיעה אשר בש\"ק זה הוא הברית מילה של נכדו ב[ן] בתו חנה עטל תחי'. ויה\"ר מהשי\"ת שיזכו הוריו להכניסו לבריתו של אברהם אבינו בשעה טובה ומוצלחת, וכשם שיכניסוהו לברית כן יכניסוהו לתורה ולחופה ולמעשים טובים.</p>\n<p>וכבר ידוע פס\"ד רבנו הזקן בעל התניא (פוסק בנסתר דתורה) והשולחן ערוך (פוסק בנגלה דתורה) בשולחנו הטהור מהדו\"ב סוף סימן ד', אשר במצות מילה הוא תחלת כניסת נפש הקדושה בגוף הישראלי,</p>\n<p>וידוע פתגם כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, אשר כידוע הנה חמשה שמות נקראו להנשמה, נפש רוח נשמה חי' יחידה, וכשעושים ענין דתורה ומצוה בעולם למטה בעולם הזה עולם העשי' כמו\"כ נעשה זה ברוח נשמה חי' בעולמות יצירה בריאה ואצילות, און אז דאס אלץ דערהערט זיך אין יחידה כמו שהיא בעולמות הא\"ס שלמעלה מאצילות, ואפילו כזה שאינו יודע כללות הענין, אבער מכל מקום דער ענין טוט זיך אפ אין אלע עולמות כו', וע\"ז נאמר וצדקתו עומדת לעד, אז ער האט א קאפיטאל אין עולמות עליונים און מיט דער צייט וועט ער וויסען פון דעם אויך (שיחתו י\"ט כסלו תרצ\"ג אות י\"ז).</p>\n<p>ויה\"ר מהשי\"ת אשר הוא וזוגתו שיחיו ירוו מהם ומכל יו\"ח שיחיו רוב נחת חסידותי לאריכות ימים ושנים טובות.</p>\n<p>בברכת מזל טוב.</p>\n<h4><i><b>ב'תשעו</b></i></h4>\n<p>נדפסה בלקו\"ש ח\"ז ע' 305, והושלמה ע\"פ העתק המזכירות.</p>\n<p><b> מוה\"ר שמואל:</b> יאלאוו. אגרת נוספת אליו - לעיל ח\"ז ב'ס.</p>"],[1200830159,"ב'תשעז\n\n<p>ב\"ה, א' תמוז, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ מוה\"ר<br>\nאברהם שי'</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מכ\"א וכ\"ז סיון (וכן הקודמים לו מל' ניסן ד' י\"ט כ\"ד אייר וה' סיון אף שכמדומה כבר אשרתי קבלתם), הנה בהנוגע לעניני הרשת ועניני ישיבת תו\"ת בלוד - בודאי כבר נתקבלו מכתבי מענה אליהם וקרא אותם. ובכלל הנה תמיהני שבענינים פשוטים וברורים, הרי לפעמים טועים מן הקצה אל הקצה, היפך שיטת ליובאוויטש במשך כל הזמן. ויה\"ר שעכ\"פ מכאן ולהבא ישתנו הדברים.</p>\n<p>מצער אותי במאד מאד, שכנראה, הספרים שנשלחו מכאן אין מפיצים אותם כדבעי וי\"א שאין מתעסקים בהפצתם כלל וכלל, ומה יהי' סוף דבר מהנהגה כמו זו - קשה לי לשער. ומזמן לזמן, הנני נזכר על פתגם כ\"ק מו\"ח אדמו\"ר, שבקרוב יבוא הזמן, ימים שאין בהם חפץ שהם ימות המשיח, און מען וועט זיך חאפען פארן קאפ, שזה עתה הי' זמן שהיו יכולים לפעול כו\"כ און מען האט דאס דורכגעלאזען אזא זמן. וכמדומה שגם הוא הי' בעת התועדות זו...</p>\n<p>כתבתי לאגו\"ח בתל אביב, ששמעתי שישנם כתבי יד (ואולי גם גוף הכתב יד) אצל נכדי הרש\"נ ע\"ה מבאברויסק וכן אצל נכדי השזב\"ן ש\"ס, ובקשתי שאם יתברר שאמת כן הוא ויש בכתב יד אלו ענינים שלא נדפסו - להשיג את הנ\"ל ולשלחם לכאן. ואם אי אפשר אחרת - הרי עכ\"פ למשך זמן...</p>\n<p>כיון שאינו מזכיר דבר מבריאותו ומבריאות ב\"ב - שיחיו - הרי בודאי כאו\"א מהם הוא בבריאות הנכונה. ובכ\"ז אחכה לבשו\"ט בפירוש.</p>\n<p>בברכה,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ב'תשעז</b></i></h4>\n<p><b> מוה\"ר אברהם</b><b>:</b> פריז. אגרות נוספות אליו - לעיל ב'תרמז, ובהנסמן בהערות שם.</p>\n<p><b> הספרים שנשלחו מכאן</b><b>:</b> ראה לעיל שם, ובאגרת ב'תערב. לקמן ב'תתכו.</p>\n<p><b> פתגם</b><b>:</b> ראה גם לעיל ח\"ח אגרת ב'תקיז, ובהנסמן בהערות שם.</p>\n<p><b> כתבתי לאגו</b><b>\"</b><b>ח</b><b>:</b> לעיל ב'תשלט.</p>"]]});
